export const usCatalog: UsCatalogSeed[] = [{"id":"007-the-world-is-not-enough","title":"007: The World Is Not Enough","year":2000,"genres":["Shooter","Stealth"],"description":"Experience the intensity of being the world's top secret agent. Equipped with a full arsenal of of Q-Lab gadgets and weaponry, you must be suave, resourceful, and lethal as you carry out action-packed missions based on the blockbuster movie. Are you cool under pressure? Deadly when necessary? Of course you are -- you're Bond...James Bond.","descriptionSource":"http://www.gamefaqs.com/n64/914163-007-the-world-is-not-enough","developer":"Eurocom Entertainment Software","coverName":"007 - The World Is Not Enough (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":3.72,"count":331}},{"id":"1080-teneighty-snowboarding","title":"1080 TenEighty Snowboarding","year":1998,"genres":["Sports","Alternative","Snowboarding"],"description":"You're taking a Tahoe 155 snowboard down a steep, bumpy incline at night and you're about to top off an Indy Nosebone with a 360 Air, and you haven't even left your living room! You're playing 1080 (Ten Eighty) Snowboarding, a game so intense you'll be brushing the snow off your goggles. With five different boarders, eight different Lamar snowboards, more than 25 tricks, a Half-Pipe and six different courses, this is as close as you'll get to the real thing without hopping on the next ski lift.","descriptionSource":"http://www.gamefaqs.com/n64/196500-1080-teneighty-snowboarding","developer":"Nintendo","coverName":"1080 TenEighty Snowboarding (Japan, USA) (En,Ja).n64","players":null,"publisher":null,"esrb":null,"rating":null},{"id":"a-bug-s-life","title":"A Bug's Life","year":1999,"genres":["Platformer"],"description":"Based on the animated film, A Bug's Life is an epic game of miniature proportions.The story follows the exciting adventures of a misfit ant named Flik as he tries to save his colony from a greedy gang of grasshoppers led by Hopper.As Flik, you travel through fully interactive 3D environments brought to life with cinematic quality animation, smooth controls, and challenging puzzles.Get ready for a bug's-eye-view in an incredible and fast-paced adventure.","descriptionSource":"http://www.gamefaqs.com/n64/196523-a-bugs-life","developer":"Traveller's Tales","coverName":"Bug's Life, A (USA).n64","players":"1","publisher":"Activision","esrb":"E - Everyone","rating":{"score":3.33,"count":95}},{"id":"aerofighters-assault","title":"AeroFighters Assault","year":1997,"genres":["Flight","Shooter"],"description":"The AeroFighters Assault team needs your help to save the Earth from the evil Phutta Morgana and their machines of doom. Engage a variety of enemy aircraft and boss characters around the globe in multiple missions. Join the battle in the only game that matters!","descriptionSource":"http://www.gamefaqs.com/n64/196549-aero-fighters-assault","developer":"Paradigm Entertainment","coverName":"AeroFighters Assault (USA).n64","players":"2","publisher":"Video System","esrb":"E - Everyone","rating":{"score":3.27,"count":150}},{"id":"aerogauge","title":"AeroGauge","year":1998,"genres":["Racing"],"description":"Blaze through the skies as you take control of your very own Aeromachines in this new futuristic racing game, AeroGauge. With courses that have sharp turns, and even sharper obstacles, it is going to take a keen eye and ultimate control to maneuver through courses featuring canyons, tunnels, oceans, and mountains. Imagine speeds reaching over 1000 mph as you whiz by the field in route to victory in these graphically advanced landscapes. Never has a game incorporated such remarkable control, detailed graphics, and mind-tingling speeds as...AeroGauge!","descriptionSource":"http://www.gamefaqs.com/n64/196550-aerogauge","developer":"Locomotive Corporation","coverName":"AeroGauge (USA).n64","players":"2","publisher":"ASCII Entertainment Software","esrb":"E - Everyone","rating":{"score":3.08,"count":160}},{"id":"aidyn-chronicles-the-first-mage","title":"Aidyn Chronicles: The First Mage","year":2001,"genres":["RPG"],"description":"Young Alaron is on a quest to discover the truth about himself, his name, and his heritage. Traveling to far and distant lands, pursued by forces he cannot understand, danger lurks around every corner. Alaron and his companions will seek to fulfill his destiny as the greatest mage ever known!","descriptionSource":"http://www.gamefaqs.com/n64/196565-aidyn-chronicles-the-first-mage","developer":"H2O Interactive","coverName":"Aidyn Chronicles - The First Mage (USA).n64","players":"1","publisher":"THQ","esrb":"T - Teen","rating":{"score":2.92,"count":101}},{"id":"air-boarder-64","title":"Air Boarder 64","year":1998,"genres":["Racing","Sports"],"description":"AirBoarder 64 is a Sports game, developed and published by Human Entertainment,which was released in Japan in 1998.","descriptionSource":"http://www.gamefaqs.com/n64/574480-airboarder-64","developer":"Human Entertainment","coverName":"Air Boarder 64 (Europe).n64","players":"2","publisher":"Human Entertainment","esrb":"Not Rated","rating":{"score":2.84,"count":75}},{"id":"all-star-tennis-99","title":"All Star Tennis 99","year":1999,"genres":["Sports"],"description":"All the power, speed and intensity of professional tennis! Compete against professional tennis' top talent: Michael Chang, Mark Philippoussis, Amanda Coetzer, Richard Krajicek, Conchita Martinez, Jonas Bjorkman, Gustavo Kuerten and '98 Wimbledon Champion Jana Novotna. Realistic courts and characters bring tennis to life. Smash overhead shots, crush 140mph serves and dive for cross-court volleys. Up to four players can go head-to-head simultaneously! Multiplayer options in singles, doubles and tournament play!","descriptionSource":"http://www.gamefaqs.com/n64/196587-all-star-tennis-99","developer":"Smart Dog","coverName":"All Star Tennis 99 (USA).n64","players":"4","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":3.16,"count":73}},{"id":"all-star-baseball-2000","title":"All-Star Baseball 2000","year":1999,"genres":["Sports"],"description":"You can learn the basics of baseball in an afternoon, then spend a lifetime mastering its intricacies. All-Star Baseball 2000 isn't quite so daunting, but expect to log lots of time on the Pause screens while you figure it out. Created by Iguana, ASB 2000 has the glossy graphics and excellent sound engineering you'd expect from the team that brought you All-Star Baseball '99, NFL Quarterback Club 99 and Turok 2. ASB 2000 supports hi-res graphics without the Expansion Pak. If you pop in an Expansion Pak, though, you'll witness extra-long replays.","descriptionSource":"http://www.gamefaqs.com/n64/196592-all-star-baseball-2000","developer":"Iguana Entertainment","coverName":"All-Star Baseball 2000 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.5,"count":67}},{"id":"all-star-baseball-2001","title":"All-Star Baseball 2001","year":2000,"genres":["Sports"],"description":"Over 700 Major League Baseball players and 30 stadiums including 5 new ballparks. Faster gameplay with Easy Batting / Pitching options. Hook slides, swipe tags, and home plate collisions. All-new Batting Practice mode lets you hone your skills. First ever Hall of Fame team including Nolan Ryan and Reggie Jackson. Full roster management includes: multi-player trades; create, sign and release players.Team stats in over 300 categories by STATS Inc.","descriptionSource":"http://www.gamefaqs.com/n64/250563-all-star-baseball-2001","developer":"High Voltage Software","coverName":"All-Star Baseball 2001 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.19,"count":59}},{"id":"all-star-baseball-99","title":"All-Star Baseball 99","year":1998,"genres":["Sports"],"description":"With All-Star Baseball '99, development house Iguana (Turok, NFL Quarterback Club '98) extends its sterling rep for putting great graphics on the N64. The high-resolution visual feast includes multiple player shadows during night games, digitized photos of most players and extremely detailed texture maps -- just check out the ivy and row houses at Wrigley! In stadiums with Jumbotrons, the action on the big screen replicates that on the field. The athletes are fully articulated, with nice use of shading that gives them a fully rounded look. Batters are graded on multiple characteristics, including whether they are pull, straightaway or opposite-field (push) hitters. Iguana has stacked the lineup with signature stances for everyone from Roberto Alomar to Sammy Sosa.","descriptionSource":"http://www.gamefaqs.com/n64/196585-all-star-baseball-99","developer":"Iguana Entertainment","coverName":"All-Star Baseball 99 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.01,"count":83}},{"id":"armorines-project-s-w-a-r-m","title":"Armorines: Project S.W.A.R.M.","year":1999,"genres":["Shooter"],"description":"You're an Armorine. You're wearing the latest in futuristic battle-armour. Armed with a devastating arsenal, you've got 120 hours to stop an all-out bug invasion of Earth. Or die trying.","descriptionSource":"http://www.gamefaqs.com/n64/196641-armorines-project-swarm","developer":"Acclaim","coverName":"Armorines - Project S.W.A.R.M. (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"T - Teen","rating":{"score":3.04,"count":102}},{"id":"army-men-air-combat","title":"Army Men: Air Combat","year":2000,"genres":["Shooter"],"description":"Pilot one of four toy helicopters through the treacherous terrain of your backyard, the local playground, picnic areas and nearby beaches. Engage in both air-to-air and air-to-ground combat with enemies ranging from battleships to butterflies. Utilize the unique abilities of each 'copter to battle armies of mutant insects; destroy rampaging remote control cars; blow up sand castles; and save Sarge from being melted by kids with magnifying glasses. Real combat. Plastic men.","descriptionSource":"http://www.gamefaqs.com/n64/196647-army-men-air-combat","developer":"3DO","coverName":"Army Men - Air Combat (USA).n64","players":"4","publisher":"3DO","esrb":"T - Teen","rating":{"score":3.59,"count":101}},{"id":"army-men-sarge-s-heroes","title":"Army Men: Sarge's Heroes","year":1999,"genres":["Shooter"],"description":"CONFIDENTIAL. 0600 hours: Tan forces captured Bravo Company Commandos. General Plastro has new weapons of mass destruction: magnifying glass, M-80 firecrackers and the garbage disposal. This is a job for Sarge. Requisition M-60s, shotguns, bazookas, flame throwers, grenades, sniper rifles, mortars, mine sweepers and plenty of ammo. Good luck, soldier.","descriptionSource":"http://www.gamefaqs.com/n64/196649-army-men-sarges-heroes","developer":"3DO","coverName":"Army Men - Sarge's Heroes (USA).n64","players":"4","publisher":"3DO","esrb":"T - Teen","rating":{"score":3.36,"count":107}},{"id":"army-men-sarge-s-heroes-2","title":"Army Men: Sarge's Heroes 2","year":2000,"genres":["Action","Shooter"],"description":"THE BOYS ARE BACK AND READY TO DO BATTLE! Sarge and the Bravo Company Commandos managed to foil the Tan Army's first assault, but do they have what it takes this time? General Plastro has teamed up with Brigitte Bleu, a diabolically treacherous Blue Spy, to destroy the Green Nation once and for all. The adventure continues as Sarge and Vikki fight their way over pool tables, around a bedroom and across desktops to the final showdown against Plastro and his troops. Prepare for another gigantic battle! It's Real Combat. Plastic Men.","descriptionSource":"http://www.gamefaqs.com/n64/340233-army-men-sarges-heroes-2","developer":"3DO","coverName":"Army Men - Sarge's Heroes 2 (USA).n64","players":"4","publisher":"3DO","esrb":"T - Teen","rating":{"score":3.61,"count":96}},{"id":"asteroids-hyper-64","title":"Asteroids Hyper 64","year":1999,"genres":["Shooter"],"description":"Crave Entertainment has given us an Asteroids game for the 90s, beefing up the classic formula with updated graphics and numerous multiplayer modes. Asteroids Hyper 64 contains 50 levels spread out over five zones. Although the time-tested concept remains the same (blast everything on the screen), players are armed with new power-ups and have to defeat a boss at the end of each level. Multiplayer action includes both cooperative and competitive variations, including team play.","descriptionSource":"http://www.gamefaqs.com/n64/196661-asteroids-hyper-64","developer":"Syrox Developments","coverName":"Asteroids Hyper 64 (USA).n64","players":"4","publisher":"Crave Entertainment","esrb":"E - Everyone","rating":{"score":2.98,"count":80}},{"id":"automobili-lamborghini","title":"Automobili Lamborghini","year":1997,"genres":["Racing"],"description":"Lay rubber through spectacular landscapes with Titus's Automobili Lamborghini! Six first-class circuits wind though mountains, past waterfalls and under ancient ruins. Great graphics effects, including light flares on your windshield, will take your breath away. But it's the goods under the hood that will have speed freaks salivating.","descriptionSource":"http://www.gamefaqs.com/n64/196671-automobili-lamborghini","developer":"Titus Software","coverName":"Automobili Lamborghini (USA).n64","players":"4","publisher":"Titus Interactive","esrb":"E - Everyone","rating":{"score":3.06,"count":110}},{"id":"banjo-kazooie","title":"Banjo-Kazooie","year":1998,"genres":["Adventure","Platformer","Puzzle"],"description":"Trouble is brewing on Spiral Mountain! Gruntilda the witch, wildly jealous of Tooty the Honey Bear's good looks; is determined to steal them for herself! But even as she whisks the helpless youngster off to her tower, Tooty's big brother Banjo and his loud-mouthed partner Kazooie are hot on the trail to rescue her...Aided by the mystical shaman Mumbo Jumbo, Banjo and Kazooie must tackle gloomy swamps, scorching deserts, towering mountain ranges and spooky haunted houses on their way to the final confrontation at the summit of Gruntilda's Lair.","descriptionSource":"http://www.gamefaqs.com/n64/196694-banjo-kazooie","developer":"Rare Ltd.","coverName":"Banjo-Kazooie (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.47,"count":736}},{"id":"banjo-tooie","title":"Banjo-Tooie","year":2000,"genres":["Adventure","Platformer","Puzzle"],"description":"Two years after Banjo Kazooie, Banjo and the gang are playing cards when an earthquake happens. Eagerly Mumbo goes out to investigate. He sees two hideous witches reviving Grunty. Mumbo goes back to investigate. Grunty shoots a laser beam at Banjo's house. Mumbo warns everyone but Bottles doesn't belive him. Grunty blows up Banjo's house with Bottles inside and sets off to get her body back. Motivated by revenge Banjo sets out to stop Grunty and revive Bottles.","descriptionSource":"http://www.gamefaqs.com/n64/196695-banjo-tooie","developer":"Rare Ltd.","coverName":"Banjo-Tooie (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.29,"count":438}},{"id":"bass-hunter-64","title":"Bass Hunter 64","year":1999,"genres":["Sports"],"description":"Go fishing in the great outdoors with Bass Hunter 64! Reel in a record-setting bass in tournament mode. 3D rendered environments, complete with native wildlife, and geographically accurate landscapes. Fish Pennsylvania's Lake Arthur and Florida's Butler Chain Lakes. Driving, underwater and positional cameras are throughout your adventure. Lure, strike, and fish-fighting animations designed to simulate bass fishing's most exciting moments. Fish behavior based on scientific research and practical experience of experts at In-Fisherman.","descriptionSource":"http://www.gamefaqs.com/n64/197634-in-fisherman-bass-hunter-64","developer":"Gear Head Entertainment","coverName":"In-Fisherman - Bass Hunter 64 (Europe).n64","players":"1","publisher":"Take-Two Interactive Software","esrb":"E - Everyone","rating":{"score":2.9,"count":48}},{"id":"bassmasters-2000","title":"Bassmasters 2000","year":1999,"genres":["Sports"],"description":"Fish with the best! Featuring real lakes from the Bassmaster Tournament Trail, authentic fishing equipment, two-player fishing action, underwater views, and frantic arcade modes. Just like The Bassmasters TV series!","descriptionSource":"http://www.gamefaqs.com/n64/196707-bassmasters-2000","developer":"Mass Media","coverName":"Bassmasters 2000 (USA).n64","players":"2","publisher":"THQ","esrb":"E - Everyone","rating":{"score":2.99,"count":49}},{"id":"batman-beyond-return-of-the-joker","title":"Batman Beyond: Return of the Joker","year":2000,"genres":["Beat 'em up"],"description":"Will The Joker have the last laugh? A sleeker, deadlier Clown Prince of Crime is back from the past to terrorize Gotham City in Batman Beyond: Return of the Joker. When The Joker's recent attacks nearly bring about the demise of the aging Bruce Wayne, it's up to you to help Batman avenge his mentor and send The Joker back to the bottom of the deck... forever!","descriptionSource":"http://www.gamefaqs.com/n64/579006-batman-beyond-return-of-the-joker","developer":"Kemco","coverName":"Batman Beyond - Return of the Joker (USA).n64","players":"1","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":2.98,"count":108}},{"id":"batman-of-the-future-return-of-the-joker","title":"Batman of the Future: Return of the Joker","year":2000,"genres":["Beat 'em up"],"description":"Will The Joker have the last laugh? A sleeker, deadlier Clown Prince of Crime is back from the past to terrorize Gotham City in Batman Beyond: Return of the Joker. When The Joker's recent attacks nearly bring about the demise of the aging Bruce Wayne, it's up to you to help Batman avenge his mentor and send The Joker back to the bottom of the deck... forever!","descriptionSource":"http://www.gamefaqs.com/n64/579006-batman-beyond-return-of-the-joker","developer":"Kemco","coverName":"Batman of the Future - Return of the Joker (Europe) (En,Fr,De).n64","players":"1","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":2.98,"count":108}},{"id":"battletanx","title":"BattleTanx","year":1998,"genres":["Action"],"description":"2001 A.D. - The world as you know it is no more. A deadly virus has wiped out 99% of the female population and the few surviving women are now worshipped as QueenLords. You are Griffin Spade, warrior and Battlelord in a post-apocalyptic future. With only the BattleTanx at your command, you must save mankind from extinction! Fight your way across the wasteland that was once America and rescue the QueenLords from roving gangs of mercenaries and thugs.","descriptionSource":"http://www.gamefaqs.com/n64/196733-battletanx","developer":"3DO","coverName":"BattleTanx (USA).n64","players":"4","publisher":"3DO","esrb":"T - Teen","rating":{"score":3.27,"count":103}},{"id":"battletanx-global-assault","title":"BattleTanx: Global Assault","year":1999,"genres":["Shooter"],"description":"The year is 2006. The world has become a post-apocalyptic wasteland. While Griffin and Madison struggle to rebuild society, they realize their young son possesses telekinetic powers that are the key to the future. But the evil QueenLord, Cassandra, plans to use the boy's powers for her own wicked scheme. With only armored tanks at your command, you must defeat the QueenLord and the sinister gangs under her control. Combat will lead you to foreign soil, where it's all-out global warfare!","descriptionSource":"http://www.gamefaqs.com/n64/196734-battletanx-global-assault","developer":"3DO","coverName":"BattleTanx - Global Assault (USA).n64","players":"4","publisher":"3DO","esrb":"T - Teen","rating":{"score":3.54,"count":102}},{"id":"battlezone-rise-of-the-black-dogs","title":"Battlezone: Rise of the Black Dogs","year":2000,"genres":["Simulation","Shooter","Strategy"],"description":"Exploit secret alien technology as you beat the Americans and Soviets at their own game in this action-packed, cold war thriller! Battlezone: Rise of the Black Dogs features advanced space-based tank combat, sniper capability and death-match intensity. With three modes of play, Battlezone gives you the power to define your combat experience - the only remaining question is how long you'll be around to use it.","descriptionSource":"http://www.gamefaqs.com/n64/196739-battlezone-rise-of-the-black-dogs","developer":"Climax Group","coverName":"Battlezone - Rise of the Black Dogs (USA).n64","players":"4","publisher":"Crave Entertainment","esrb":"E - Everyone","rating":{"score":2.95,"count":68}},{"id":"beetle-adventure-racing","title":"Beetle Adventure Racing!","year":1999,"genres":["Racing"],"description":"The adventure begins when you leave the road behind! Smashing, bashing fun! Crash and dash! Ultra-fast nitro blast! Go anywhere - choose your own routes, find surprises at every turn! Do anything - grab big-time air, engage in four-car mayhem!","descriptionSource":"http://www.gamefaqs.com/n64/196751-beetle-adventure-racing","developer":"Paradigm Entertainment","coverName":"Beetle Adventure Racing! (USA) (En,Fr,De).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.85,"count":200}},{"id":"big-mountain-2000","title":"Big Mountain 2000","year":2000,"genres":["Sports"],"description":"The king of all mountains wants some face time with you! Face-off on your choice of either snowboard or skis. Nasty hills, turns and jumps help you shred the laws of gravity as you Freestyle it, Solo or compete against other snowhounds. Ready to challenge the Big Mountain? Three modes - Time Attack, 2-Player Battle, and Championship - with 3 styles of play - Free Ride, Slalom and Giant Slalom. Six characters of wildly varying skill levels to choose from. Design your own gear, including equipment and clothing.","descriptionSource":"http://www.gamefaqs.com/n64/196757-big-mountain-2000","developer":"Natsume","coverName":"Big Mountain 2000 (USA).n64","players":"2","publisher":"Imagineer","esrb":"E - Everyone","rating":{"score":2.81,"count":67}},{"id":"bio-f-r-e-a-k-s","title":"Bio F.R.E.A.K.S.","year":1998,"genres":["Fighting"],"description":"The future is now... America and her government are in ruins after the Techno-Industrial civil wars. Technology has spiraled out of control, spawning a new breed of citizens: the BIOF.R.E.A.K.S. Choose from 8 F.R.E.A.K.S. Each is armed for battle with his or her own arsenal, including pulse lasers, grenade launchers, stun guns, swords and machine guns. Battle in three story, multi-tiered arenas! Watch out for hazards such as lava pits, meat grinders and spinning blades.","descriptionSource":"http://www.gamefaqs.com/n64/196759-bio-freaks","developer":"Saffire","coverName":"Bio F.R.E.A.K.S. (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":2.8,"count":79}},{"id":"blast-corps","title":"Blast Corps","year":1997,"genres":["Action","Puzzle"],"description":"A pair of defective nuclear missiles, en route to a safe detonation site, has begun to leak. Badly damaged, the carrier automatically locks onto the most direct route. Clear a path to help the carrier arrive safely. Tons of vehicles are at your disposal. Leave nothing standing or the adventure will end in an earth-shattering explosion! Find the hidden technicians to ensure a safe detonation. Strap on your seat belt, it's going to be a bumpy ride.","descriptionSource":"http://www.gamefaqs.com/n64/196774-blast-corps","developer":"Rare Ltd.","coverName":"Blast Corps (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.86,"count":187}},{"id":"blues-brothers-2000","title":"Blues Brothers 2000","year":2000,"genres":["Rhythm","Platformer"],"description":"The newly freed Elwood scours the Windy City to find and rescue all the members of his band. Gather enough notes along the way to build an impressive repertoire for the ultimate Battle of the Bands. The more songs you learn, the more secrets you uncover and the better your band becomes! Search city streets, roam through sewers, run from ghosts, pounce, shove and smash your way through the Chicago underworld to collect as much cash as possible... All to complete your mission: reunite your band in time for the Battle of the Bands. Straighten your tie, adjust your hat and slide on the shades... Chicago is waiting.","descriptionSource":"http://www.gamefaqs.com/n64/196792-blues-brothers-2000","developer":"Player 1","coverName":"Blues Brothers 2000 (USA).n64","players":"2","publisher":"Titus Software","esrb":"E - Everyone","rating":{"score":2.47,"count":66}},{"id":"body-harvest","title":"Body Harvest","year":1998,"genres":["Action","Shooter"],"description":"Earth is dead. Mankind annihilated. Hunted to extinction by a century of alien attacks. One last, desperate chance remains - CHANGE HISTORY. Someone must travel back in time and attack the alien predators before they complete their hideous invasion. Genetically enhanced marine, Adam Drake, must make the trip into the far reaches of Earth's history. His goal - stop the alien body harvest... Travel with Adam Drake through 5 incredible levels of action-packed adventure, spanning more than a century of Earth history!","descriptionSource":"http://www.gamefaqs.com/n64/196796-body-harvest","developer":"DMA Design","coverName":"Body Harvest (USA).n64","players":"1","publisher":"Gremlin Interactive","esrb":"T - Teen","rating":{"score":3.44,"count":120}},{"id":"bomberman-64","title":"Bomberman 64","year":1997,"genres":["Action","Party"],"description":"The evil Altair is using the Omni Cube to drain the energy from Planet Bomber. With the aid of a mysterious helper, you must defeat Altair,and restore peace to Planet Bomber. In the Adventure mode, guide Bomberman through 24 areas of perilous conflict. Battle Altair's sinister allies, destroy their bases and put an end to the insane attack. The multi-player Battle mode offers endless hours of explosive action. Use the standard Bomberman character or create a custom one and save it to an N64 Controller Pak.","descriptionSource":"http://www.gamefaqs.com/n64/196799-bomberman-64","developer":"Hudson","coverName":"Bomberman 64 (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.73,"count":210}},{"id":"bomberman-64-the-second-attack","title":"Bomberman 64: The Second Attack!","year":2000,"genres":["Action","Party","Platformer"],"description":"Of the great discoveries in the universe, few are more important than the legendary 8 elements. When the evil Rukifellth found one of these elements - the powerful Celestial Stone - he used his influence to assemble the dreaded BHB Army. Armed with his new army and a giant space warship, the power-crazed Rukifellth began scouring the galaxy for the other 7 elements, invading planets and enslaving innocent races throughout the galaxy. Rukifellth controls these enslaved planets with special Gravity Generators - the same devices the BHB Army used to create a Black Hole. Rukifellth uses his Black Hole to capture new planets... But he should have thought twice before he tried to capture Bomber Planet!","descriptionSource":"http://www.gamefaqs.com/n64/257793-bomberman-64-the-second-attack","developer":"Hudson","coverName":"Bomberman 64 - The Second Attack! (USA).n64","players":"4","publisher":"Vatical Entertainment","esrb":"E - Everyone","rating":{"score":3.78,"count":123}},{"id":"bomberman-hero","title":"Bomberman Hero","year":1998,"genres":["Action","Platformer"],"description":"Bomberman's latest adventure takes him across the galaxy! Princess Millian has been kidnapped by the evil Garaden Empire and it's up to Bomberman to save the day. Travel through worlds of ice, fire and water. Use new abilities and get help from friends like Louie the rabbit and Pibol the robot. New vehicles like the Bomber Copter and Bomber Marine will come in handy in your quest to save the Princess and free the universe once again!","descriptionSource":"http://www.gamefaqs.com/n64/196801-bomberman-hero","developer":"AI","coverName":"Bomberman Hero (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.7,"count":141}},{"id":"bottom-of-the-9th","title":"Bottom of the 9th","year":1999,"genres":["Sports"],"description":"Konami brings its famous Bottom of the 9th to the Nintendo 64. Play as Juan Gonzalez and take on McGwire and Sosa and re-live the chase for the home run crown. Over 750 real MLBPA players. 1998 rosters plus off-season trades and free agent signings. Scenario mode lets you replay nail-biting moments in history - including the dramatic 1998 home run race. Six exciting play modes: practice, exhibition, all star, season, playoffs, plus new scenaio mode.","descriptionSource":"http://www.gamefaqs.com/n64/575340-bottom-of-the-9th","developer":"Konami Computer Entertainment Osaka","coverName":"Bottom of the 9th (USA).n64","players":"2","publisher":"Konami","esrb":"E - Everyone","rating":{"score":1.93,"count":43}},{"id":"box-champions-2000","title":"Box Champions 2000","year":1999,"genres":["Sports"],"description":"Get it on as or against 25 of the greatest boxers of all time! Includes Oscar De La Hoya, Sugar Ray Leonard, Evander Holyfield, and THE GREATEST, Muhammad Ali! Arcade-style Slugfest and Career modes. Super KO punches and hidden moves. Knockdown-dragout battles with the greatest boxers ever. Build a champion and fight to the top in Career mode. Pit current champs vs. legendary superstars, or challenge your created boxer against the greats.","descriptionSource":"http://www.gamefaqs.com/n64/197746-knockout-kings-2000","developer":"Black Ops Entertainment","coverName":"Knockout Kings 2000 (Europe).n64","players":"2","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":3.86,"count":52}},{"id":"brunswick-circuit-pro-bowling","title":"Brunswick Circuit Pro Bowling","year":1999,"genres":["Sports"],"description":"Now every night is bowling night! Unsurpassed bowling physics engine for ultra-realistic ball and pin action. Cosmic bowling for lights-down, glow-in-the-dark bowling fun! Play as one of the Brunswick ProStaff, or create your own bowler. Authentic play modes, including tournaments, opens, and Skins games. The ultimate party game for up to six players!","descriptionSource":"http://www.gamefaqs.com/n64/915910-brunswick-circuit-pro-bowling","developer":"Point of View","coverName":"Brunswick Circuit Pro Bowling (USA).n64","players":"6","publisher":"THQ","esrb":"E - Everyone","rating":{"score":3.0,"count":54}},{"id":"buck-bumble","title":"Buck Bumble","year":1998,"genres":["Shooter"],"description":"The Herd, an evil band of vicious mutant insectoids, is attacking and exterminating Earth's native insects! Only Buck Bumble, the baddest bee in the hive and the world's most advanced cyborg insect, can save the day. Protect the insect world by blowing away terrifying Attack Wasps and Killapillas in 20 unearthly 3D environments. Use Buck's cybernetic implants and deadly weapons to unmask the power behind The Herd!","descriptionSource":"http://www.gamefaqs.com/n64/196835-buck-bumble","developer":"Argonaut Games","coverName":"Buck Bumble (USA).n64","players":"2","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":3.45,"count":103}},{"id":"bust-a-move-99","title":"Bust-A-Move '99","year":1999,"genres":["Puzzle"],"description":"Think you've busted with the best? Not until you've faced Bust-A-Move '99! With intense 4-player competition, all new graphics, and create-a-level mode, you've never busted bubbles like these! And with eight new mysterious characters to save, you'll be bustin' like crazy to solve all the puzzles and send them home!","descriptionSource":"http://www.gamefaqs.com/n64/196850-bust-a-move-99","developer":"Distinctive Developments Ltd","coverName":"Bust-A-Move '99 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.82,"count":95}},{"id":"bust-a-move-2-arcade-edition","title":"Bust-A-Move 2: Arcade Edition","year":1998,"genres":["Puzzle"],"description":"Bust-A-Move 2 is the lightning-quick, ultra-intense, 100% addictive, arcade puzzler that's gonna grab you and never let go! As the balls descend, you're gonna need sharp eyes and quick reflexes to match 3 or more balls and pop them... fast! Insane two-player action pits you against an opponent in a race to bust or be busted! Match 'em by color! Stack 'em! Pop 'em! It's the end all, be all, puzzle game of the century that lets everyone Bust-A-Move!","descriptionSource":"http://www.gamefaqs.com/n64/196853-bust-a-move-2-arcade-edition","developer":"Probe Entertainment Limited","coverName":"Bust-A-Move 2 - Arcade Edition (USA).n64","players":"2","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.59,"count":91}},{"id":"bust-a-move-3-dx","title":"Bust-A-Move 3 DX","year":1999,"genres":["Puzzle"],"description":"Think you've busted with the best? Not until you've faced Bust-A-Move '99! With intense 4-player competition, all new graphics, and create-a-level mode, you've never busted bubbles like these! And with eight new mysterious characters to save, you'll be bustin' like crazy to solve all the puzzles and send them home!","descriptionSource":"http://www.gamefaqs.com/n64/196850-bust-a-move-99","developer":"Distinctive Developments Ltd","coverName":"Bust-A-Move 3 DX (Europe).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.82,"count":95}},{"id":"california-speed","title":"California Speed","year":1999,"genres":["Racing"],"description":"Welcome to the Golden State! But if you want to see it all, don't blink 'cuz you'll be traveling at a cool 145 mph! Blast by landmarks at eye-popping velocity, while maintaining smooth control over your vehicle. Get in, grab the wheel and drive like the speed demon you are! We'll get your motor running! Scoot down 11 original tracks (all with plenty of shortcuts) plus 5 hidden tracks. Race at night, in overcast conditions or on one of those typically sunny California days. Got your shades? Custom-build your speed machine with all the essentials - cool rims, brilliant colors, automatic and manual transmissions!","descriptionSource":"http://www.gamefaqs.com/n64/196863-california-speed","developer":"Atari Games (Midway)","coverName":"California Speed (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.2,"count":99}},{"id":"carmageddon-64","title":"Carmageddon 64","year":1999,"genres":["Racing"],"description":"The year is 2026 and fatal toxins have polluted the earth's atmosphere. Those humans lucky enough to get to the 'Climate Emulation Centers' in time live in fear of the souls left on the surface - mutated, blood-thirsty zombies - the 'undead.' The World Government has recruited drivers to deal with this problem. The solution is 'The Carmageddon' - a death race in which drivers race against each other for the ultimate prize: a new life on the sun-drenched beaches of the off-world colonies. As well as a way of dealing with the zombies, it provides entertainment for the dwindling human population. You take on this challenge as Max Damage, a psychotic, cold-blooded racing machine. There is no second place. Drive to survive and let nothing and no one get in your way!","descriptionSource":"http://www.gamefaqs.com/n64/196871-carmageddon-64","developer":"Software Creations","coverName":"Carmageddon 64 (USA).n64","players":"2","publisher":"SCi Games","esrb":"M - Mature","rating":{"score":2.47,"count":92}},{"id":"castlevania","title":"Castlevania","year":1998,"genres":["Action","Platformer"],"description":"Take control of Reinhardt Schneider, a whip-toting Vampire Killer who has waited his whole life to meet his destiny, or Carrie Fernandez, a young girl with a strong magical presence who is mysteriously drawn to Dracula's evil Castlevania. It is their duty to seek out Castlevania and put an end to its residents' plans. What is your destiny?","descriptionSource":"http://www.gamefaqs.com/n64/196882-castlevania","developer":"KCEK","coverName":"Castlevania (USA).n64","players":"1","publisher":"Konami","esrb":"T - Teen","rating":{"score":3.53,"count":207}},{"id":"castlevania-legacy-of-darkness","title":"Castlevania: Legacy of Darkness","year":1999,"genres":["Action","Platformer"],"description":"Before Reinhardt Schneider and Carrie Fernandez confronted Dracula, a magical warrior embarked on a quest that would ultimately lead him to Dracula's lair. Take control of Cornell, a powerful werewolf, who is seeking out the evil minions responsible for his sister's disappearance. Armed with the power to morph from human to werewolf, Cornell is destined to rescure his sister from a sinister plan and rid the world of Dracula once and for all. Will he succeed or fail? Will the past unravel the future? Discover the legacy in this exciting prequel.","descriptionSource":"http://www.gamefaqs.com/n64/196883-castlevania-legacy-of-darkness","developer":"KCEK","coverName":"Castlevania - Legacy of Darkness (USA).n64","players":"1","publisher":"Konami","esrb":"T - Teen","rating":{"score":3.71,"count":226}},{"id":"centre-court-tennis","title":"Centre Court Tennis","year":1999,"genres":["Sports"],"description":"Challenge unique courts loaded with various tricks and obstacles! Enjoy the excitement of these lighthearted yet challenging courts! Increase the strength and ability of your players by collecting different items! Battle opponents in fierce competition to capture even more items! Acquire even further items in the MINI GAMES that get really exciting before you knowit! Put your skills to the test on a variety of courts against a variety of players!","descriptionSource":"http://www.gamefaqs.com/n64/576247-lets-smash","developer":"Hudson","coverName":"Centre Court Tennis (Europe).n64","players":"4","publisher":"Hudson Soft","esrb":"Not Rated","rating":{"score":3.05,"count":51}},{"id":"chameleon-twist","title":"Chameleon Twist","year":1997,"genres":["Action","Platformer"],"description":"Davy the Chameleon followed a peculiar rabbit into a magical pot, and now he is lost in a strange land! What's worse, he seems to have transformed into an alien. It looks like the only thing that is going to get him out of this mess is his chameleon tongue. A 3D action-adventure game for all ages! Training mode to improve basic gaming skills. Battle mode will provide a versus game with 2 - 4 players.","descriptionSource":"http://www.gamefaqs.com/n64/196896-chameleon-twist","developer":"Japan System Supply","coverName":"Chameleon Twist (USA).n64","players":"4","publisher":"Sunsoft","esrb":"E - Everyone","rating":{"score":3.3,"count":80}},{"id":"chameleon-twist-2","title":"Chameleon Twist 2","year":1999,"genres":["Action","Platformer"],"description":"Get in a twist! The chameleon is back! Once again our courageous Chameleon is led into a splendid adventure by the wiley White Rabbit. Using his tongue and his new gadget, a parachute, he can make his way through all the magical worlds, collecting items, changing his clothes (being a chameleon), beating his enemies as well as locating the many secret rooms where there are mini-games to enthrall and delight.","descriptionSource":"http://www.gamefaqs.com/n64/196897-chameleon-twist-2","developer":"Japan System Supply","coverName":"Chameleon Twist 2 (USA).n64","players":"1","publisher":"Sunsoft","esrb":"E - Everyone","rating":{"score":3.27,"count":77}},{"id":"charlie-blast-s-territory","title":"Charlie Blast's Territory","year":1999,"genres":["Puzzle"],"description":"Here's a fun puzzle for you, Charlie. See if you can set up a series of bombs in time to blow yourself to the next level - before you get so nervous you explode. It's a total N64 blast for 1 to 4 players. Bursting with cool Line Bombs and Freeze Bombs to demolish your competition. 45 increasingly complicated Multi-Player game boards for Survival Mode and Territory Mode. 60 single player Puzzle Mode levels. All kinds of wacky booby-traps designed by the world-famous game designer Scott Kim.","descriptionSource":"http://www.gamefaqs.com/n64/196901-charlie-blasts-territory","developer":"Realtime Associates","coverName":"Charlie Blast's Territory (USA).n64","players":"4","publisher":"Kemco U.S.A.","esrb":"E - Everyone","rating":{"score":3.02,"count":56}},{"id":"chopper-attack","title":"Chopper Attack","year":1998,"genres":["Shooter"],"description":"ACES NEEDED! Join an elite group of international chopper pilots with one objective... hunt down and destroy a renegade terrorist group bent on world domination! Engage and destroy the enemy in 8 different intense missions. Blow up strategic enemy radar. Shoot ground troops and enemy aircraft as you rescue hostages or escort friendly aircraft from dangerous enemy territory. Cash rewards give way to an explosive arsenal of ground and air missiles. Transform enemy installations into explosive fireballs with devastating ground and air target lock-on cluster bombs. Fly one of 8 different choppers, each one with different weapon and flying capabilities.","descriptionSource":"http://www.gamefaqs.com/n64/196913-chopper-attack","developer":"Seta Corporation","coverName":"Chopper Attack (USA).n64","players":"1","publisher":"SETA","esrb":"T - Teen","rating":{"score":3.17,"count":66}},{"id":"clay-fighter-63-1-3","title":"Clay Fighter 63 1-3","year":1997,"genres":["Fighting"],"description":"Get ready to crumble! Once again, the clay fighters prove that when you play a state-of-the-art fighter, you might lose lives, you might lose limbs, but there's no reason to lose your sense of humor! Fight in and out of 3D backgrounds. Get tossed out of a window and resume fighting outside. Choose form 12 eccentric fighters including brand new combatants and old favorites like 'Bad Mister Frosty' and 'Bonker the Clown.' Includes bonus 'secret characters' who are so famous that a legal gag order prohibits us from revealing their identity. Move freely in over 12 highly detailed 3D environments.","descriptionSource":"http://www.gamefaqs.com/n64/196934-clayfighter-63-1-3","developer":"Danger Productions","coverName":"Clay Fighter 63 1-3 (USA).n64","players":"2","publisher":"Interplay Entertainment","esrb":"T - Teen","rating":{"score":3.16,"count":88}},{"id":"clay-fighter-sculptor-s-cut","title":"Clay Fighter: Sculptor's Cut","year":1998,"genres":["Fighting"],"description":"Get ready to crumble... with this special edition of the world's funniest fighting game! This 'director's cut' contains many extras added to the original Clay Fighter 63 1/3 game. You might lose lives, you might lose limbs, but don't lose your sense of humor! 12 eccentric fighters plus 4 additional clay combatants only found in this version. More snide remarks and barbed wit will have you crying from laughing so hard! Original characters get additional attacks for an all-new experience. Enhanced camera angle stays put to see more details in the environment and improve fight control!","descriptionSource":"http://www.gamefaqs.com/n64/574483-clayfighter-the-sculptors-cut","developer":"Interplay","coverName":"Clay Fighter - Sculptor's Cut (USA).n64","players":"2","publisher":"Interplay Productions","esrb":"T - Teen","rating":{"score":3.37,"count":91}},{"id":"command-and-conquer","title":"Command & Conquer","year":1999,"genres":["Strategy"],"description":"In the hyper-real combat/strategy experience of Command & Conquer, you're thrust dead-on into the heat of an all-out race for global control. Will you side with the humanistic Global Defense Initiative? Or bring the world to its knees with the terroristic Brotherhood of Nod? Spread your web of power via electronic and physical aggression. Build bases, muster forces and lacerate your enemies to the bone. All for the love of power. And the chance to see how far you'll go to get it.","descriptionSource":"http://www.gamefaqs.com/n64/196958-command-and-conquer","developer":"Looking Glass Studios","coverName":"Command & Conquer (USA).n64","players":"1","publisher":"Nintendo","esrb":"T - Teen","rating":{"score":3.21,"count":75}},{"id":"conker-s-bad-fur-day","title":"Conker's Bad Fur Day","year":2001,"genres":["Action","Adventure","Platformer"],"description":"The day after his 21st birthday bash, Conker's sporting the worst hangover ever, and he just can't seem to find his way home. Prepare to stagger through randy, raunchy, raucous scenarios crammed full of bad manners, twisted humor, and graphic bodily functions. Unless you're a fan of violence, foul language, and racy innuendo, you'd best steer clear of this one.","descriptionSource":"http://www.gamefaqs.com/n64/196973-conkers-bad-fur-day","developer":"Rare Ltd.","coverName":"Conker's Bad Fur Day (USA).n64","players":"4","publisher":"THQ","esrb":"M - Mature","rating":{"score":4.36,"count":484}},{"id":"cruis-n-exotica","title":"Cruis'n Exotica","year":2000,"genres":["Racing"],"description":"Race in style! Cruis'n Exotica takes you to fantastic locales in even more fantastic vehicles. Race through steamy Jurassic jungles or on the ocean floor. Midair stunts keep the action nonstop! Valuable short-cuts and nitro boosts speed up the already fast-paced action! Fantastic driving action straight from the arcade! 60 tracks from around the world. One to four player nonstop racing action. Three modes of gameplay to choose from.","descriptionSource":"http://www.gamefaqs.com/n64/374847-cruisn-exotica","developer":"Gratuitous Games","coverName":"Cruis'n Exotica (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.68,"count":124}},{"id":"cruis-n-usa","title":"Cruis'n USA","year":1996,"genres":["Racing"],"description":"Slam the pedal to the metal and hang on for a wild race across the highways of America. Catch all the roadside scenery and famous landmarks from three different driving perspectives - from San Francisco's Golden Gate Bridge, South Dakota's Mount Rushmore to the rolling hills of Appalachia! Select one of five difficulty levels and even remove street traffic or rival racers from the course. Select one of 10 short courses or go the distance on an extended 14-stage road race.","descriptionSource":"http://www.gamefaqs.com/n64/197003-cruisn-usa","developer":"Midway","coverName":"Cruis'n USA (USA).n64","players":"2","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.69,"count":243}},{"id":"cruis-n-world","title":"Cruis'n World","year":1998,"genres":["Racing"],"description":"Wanna see the world the easy way? Cruise it! Race through the deserts of Australia, zip through the streets of Paris or blast through the roadways of China! Play the new Championship mode to earn power-ups and secret cars! Go it alone or challenge up to three friends to see who's the fastest! Check your passport at the door. With Cruis'n World, you've got the power! Choose from 12 different cars and take in scenery from 14 courses around the world.","descriptionSource":"http://www.gamefaqs.com/n64/197004-cruisn-world","developer":"Eurocom Entertainment Software","coverName":"Cruis'n World (USA).n64","players":"4","publisher":"Nintendo of America","esrb":"E - Everyone","rating":{"score":3.74,"count":163}},{"id":"cybertiger","title":"CyberTiger","year":2000,"genres":["Sports"],"description":"Rip up the rules book - anything goes! Create your own golfer to take on CyberTiger and the many other characters. Real-time analog swing and ball control - hit a fade or a draw, add topspin or backspin, all in mid-flight. Sandtraps and tall rough are just the beginning. Seven modes of play: Strokes, Skins, Match, Tournament, Practice, Driving Range and the all-new Battle and Club Challenge modes. More ways to get on the green - superdrives, hidden tricks, hidden courses, hidden golfers, and tons of secret skills!","descriptionSource":"http://www.gamefaqs.com/n64/197025-cybertiger","developer":"Saffire","coverName":"CyberTiger (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.06,"count":52}},{"id":"daffy-duck-starring-as-duck-dodgers","title":"Daffy Duck Starring as Duck Dodgers","year":2000,"genres":["Platformer"],"description":"Can you do it, Duck Dodgers? Can you save the Earth? Marvin the Martian has built the Ultimate Weapon to destroy our planet. But there's one small problem: Ultimate Weapons require a lot of energy that Marvin doesn't have. So he sends out his minions to search for energy atoms. It's up to you, Duck Dodgers, savior of the Universe (and master klutz), to stop Marvin before he collects enough atoms to make his diabolical plan a success. We're counting on you!","descriptionSource":"http://www.gamefaqs.com/n64/250578-duck-dodgers-starring-daffy-duck","developer":"Paradigm Entertainment","coverName":"Daffy Duck Starring as Duck Dodgers (Europe) (En,Fr,De,Es,It,Nl).n64","players":"1","publisher":"Infogrames","esrb":"E - Everyone","rating":{"score":3.33,"count":89}},{"id":"dark-rift","title":"Dark Rift","year":1997,"genres":["Fighting"],"description":"Dark Rift delivers hyper-active 3D fighting with a sci-fi theme! Compete against eight exotic and powerful characters and two very large bosses. Motion captured character animations enhance the realism. The arsenal includes multiple-hit combos, back-crunching grabs, juggles, projectiles, and punishing special moves. Tune into individual character stereo sound tracking. Fight in Tournament, 2-Player or Training modes.","descriptionSource":"http://www.gamefaqs.com/n64/197049-dark-rift","developer":"Kronos Digital Entertainment","coverName":"Dark Rift (USA).n64","players":"2","publisher":"Vic Tokai","esrb":"T - Teen","rating":{"score":3.05,"count":77}},{"id":"deadly-arts","title":"Deadly Arts","year":1998,"genres":["Fighting"],"description":"Walk into the arena, take a bow, and prepare for the most intense combat simulation ever! Over nine controllable fighters are yours to command, complete with an arsenal of face-busting, body-smashing moves. Feel every kick, punch and throw with the RUMBLE PAK feature as you take part in a low down and dirty street fighting tournament!","descriptionSource":"http://www.gamefaqs.com/n64/197070-deadly-arts","developer":"Konami Computer Entertainment Osaka","coverName":"Deadly Arts (USA).n64","players":"2","publisher":"Konami","esrb":"T - Teen","rating":{"score":2.73,"count":62}},{"id":"destruction-derby-64","title":"Destruction Derby 64","year":1999,"genres":["Racing"],"description":"High speed chaos! Up to 12 opponents battle simultaneously on a dozen arenas and tracks. Hardcore demolition action! Exploding cars. Realistic damage. Hit the road! 24 vehicles, from stock cars to hot rods to ambulances. Multiplayer mayhem! Deathmatch, Destruction Race, Bomb Tag and Capture the Flag modes.","descriptionSource":"http://www.gamefaqs.com/n64/197105-destruction-derby-64","developer":"Looking Glass Studios","coverName":"Destruction Derby 64 (USA).n64","players":"4","publisher":"THQ","esrb":"E - Everyone","rating":{"score":3.45,"count":98}},{"id":"diddy-kong-racing","title":"Diddy Kong Racing","year":1997,"genres":["Racing"],"description":"Timber the Tiger's parents picked a fine time to go on vacation. When they come back, they're going to be faced with an island trashed by the spiteful space bully Wizpig - unless the local animals can do something about it! So join Diddy Kong as he teams up with Timber the Tiger, Pipsy the Mouse and Taj the Genie in an epic racing adventure unlike anything you've ever experienced before!","descriptionSource":"http://www.gamefaqs.com/n64/197118-diddy-kong-racing","developer":"Rare Ltd.","coverName":"Diddy Kong Racing (USA) (En,Fr).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.32,"count":525}},{"id":"donald-duck-goin-quackers","title":"Donald Duck: Goin' Quackers","year":2000,"genres":["Action","Platformer"],"description":"Keeping Donald content is about as easy as herding cats, but everyone's favorite fusspot really goes off the deep end when malodorous magician Merlock duck-naps Daisy. To add insult to injury, Donald's uppity cousin, Gladstone Gander, vows to rescue Daisy. Thus begins Donald's great race to reach Daisy first and foil Merlock's nefarious plans.","descriptionSource":"http://www.gamefaqs.com/n64/914358-disneys-donald-duck-goin-quackers","developer":"Disney Interactive Studios","coverName":"Donald Duck - Goin' Quackers (USA) (En,Fr,De,Es,It).n64","players":"1","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":4.09,"count":129}},{"id":"donald-duck-quack-attack","title":"Donald Duck: Quack Attack","year":2000,"genres":["Action","Platformer"],"description":"Keeping Donald content is about as easy as herding cats, but everyone's favorite fusspot really goes off the deep end when malodorous magician Merlock duck-naps Daisy. To add insult to injury, Donald's uppity cousin, Gladstone Gander, vows to rescue Daisy. Thus begins Donald's great race to reach Daisy first and foil Merlock's nefarious plans.","descriptionSource":"http://www.gamefaqs.com/n64/914358-disneys-donald-duck-goin-quackers","developer":"Disney Interactive Studios","coverName":"Donald Duck - Quack Attack (Europe) (En,Fr,De,Es,It).n64","players":"1","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":4.09,"count":129}},{"id":"donkey-kong-64","title":"Donkey Kong 64","year":1999,"genres":["Action","Platformer"],"description":"K. Rool has kidnapped the Kongs! Can Donkey Kong rescue his friends, reclaim the Golden Bananas and save his homeland from certain doom? Take out some Kremlings with Chunky's Pineapple Launcher or Lanky's Trombone. Float through the air using Tiny's Ponytail Twirl. Even rocket to the sky with Diddy's Jetbarrel!","descriptionSource":"http://www.gamefaqs.com/n64/191702-donkey-kong-64","developer":"Rare Ltd.","coverName":"Donkey Kong 64 (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.21,"count":510}},{"id":"doom-64","title":"Doom 64","year":1997,"genres":["Shooter"],"description":"You killed the Demons once, they were all dead. Or so you thought... A single Demon Entity escaped detection. Systematically it altered decaying, dead carnage back into grotesque living tissue. The Demons have returned - stronger and more vicious than ever before. You mission is clear, there are no options: kill or be killed!","descriptionSource":"http://www.gamefaqs.com/n64/197141-doom-64","developer":"Midway Studios - San Diego","coverName":"Doom 64 (USA).n64","players":"1","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":4.01,"count":228}},{"id":"dr-mario-64","title":"Dr. Mario 64","year":2001,"genres":["Puzzle"],"description":"It's a new outbreak of Dr. Mario madness! Dr. Mario's back, packing a prescription for fun--and now the frenzied action of the original gets even more frantic with all-new multiplayer modes! Up to four players can go head-to-head, or they can pair up to pile on capsules in Team Battle. Other options let 'em race against time in Score Attack, target flashing viruses in Flash Mode, or test endurance in Marathon play. There's even a new story mode that pits Mario against pilferers trying to profit from his Megavitamins. It's a puzzling epidemic, and Dr. Mario's got the cure!","descriptionSource":"http://www.gamefaqs.com/n64/459840-dr-mario-64","developer":"Newcom","coverName":"Dr. Mario 64 (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.64,"count":158}},{"id":"dual-heroes","title":"Dual Heroes","year":1998,"genres":["Fighting"],"description":"Virtual gamers challenge you in a hot battle! Train your own robot! Cool heroes battle it out using combo attacks in 3D space. Exciting battles against CPU gamers with personality. Train your robot and have it fight in the auto-battle. Give it all you've got to win a medal!","descriptionSource":"http://www.gamefaqs.com/n64/197169-dual-heroes","developer":"Produce","coverName":"Dual Heroes (USA).n64","players":"2","publisher":"Electro Brain","esrb":"T - Teen","rating":{"score":2.49,"count":54}},{"id":"duck-dodgers-starring-daffy-duck","title":"Duck Dodgers Starring Daffy Duck","year":2000,"genres":["Platformer"],"description":"Can you do it, Duck Dodgers? Can you save the Earth? Marvin the Martian has built the Ultimate Weapon to destroy our planet. But there's one small problem: Ultimate Weapons require a lot of energy that Marvin doesn't have. So he sends out his minions to search for energy atoms. It's up to you, Duck Dodgers, savior of the Universe (and master klutz), to stop Marvin before he collects enough atoms to make his diabolical plan a success. We're counting on you!","descriptionSource":"http://www.gamefaqs.com/n64/250578-duck-dodgers-starring-daffy-duck","developer":"Paradigm Entertainment","coverName":"Duck Dodgers Starring Daffy Duck (USA) (En,Fr,Es).n64","players":"1","publisher":"Infogrames","esrb":"E - Everyone","rating":{"score":3.33,"count":89}},{"id":"duke-nukem-64","title":"Duke Nukem 64","year":1997,"genres":["Shooter"],"description":"Duke Nukem's coming to get some! Prepare yourself to become the biggest, baddest, alien basher in the known universe - Duke Nukem; as you blast your way through the streets of LA out to an orbiting station, and onto the moon itself. Bag some aliens with over a dozen hi-tech weapons. 32 levels of non-stop carnage. Run, jump, crawl, swim, and jetpack your way through danger. Big weapons and bigger bosses for a fun-filled fragfest! Four-player, split-screen Dukematch action.","descriptionSource":"http://www.gamefaqs.com/n64/197176-duke-nukem-64","developer":"Eurocom Entertainment Software","coverName":"Duke Nukem 64 (USA).n64","players":"4","publisher":"GT Interactive Software","esrb":"M - Mature","rating":{"score":3.73,"count":152}},{"id":"duke-nukem-zero-hour","title":"Duke Nukem: Zero Hour","year":1999,"genres":["Shooter"],"description":"He's all that stands between us and a Time-Spanning Alien invasion. He's Duke Nukem. Gaming's Greatest Action Hero. And this is his finest hour! Zero Hour! Awesome new enemies! Hilarious gags and one-liners! Same blood and guts attitude! Over 30 gut-wrenching levels set in four action-packed time eras! Incredible Teamplay and Deathmatch modes for up to 4 players! Over 20 all-new weapons of high-octane annihilation.","descriptionSource":"http://www.gamefaqs.com/n64/188913-duke-nukem-zero-hour","developer":"Eurocom Entertainment Software","coverName":"Duke Nukem - Zero Hour (USA).n64","players":"4","publisher":"GT Interactive Software","esrb":"M - Mature","rating":{"score":3.82,"count":118}},{"id":"earthworm-jim-3d","title":"Earthworm Jim 3D","year":1999,"genres":["Action","Platformer"],"description":"America's favorite super-hero is back! This time he's fighting to save HIS OWN MIND! The wacky worm is back in a massive 3D search for sanity. Four brains to navigate. Five evil bosses to battle including: Professor Monkey for a Head, Psy-Crow, Bob the Goldfish, and Fatty Roswell. 13 weapons including the Groovy Gun, the Chicken Gun, Banana-Myte, and the good old hair flamer! 15 levels plus final mega-boss showdown! Hundreds of puzzles to solve.","descriptionSource":"http://www.gamefaqs.com/n64/197200-earthworm-jim-3d","developer":"VIS Entertainment","coverName":"Earthworm Jim 3D (USA).n64","players":"1","publisher":"Rockstar Games","esrb":"E - Everyone","rating":{"score":3.21,"count":107}},{"id":"ecw-hardcore-revolution","title":"ECW Hardcore Revolution","year":2000,"genres":["Fighting","Sports"],"description":"Often imitated, never duplicated, ECW Hardcore Revolution takes you to Hell and back with the most intense hardcore wrestling action the human body can endure. Remember, scars never heal. Debut of over 40 hardcore ECW stars including Rob Van Dam, Sabu, Tommy Dreamer, Raven, Mike Awesome, Francine and New Jack! Real gutter-mouth crowd chants and commentary from ECW's Joey Styles. Brutal finishers and chair shots. '3-Way Dance' plus over 20 game modes!","descriptionSource":"http://www.gamefaqs.com/n64/197210-ecw-hardcore-revolution","developer":"Acclaim","coverName":"ECW Hardcore Revolution (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":2.96,"count":52}},{"id":"elmo-s-letter-adventure","title":"Elmo's Letter Adventure","year":1999,"genres":["Edutainment"],"description":"Preschoolers are in for a wonderful alphabet-packed good time. Join Elmo and his Sesame Street pals in wonderful 3D action adventures as he swims, drives, and blasts off into a vibrantly colored world of video game fun! Helps children ages 3 - 6 with letter recognition and basic spelling skills. Three skill levels easily adjustable by parent or child. Features voices from the beloved TV show.","descriptionSource":"http://www.gamefaqs.com/n64/929169-sesame-street-elmos-letter-adventure","developer":"Realtime Associates","coverName":"Elmo's Letter Adventure (USA).n64","players":null,"publisher":null,"esrb":null,"rating":null},{"id":"elmo-s-number-journey","title":"Elmo's Number Journey","year":1999,"genres":["Edutainment"],"description":"Preschoolers are in for a wonderful number-packed good time. Explore magical worlds with Elmo and his Sesame Street friends as he snowboards, jetskis, and drives off on an exciting video game adventure! Helps children ages 3 - 6 with number recognition and basic math skills. Three skill levels easily adjustable by parent or child. Features voices from the beloved TV show.","descriptionSource":"http://www.gamefaqs.com/n64/915907-sesame-street-elmos-number-journey","developer":"Realtime Associates","coverName":"Elmo's Number Journey (USA).n64","players":null,"publisher":null,"esrb":null,"rating":null},{"id":"excitebike-64","title":"Excitebike 64","year":2000,"genres":["Racing"],"description":"Experience extreme MX! You grind your way through the hairpin turn, a wall of mud exploding in your wake. Your next jump launches you into the air - you pull off a spectacular double no-footed can-can and become an instant legend! In Excitebike 64, you'll find all the high-flying action, heart-stopping stunts and bone-jarring crashes of the extreme sport of motocross. It'll set the daredevil inside you free. 20 stadium tracks and awesome outdoor courses - plus six different riders with six unique styles!","descriptionSource":"http://www.gamefaqs.com/n64/197253-excitebike-64","developer":"Left Field Productions","coverName":"Excitebike 64 (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.58,"count":142}},{"id":"extreme-g","title":"Extreme-G","year":1997,"genres":["Racing"],"description":"Pit yourself against 12 laser-blasting speedfreaks across 12 looping, coiling, corkscrewing rollercoaster racetracks. If you've never seen a cyber-cycle take a stinger missile up the tailpipe during a blistering halfpipe you're about to get a rush of adrenaline. Racing to the Nth degree through gravitational extremes. Surfing the knife edge between G-force and burning wreckage! If gravity's a law, then this is a felony.","descriptionSource":"http://www.gamefaqs.com/n64/197261-extreme-g","developer":"Probe Entertainment Limited","coverName":"Extreme-G (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.6,"count":131}},{"id":"extreme-g-xg2","title":"Extreme-G XG2","year":1998,"genres":["Racing"],"description":"Get ready for the ride of your life! Extreme-G 2. Feed the speedfreak within. Faster than the original. And ten times more deadly. One false turn and you're toast! Break the sound barrier with 12 razor-sharp handling evolution bikes. Over 40 twisting tracks. Blast your enemies with Rear-Firing Rockets, Ion Sidecannons, Magnetic Mines and more! Intense 4-player action: Battle Mode, Cup Challenge and Head-to-Head.","descriptionSource":"http://www.gamefaqs.com/n64/446010-extreme-g-2","developer":"Probe Entertainment Limited","coverName":"Extreme-G XG2 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.7,"count":97}},{"id":"f-1-world-grand-prix","title":"F-1 World Grand Prix","year":1998,"genres":["Racing"],"description":"F-1 World Grand Prix straps you into the driver's seat as you experience the high-octane rush of an actual Formula One season. Compete in the FIA Formula One World Championship with your choice of 22 drivers. You'll race through 17 of the most challenging Formula One circuits. Five game modes including: Grand Prix, Exhibition, Time Trial, Challenge and Two-Player. Realistic racing effects include real-time tire wear, skid marks and exhaust flames.","descriptionSource":"http://www.gamefaqs.com/n64/197275-f-1-world-grand-prix","developer":"Paradigm Entertainment","coverName":"F-1 World Grand Prix (USA).n64","players":"2","publisher":"Video System","esrb":"E - Everyone","rating":{"score":3.7,"count":89}},{"id":"f-1-world-grand-prix-ii","title":"F-1 World Grand Prix II","year":1999,"genres":["Racing"],"description":"The second F1 experience from Paradigm, the direct sequel to F-1 World Grand Prix, has more of the same high speed antics around the Formula 1 circuit.\n\nFollowing the 1998 season, you'll experience all the drivers, tracks and teams and compete in a number of different racing modes, from the usual Grand Prix and Training to Challenge mode, where you'll attempt to complete a range of critical events based on the deal.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/1101","developer":"Paradigm Entertainment","coverName":"F-1 World Grand Prix II (Europe) (En,Fr,De,Es).n64","players":"2","publisher":"Video System","esrb":"Not Rated","rating":{"score":3.82,"count":65}},{"id":"f-zero-x","title":"F-Zero X","year":1998,"genres":["Racing"],"description":"It's you against 29 other machines competing for the title of F-Zero X Champion. You're racing at speeds of over 1,000 km/h high above the atmosphere. Your competition comes from every corner of the galaxy and won't shed a tear at the thought of smashing you off the track. With four-player simultaneous gameplay and the Rumble Pak accessory, you have the fastest racing game on the N64 system!","descriptionSource":"http://www.gamefaqs.com/n64/197414-f-zero-x","developer":"Nintendo","coverName":"F-Zero X (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.29,"count":388}},{"id":"f1-pole-position-64","title":"F1 Pole Position 64","year":1997,"genres":["Racing"],"description":"Jump into the cockpit of an F1 racer and face the best teams in the world for a breathtaking race! Incredibly exciting: Official game of the FIA, the latest game from HUMAN will make your N64 roar through the 16 world championship circuits. From Monaco to San Marin, challenge the best drivers and feel the excitement of the World Grand Prix in 3D. 100% adrenalin! 2 arcade modes and a world championship mode which will help you experience a very realistic F1 simulation: settings of your vehicle, audio contact with the pit, changing weather conditions, collisions, retirement...","descriptionSource":"http://www.gamefaqs.com/n64/197271-f1-pole-position-64","developer":"Human Entertainment","coverName":"F1 Pole Position 64 (USA) (En,Fr,De).n64","players":"1","publisher":"Human Entertainment","esrb":"E - Everyone","rating":{"score":2.87,"count":67}},{"id":"f1-racing-championship","title":"F1 Racing Championship","year":2000,"genres":["Racing"],"description":"F1 Racing Championship is a Driving game, developed and published by Ubisoft,which was released in Europe in 2000.","descriptionSource":"http://www.gamefaqs.com/n64/577226-f1-racing-championship","developer":"Ubisoft","coverName":"F1 Racing Championship (Europe) (En,Fr,De,Es,It).n64","players":"2","publisher":"Video System","esrb":"Not Rated","rating":{"score":3.96,"count":61}},{"id":"fifa-64","title":"FIFA 64","year":1997,"genres":["Sports"],"description":"EA SPORTS elevates the world's #1 interactive sports title to the next level with FIFA Soccer for the N64. 3D stadiums showcase quick and responsive motion captured players as you control their every pass and shot with the smoothness of an analog joystick. Real-time picture-in-picture allows you to play the action from two distinct view points, perfect for fast-paced gameplay. Featuring 22 fully rendered players, 6 leagues including 160 teams, and Tournament, Playoff, Friendly, and League modes.","descriptionSource":"http://www.gamefaqs.com/n64/197313-fifa-soccer-64","developer":"EA Canada","coverName":"FIFA Soccer 64 (Europe) (En,Fr,De).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":2.66,"count":66}},{"id":"fifa-99","title":"FIFA 99","year":1998,"genres":["Sports"],"description":"All the clubs, leagues, and cups! Over 250 club teams. Twleve leagues: USA, Spain, Brazil, Italy, England, France, Germany, Sweden, Scotland, Portugal, Belgium, and the Netherlands. Custom Cups and Leagues - play your way! European Dream League mode - challenge the best of the best. New slide shots, new semi-auto goalkeepers, dazzling skill moves, new lifelike head tracking, new traps and tackles!","descriptionSource":"http://www.gamefaqs.com/n64/197309-fifa-99","developer":"EA Canada","coverName":"FIFA 99 (USA) (En,Fr,De,Es,It,Nl,Pt,Sv).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.64,"count":69}},{"id":"fifa-soccer-64","title":"FIFA Soccer 64","year":1997,"genres":["Sports"],"description":"EA SPORTS elevates the world's #1 interactive sports title to the next level with FIFA Soccer for the N64. 3D stadiums showcase quick and responsive motion captured players as you control their every pass and shot with the smoothness of an analog joystick. Real-time picture-in-picture allows you to play the action from two distinct view points, perfect for fast-paced gameplay. Featuring 22 fully rendered players, 6 leagues including 160 teams, and Tournament, Playoff, Friendly, and League modes.","descriptionSource":"http://www.gamefaqs.com/n64/197313-fifa-soccer-64","developer":"EA Canada","coverName":"FIFA Soccer 64 (USA) (En,Fr,De).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":2.66,"count":66}},{"id":"fifa-road-to-world-cup-98","title":"FIFA: Road to World Cup 98","year":1997,"genres":["Sports"],"description":"Conquer fierce defenders and defeat entire nations on your quest to compete in World Cup 98. Featuring 172 International teams from 6 zones and 16 International stadiums. Responsive player and ball control. New motion captured players and moves. Detailed stats for over 4500 players. 5 ways to compete: World Cup 98, Friendly, League, Penalty Kick Shootout and Training Mode. Edit teams and players to create your own dream team.","descriptionSource":"http://www.gamefaqs.com/n64/197311-fifa-road-to-world-cup-98","developer":"EA Canada","coverName":"FIFA - Road to World Cup 98 (USA) (En,Fr,De,Es,It,Nl,Sv).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.51,"count":74}},{"id":"fighter-destiny-2","title":"Fighter Destiny 2","year":2000,"genres":["Fighting"],"description":"Enter the arena and do battle with the toughest, most skilled martial arts experts on the planet. As one of the international fighting elite, you'll vie to become the true authority of hand-to-hand combat. Your destiny awaits. Defeat any of your 11 opponents and gain their abilities. Launch 5 different modes of attack, from Training to Record Attack. Adjust scoring, ring sizes and difficulty settings. Compete in points-based martial arts tournaments. Force your opponent to relive defeat in instant replay. Gain new abilities and skills when you face the Master in the Fighter's Arena.","descriptionSource":"http://www.gamefaqs.com/n64/197326-fighter-destiny-2","developer":"Opus","coverName":"Fighter Destiny 2 (USA).n64","players":"2","publisher":"Imagineer","esrb":"T - Teen","rating":{"score":3.0,"count":76}},{"id":"fighters-destiny","title":"Fighters Destiny","year":1998,"genres":["Fighting"],"description":"Defeat the Masters of the Fight in a head-on bout of power and skill. Fighters Destiny demands everything you have, everything you are and throws it right back at you in truly amazing, unstoppable 3D action. Prepare to fight every step of the way as you master the moves and unlock the secrets to fulfill your ultimate destiny!","descriptionSource":"http://www.gamefaqs.com/n64/197325-fighters-destiny","developer":"Opus","coverName":"Fighters Destiny (USA).n64","players":"2","publisher":"Ocean Software","esrb":"T - Teen","rating":{"score":3.36,"count":83}},{"id":"fighting-force-64","title":"Fighting Force 64","year":1999,"genres":["Beat 'em up"],"description":"Fighting Force delivers unparalleled action and tons of attack moves in a fully progressive 3D environment. Smash through an anti-tank barricade, pick up a rocket launcher and torch incoming enemies or knock over a vending machine or fuel tanker to find hidden weapons!","descriptionSource":"http://www.gamefaqs.com/n64/197332-fighting-force-64","developer":"Core Design Ltd.","coverName":"Fighting Force 64 (USA).n64","players":"2","publisher":"Crave Entertainment","esrb":"T - Teen","rating":{"score":3.99,"count":98}},{"id":"flying-dragon","title":"Flying Dragon","year":1998,"genres":["Fighting"],"description":"Two games in one: Flying Dragon is the ONE and ONLY game that will entertain the entire family. Create your ideal fighting game using the most customizable interface yet offered. Choose between RPG-style and 'virtual' tournament combat. Flying Dragon is never the same game twice! Over 20 different characters and 200 different items. Save your characters on a Controller Pak and play them against your friends!","descriptionSource":"http://www.gamefaqs.com/n64/197363-flying-dragon","developer":"Culture Brain","coverName":"Flying Dragon (USA).n64","players":"2","publisher":"Natsume","esrb":"T - Teen","rating":{"score":3.61,"count":67}},{"id":"forsaken","title":"Forsaken","year":1998,"genres":["Shooter"],"description":"An experiment gone wrong ripped away the earth's atmosphere. Bathed in the searching radiation of the sun, the planet has been condemned. You are among the FORSAKEN™ few who invade the now abandoned settlements to collect what little fortune was left behind.","descriptionSource":"http://www.gamefaqs.com/n64/197377-forsaken-64","developer":"Iguana Entertainment","coverName":"Forsaken 64 (Europe) (En,Fr,Es,It).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.69,"count":93}},{"id":"forsaken-64","title":"Forsaken 64","year":1998,"genres":["Shooter"],"description":"An experiment gone wrong ripped away the earth's atmosphere. Bathed in the searching radiation of the sun, the planet has been condemned. You are among the FORSAKEN™ few who invade the now abandoned settlements to collect what little fortune was left behind.","descriptionSource":"http://www.gamefaqs.com/n64/197377-forsaken-64","developer":"Iguana Entertainment","coverName":"Forsaken 64 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.69,"count":93}},{"id":"fox-sports-college-hoops-99","title":"Fox Sports College Hoops '99","year":1998,"genres":["Sports"],"description":"Complete college basketball license featuring over 120 college teams. NCAA Tournament, NCAA Sweet 16 and Final Four. Pre-season and Conference tournaments. In-depth player attributes and skill ratings. Three difficulty levels, easy to learn controls, and multiple camera angles. Authentic college basketball look and feel with real logos, uniforms and home courts, and real college offensive and defensive plays.","descriptionSource":"http://www.gamefaqs.com/n64/197380-fox-sports-college-hoops-99","developer":"Z-Axis, Ltd.","coverName":"Fox Sports College Hoops '99 (USA).n64","players":"2","publisher":"Fox Interactive","esrb":"E - Everyone","rating":{"score":2.37,"count":34}},{"id":"g-a-s-p-fighters-nextream","title":"G.A.S.P!! Fighters' NEXTream","year":1998,"genres":["Fighting"],"description":"Walk into the arena, take a bow, and prepare for the most intense combat simulation ever! Over nine controllable fighters are yours to command, complete with an arsenal of face-busting, body-smashing moves. Feel every kick, punch and throw with the RUMBLE PAK feature as you take part in a low down and dirty street fighting tournament!","descriptionSource":"http://www.gamefaqs.com/n64/197070-deadly-arts","developer":"Konami Computer Entertainment Osaka","coverName":"G.A.S.P!! Fighters' NEXTream (Europe).n64","players":"2","publisher":"Konami","esrb":"T - Teen","rating":{"score":2.73,"count":62}},{"id":"gamebooster-64","title":"GameBooster 64","year":0,"genres":[],"description":null,"descriptionSource":null,"developer":null,"coverName":"GameBooster 64 (USA) (v1.1) (Unl).n64","players":null,"publisher":null,"esrb":null,"rating":null},{"id":"gauntlet-legends","title":"Gauntlet Legends","year":1999,"genres":["Action"],"description":"Arm yourself and up to 3 friends, for adrenaline-drenched 4-player action in the legendary Gauntlet universe. Destroy evil forces in the 7 kingdoms! Experience 3 never-before-seen worlds filled with new enemies, traps and treasures! Use powerful sorcery, exotic power-ups and new 'Items of Legend' to save the Realm from the Demon Lord Skorne! Choose from the 4 classic characters (and unlock 5 hidden characters) to fight hordes of vile enemies and 6 vicious bosses! Become part of the Gauntlet saga by solving over 20 magical quests complete with new in-engine cinematics to tell the rich storyline!","descriptionSource":"http://www.gamefaqs.com/n64/197431-gauntlet-legends","developer":"Atari Games (Midway)","coverName":"Gauntlet Legends (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"T - Teen","rating":{"score":3.85,"count":112}},{"id":"gex-3-deep-cover-gecko","title":"Gex 3: Deep Cover Gecko","year":1999,"genres":["Action","Platformer"],"description":"Even a lost island hideaway in the wet South Pacific isn't far enough away from the long arm of Rez. While GEX was whiling away the hours living on the fruits of his recent successes, the madman of the Media Dimension was working on his new hobby - secret agent-napping. Agent Xtra was now struggling for her freedom as a hostage in the lair of Rez. As a master of disguise, GEX had his work cut out for him. Another descent into bad TV movies is at hand. To the GEXCaves!","descriptionSource":"http://www.gamefaqs.com/n64/197442-gex-3-deep-cover-gecko","developer":"Gratuitous Games","coverName":"Gex 3 - Deep Cover Gecko (USA).n64","players":"1","publisher":"Crave Entertainment","esrb":"E - Everyone","rating":{"score":3.47,"count":76}},{"id":"gex-64-enter-the-gecko","title":"Gex 64: Enter the Gecko","year":1998,"genres":["Action","Platformer"],"description":"The ultimate free-roaming 3D experience! 24 Media Dimension levels, all designed as sarcastic parodies of popular TV and movies! Master of Disguise GEX sports a secret agent suit, kung fu uniform, spacesuit and other costumes on his quest to save TV from the evil Rez! Over 125 slick gecko moves. Whip-cracking tail attacks, flying karate kicks, tongue-grabbing and climbing up walls. All-new N64 exclusive deep sea level with new swim mechanics and scuba gear!","descriptionSource":"http://www.gamefaqs.com/n64/197445-gex-64-enter-the-gecko","developer":"Realtime Associates","coverName":"Gex 64 - Enter the Gecko (USA).n64","players":"1","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.56,"count":97}},{"id":"glover","title":"Glover","year":1998,"genres":["Platformer"],"description":"The Kingdom's peaceful world has been shattered! The wizard, while mixing potions with his magical gloves has caused a huge explosion, turning him instantly to stone and dislodging the seven crystals that give the Kingdom its energy. Without the crystals, the castle and its world will fall apart and the wizard will be lost! It's down to Glover, one of the magical gloves, to find the crystals, now disguised as rubber balls and return them safely to the castle. Guide Glover and the balls through seven magical worlds full of puzzles and hidden surprises. Watch out! The evil glove is lurking in the shadows, and he'll stop at nothing to foil Glover's attempts at restoring peace.","descriptionSource":"http://www.gamefaqs.com/n64/197452-glover","developer":"Interactive Studios Ltd.","coverName":"Glover (USA).n64","players":"1","publisher":"Hasbro Interactive","esrb":"E - Everyone","rating":{"score":3.39,"count":107}},{"id":"goemon-s-great-adventure","title":"Goemon's Great Adventure","year":1999,"genres":["Action","Platformer"],"description":"Goemon and all his friends are back in his greatest adventure yet! Goemon's Great Adventure combines classic Goemon platform action with an all-new twist. The evil time-traveling nun, Bismaru, has summoned Dochuki, a demon prince, to take over the Earth. But first, she wants to marry him! Can Goemon and his gang stop the demon? Can Dochuki escape the cloying clutches of the wacked-out nun? Will Ebisu ever beat his own dumpling eating record? It's an adventure you'll never forget!","descriptionSource":"http://www.gamefaqs.com/n64/915334-goemons-great-adventure","developer":"Konami Computer Entertainment Osaka","coverName":"Goemon's Great Adventure (USA).n64","players":"2","publisher":"Konami","esrb":"E - Everyone","rating":{"score":3.97,"count":138}},{"id":"golden-nugget-64","title":"Golden Nugget 64","year":1998,"genres":["Casino"],"description":"Enter the Golden Nugget and you'll find yourself immersed in a real-time casino paradise with 15 games of chance to challenge and thrill you. Explore the lavish and elegant surroundings of the legendary Golden Nugget. Play Blackjack and Poker. Try your hand at Roulette and Craps. Feed coins into authentic slots and video poker machines. Experience breathtaking 3D animation with the odds, payoffs and excitement you'd expect from the legendary Golden Nugget of Las Vegas!","descriptionSource":"http://www.gamefaqs.com/n64/574488-golden-nugget-64","developer":"Westwood Studios","coverName":"Golden Nugget 64 (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.22,"count":52}},{"id":"goldeneye-007","title":"GoldenEye 007","year":1997,"genres":["Shooter","Stealth"],"description":"The name is Bond. James Bond. The famous hero of Ian Fleming's novels returns in this first-person shooter, which is based on the movie of the same name. Agent 007 and his friend Alec Trevalyan (a.k.a. Agent 006) were sent to the Soviet Union on a secret mission. But everything goes wrong, James Bond barely escapes, and his friend is presumed dead.\n\nTen years later, a mysterious organization named \"Janus\" appeared. Commanding a new satellite called \"GoldenEye\", the organization attempts to steal money electronically from banks, deleting all evidence of transfer. It's up to our Agent 007 to venture to the Soviet Union once again and to put an end to Janus' ambitions.\n\nIn this 3D action game, the player controls James Bond from a first-person perspective, using a variety of weapons (from knuckles to grenade launcher) to eliminate his foes. However, many parts require the player to be careful, to stay unnoticed, or to snipe guards from distance, since they will react to his presence and alarm their comrades. The game is divided into missions, and in most of them Bond will have to perform other tasks besides killing his enemies: disarm bombs, take pictures of important evidence, or avoid killing scientists. The game features a multiplayer mode with a variety of options and three difficulty levels. Higher difficulty means, besides having to deal with tougher enemies, additional objectives needed to be fulfilled in order to successfully complete the level.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/160","developer":"Rare","coverName":"007 - GoldenEye (USA).n64","players":"4","publisher":"Nintendo","esrb":"T - Teen","rating":{"score":4.48,"count":815}},{"id":"gt64-championship-edition","title":"GT64: Championship Edition","year":1998,"genres":["Racing"],"description":"The streets are clear, the lights are green and nothing is stopping you from taking the GT 64 Challenge. GT Racing puts the dream of professional racing into the hands of the ordinary driver. Specially re-engineered passenger cars take on the streets from Tokyo to the USA in the search for greater realism and improved challenges. GT 64 takes this one stage further by placing you behind the wheel of one of these monster machines. Accurately modelled car systems demand your every response be as real as if you were actually there, putting your faith in yourself and in the equipment around you.","descriptionSource":"http://www.gamefaqs.com/n64/197500-gt-64-championship-edition","developer":"Imagineer","coverName":"GT64 - Championship Edition (USA).n64","players":"2","publisher":"Ocean Software","esrb":"E - Everyone","rating":{"score":3.14,"count":75}},{"id":"harvest-moon-64","title":"Harvest Moon 64","year":1999,"genres":["Simulation","RPG"],"description":"Retire to the country for a new challenge in Harvest Moon 64. Hard work is rewarded as you struggle to bring prosperity back to a neglected farm. Work the land, pick up odd-jobs, and get to know the neighbors. Harvest Moon 64 has all the charm of the original Super Nintendo classic, plus many new surprises.* Tons of new seasonal vegetables and fruits.* Raise cows, chickens, and sheep.* New items and gifts. Including tools that increase in power as you master them.* One of town's five eligible women may prove to be the love of your life.* Celebrate seasonal festivals with the nearby townsfolk.* Enjoy local horse and dog racing.","descriptionSource":"http://www.gamefaqs.com/n64/197528-harvest-moon-64","developer":"Victor Interactive Software","coverName":"Harvest Moon 64 (USA).n64","players":"1","publisher":"Natsume","esrb":"E - Everyone","rating":{"score":3.88,"count":116}},{"id":"hercules-the-legendary-journeys","title":"Hercules: The Legendary Journeys","year":2000,"genres":["Action","Adventure"],"description":"Take control of the legendary hero Hercules and his friends Iolaus and Serena as they attempt to stop Ares from completing his diabolical plans. Use each character's unique attributes: Hercules' legendary strength, Iolaus' nimble nature and Serena's accuracy to complete your quest. Travel through 12 unique fully 3D worlds, from the sunny seaside town of Porticus to the snowy mountains of Alpsius. Explore the bandit-overrun forrests of Traycus or heavenly Mount Olympus. Fight mythical terrifying monsters such as the Minotaur, Cyclops, and more!","descriptionSource":"http://www.gamefaqs.com/n64/197546-hercules-the-legendary-journeys","developer":"Player 1","coverName":"Hercules - The Legendary Journeys (USA).n64","players":"1","publisher":"Titus Software","esrb":"T - Teen","rating":{"score":2.99,"count":41}},{"id":"hexen","title":"Hexen","year":1997,"genres":["Shooter"],"description":"While you were battling the evil forces of D'Sparil, the other Serpent Riders were busy sowing the seeds of destruction in other dimensions. One such dimension is the decaying world where Hexen takes place. Only three humans - a warrior, a mage and a cleric - have escaped the leader's vicious spell. Now these three brave souls have sworn to crush the evil regime that threatens to destroy the world forever. Become one of three heroes. Wield superhuman powers and lethal weapons. Walk. Run. Fly. Track down powerful artifacts and cast wicked spells.","descriptionSource":"http://www.gamefaqs.com/n64/197555-hexen","developer":"Software Creations","coverName":"Hexen (USA).n64","players":"4","publisher":"id Software","esrb":"M - Mature","rating":{"score":3.81,"count":94}},{"id":"hey-you-pikachu","title":"Hey You, Pikachu!","year":2000,"genres":["Simulation"],"description":"For the first time ever, you can actually talk to your favorite Pokémon. Tag along with Pikachu as it goes through its daily routines, taking field trips, going fishing and having picnics, becoming better friends with each passing day. Pikachu will hear and react to the words you say. The more you speak the closer friends you'll be!","descriptionSource":"http://www.gamefaqs.com/n64/250595-hey-you-pikachu","developer":"Ambrella","coverName":"Hey You, Pikachu! (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":2.87,"count":63}},{"id":"holy-magic-century","title":"Holy Magic Century","year":1998,"genres":["RPG"],"description":"Celtland has been cast into chaos by the theft of Eletale's Book.This mystical volume contains the secrets of the Spirit Tamers.Control Brian, a magician's apprentice, as he explores the expansive countryside and villages on his quest.If he does not reclaim the book, the Kingdom of Celtland will be cast into darkness forever.","descriptionSource":"http://www.gamefaqs.com/n64/198386-quest-64","developer":"Imagineer","coverName":"Holy Magic Century (Europe).n64","players":"1","publisher":"Konami","esrb":"E - Everyone","rating":{"score":3.47,"count":115}},{"id":"hot-wheels-turbo-racing","title":"Hot Wheels: Turbo Racing","year":1999,"genres":["Racing"],"description":"Stunts, speed and crashes combine for wild racing fun! Race 40 classic Hot Wheels - including Twin Mill and Red Baron. First ever killer stunt moves - 360's, barrel rolls, mid-air spins! 8 Hot Wheels tracks - Loop-the-Loops, Danger Changers, and more! Multi-player action so you can race against your friends! Three ways to win - speed, stunts, or crash cars off the road! Shortcuts, hidden cars, and power-ups!","descriptionSource":"http://www.gamefaqs.com/n64/197576-hot-wheels-turbo-racing","developer":"Stormfront Studios","coverName":"Hot Wheels - Turbo Racing (USA).n64","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.3,"count":87}},{"id":"hybrid-heaven","title":"Hybrid Heaven","year":1999,"genres":["Action","RPG"],"description":"A gunshot echoes through the tunnels of the New York subway system. A secret service agent lies dying, and Diaz, with a gun gripped tightly in his hand, flees and stumbles into a strange underground world where a secret society of genetically engineered hybrid clones threaten to subvert the population of the outside world. Experience New York City's secret night life in Hybrid Heaven, a unique, fully-immersive action RPG that combines fighting, action, and role playing into a story of alien invasion, scientific experimentation, and murder. Unravel the secrets of the hybrid society, the future of humanity, and the true identity of Diaz.","descriptionSource":"http://www.gamefaqs.com/n64/197592-hybrid-heaven","developer":"Konami Computer Entertainment Osaka","coverName":"Hybrid Heaven (USA).n64","players":"2","publisher":"Konami","esrb":"T - Teen","rating":{"score":3.48,"count":92}},{"id":"hydro-thunder","title":"Hydro Thunder","year":2000,"genres":["Racing"],"description":"Prepare for the power, speed and thrills of Hydro Thunder super-boat racing! Mighty Hull your way to the finish line of the most treacherous water courses imaginable! Nine unique handling turbo-charged thunder boats. Nine vividly rendered tracks through the world's most exhilarating terrain. Bonus boats, bonus tracks, boost power-ups and shortcuts galore. Split-screen mode can support up to 4 players simultaneously!","descriptionSource":"http://www.gamefaqs.com/n64/197595-hydro-thunder","developer":"Eurocom Entertainment Software","coverName":"Hydro Thunder (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.99,"count":111}},{"id":"iggy-s-reckin-balls","title":"Iggy's Reckin' Balls","year":1998,"genres":["Action","Racing"],"description":"A vertical race up towering tracks. Iggy and the Reckin' Balls are in the race of their lives. A winner-take-all dash to the top of twisted, looped, warped and genuinely demented courses! Smash, crash and swing with Iggy, his friends, plus loads of secret characters. Over 100 tracks, tons of shortcuts, secret paths, loops and elevators. One to four player racing action with Battle and Versus mode.","descriptionSource":"http://www.gamefaqs.com/n64/197610-iggys-reckin-balls","developer":"Iguana Entertainment","coverName":"Iggy's Reckin' Balls (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.12,"count":65}},{"id":"in-fisherman-bass-hunter-64","title":"In-Fisherman: Bass Hunter 64","year":1999,"genres":["Sports"],"description":"Go fishing in the great outdoors with Bass Hunter 64! Reel in a record-setting bass in tournament mode. 3D rendered environments, complete with native wildlife, and geographically accurate landscapes. Fish Pennsylvania's Lake Arthur and Florida's Butler Chain Lakes. Driving, underwater and positional cameras are throughout your adventure. Lure, strike, and fish-fighting animations designed to simulate bass fishing's most exciting moments. Fish behavior based on scientific research and practical experience of experts at In-Fisherman.","descriptionSource":"http://www.gamefaqs.com/n64/197634-in-fisherman-bass-hunter-64","developer":"Gear Head Entertainment","coverName":"In-Fisherman - Bass Hunter 64 (USA).n64","players":"1","publisher":"Take-Two Interactive Software","esrb":"E - Everyone","rating":{"score":2.9,"count":48}},{"id":"indiana-jones-and-the-infernal-machine","title":"Indiana Jones and the Infernal Machine","year":2000,"genres":["Action","Adventure"],"description":"1947. The nazis have been crushed, the Cold War has begun and Soviet agents are sniffing around an ancient ruin. Grab your whip and fedora and join Indy in a globespanning race to unearth the mysterious 'Infernal Machine'. Survive the challenges of unusual beasts, half the Red Army and more (including - oh no - snakes!) . Puzzle your way through 17 chapters of an action-packed story. Travel the world to exotic locales, from the ruins of Babylon to Egyptian deserts. All the weapons you'll need, including firearms, explosives-and of course Indy's trusty whip and revolver.","descriptionSource":"http://www.gamefaqs.com/n64/914232-indiana-jones-and-the-infernal-machine","developer":"Factor 5","coverName":"Indiana Jones and the Infernal Machine (USA).n64","players":"1","publisher":"LucasArts","esrb":"T - Teen","rating":{"score":3.86,"count":92}},{"id":"indy-racing-2000","title":"Indy Racing 2000","year":2000,"genres":["Racing"],"description":"Don't set the pace. Demolish it! Get behind the wheel and take control of the speed, power and tradition of 'The Greatest Spectacle in Racing' with Indy Racing 2000. With authentic Indy arcade action and additional fantasy courses, Indy Racing 2000 captures all of the high-speed excitement of racing 225 mph toward victory! Race as one of Indy racing's biggest superstars in an authentic Indy racing season. Dominate beyond Indy racing on 8 additional open wheel courses with Midget, Sprint and Formula cars.","descriptionSource":"http://www.gamefaqs.com/n64/197632-indy-racing-2000","developer":"Paradigm Entertainment","coverName":"Indy Racing 2000 (USA).n64","players":"2","publisher":"Infogrames","esrb":"E - Everyone","rating":{"score":3.48,"count":63}},{"id":"international-superstar-soccer-98","title":"International Superstar Soccer '98","year":1998,"genres":["Sports"],"description":"Do you have what it takes to be a superstar? Over 17,000 new motion captured animations! Team motivation, players and teams react to real game situations. Vertical camera angle allows you to see more of the pitch. 52 International teams and 9 unique soccer stadiums. Create your own players and trade existing ones. Infinite team formations and customizable strategies.","descriptionSource":"http://www.gamefaqs.com/n64/574489-international-superstar-soccer-98","developer":"Konami Computer Entertainment Osaka","coverName":"International Superstar Soccer '98 (USA).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":3.73,"count":71}},{"id":"international-superstar-soccer-2000","title":"International Superstar Soccer 2000","year":2000,"genres":["Sports"],"description":"The undisputed king of football returns... Experience the new Career Mode - bring youngsters through the ranks to create individual star players. Smoother animations and gameplay. ISS 2000 is the choice of champions - nothing gets as close to the beautiful game.","descriptionSource":"http://www.gamefaqs.com/n64/562991-international-superstar-soccer-2000","developer":"Konami","coverName":"International Superstar Soccer 2000 (USA) (En,Es).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":3.58,"count":71}},{"id":"international-superstar-soccer-64","title":"International Superstar Soccer 64","year":1997,"genres":["Sports"],"description":"Are you ready for the most realistic soccer game the world has ever seen? Get ready for: Incredible, seemless game control; Awesome animation with over 17,000 motion captured animations; Live, intelligent commentary; Every conceivable soccer move from headers to heel passes; Multiple formations to team strategies; Trade & create your own players; 36 International teams with 16 players per team. Everything a soccer fan wants!","descriptionSource":"http://www.gamefaqs.com/n64/197641-international-superstar-soccer-64","developer":"Konami Computer Entertainment Osaka","coverName":"International Superstar Soccer 64 (USA).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":3.83,"count":79}},{"id":"international-track-and-field-2000","title":"International Track & Field 2000","year":2000,"genres":["Sports"],"description":"Pure adrenaline! Go for gold with the only Track and Field title for Nintendo 64! Lightning-fast gameplay for up to four players. Over a dozen grueling international events, from weightlifting, to gymnastics, to the 100M dash.","descriptionSource":"http://www.gamefaqs.com/n64/258825-international-track-and-field-2000","developer":"Konami Computer Entertainment Osaka","coverName":"International Track & Field 2000 (USA).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":2.91,"count":46}},{"id":"international-track-and-field-summer-games","title":"International Track & Field: Summer Games","year":2000,"genres":["Sports"],"description":"Pure adrenaline! Go for gold with the only Track and Field title for Nintendo 64! Lightning-fast gameplay for up to four players. Over a dozen grueling international events, from weightlifting, to gymnastics, to the 100M dash.","descriptionSource":"http://www.gamefaqs.com/n64/258825-international-track-and-field-2000","developer":"Konami Computer Entertainment Osaka","coverName":"International Track & Field - Summer Games (Europe) (En,Fr,De).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":2.91,"count":46}},{"id":"jeopardy","title":"Jeopardy!","year":1998,"genres":["Quiz"],"description":"Join your host Alex Trebek in the Nintendo 64 version of Jeopardy! With its 3D rendered set, high-quality 16-bit audio and detailed video capture of Alex Trebek, you will feel as if you were really on the set. Featuring 4,000 brand new answers and questions and 650 different categories directly from the TV show.","descriptionSource":"http://www.gamefaqs.com/n64/915330-jeopardy","developer":"GameTek","coverName":"Jeopardy! (USA).n64","players":"3","publisher":"GameTek","esrb":"E - Everyone","rating":{"score":2.5,"count":38}},{"id":"jeremy-mcgrath-supercross-2000","title":"Jeremy McGrath Supercross 2000","year":2000,"genres":["Racing"],"description":"The ONLY Supercross game with Jeremy 'Showtime' McGrath! Totally customizable bikes and racing modes, plus free-ride practice environments and variable weather conditions. All-new engine featuring state-of-the-art graphics and bike physics. Design your own tracks with the custom 3D track editor. 16 Supercross stadiums and licensed Motocross tracks. 250cc and 125cc bikes plus Create-A-Rider. Sick freestyle motocross competitions exclusively featuring Travis Pastrana!","descriptionSource":"http://www.gamefaqs.com/n64/197678-jeremy-mcgrath-supercross-2000","developer":"Acclaim Studios Salt Lake City","coverName":"Jeremy McGrath Supercross 2000 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.47,"count":52}},{"id":"jet-force-gemini","title":"Jet Force Gemini","year":1999,"genres":["Adventure","Shooter"],"description":"The insect invasion has begun... The galaxy is being infested by the evil Mizar and his horde of Drones. Already, the planet of Goldwood has been subjugated and the peaceful Tribals enslaved. With an arsenal of mega-weapons at their disposal, the Jet Force Gemini team must travel in search of Mizar's lair - rescuing Tribals and splattering Drones all along the way. But can Juno, Vela and their faithful dog, Lupus, exterminate the deadly threat before it's too late?","descriptionSource":"http://www.gamefaqs.com/n64/197682-jet-force-gemini","developer":"Rare Ltd.","coverName":"Jet Force Gemini (USA).n64","players":"4","publisher":"Rare","esrb":"T - Teen","rating":{"score":3.88,"count":176}},{"id":"john-romero-s-daikatana","title":"John Romero's Daikatana","year":2000,"genres":["Shooter"],"description":"Designed by the legendary John Romero, Daikatana is a first person perspective action, which takes the 3D shoot'em up genre into a new dimension.Players assume the role of Hiro, traveling through time with his two sidekicks, the beautiful, yet lethal Mikko and the powerful mercenary Superfly Johnson. The player must lead this team, interacting with them to guide them through perilous worlds, exploring vast levels that are filled with an array of intelligent enemies.In their quest to save history, players will journey through four different time periods, traveling from mythical Greece to a post apocalyptic San Francisco 500 years in the future. Battling over 60 different monstrous enemies with more than 30 different weapon types, breaching obstacles and unearthing secret locations.","descriptionSource":"http://www.gamefaqs.com/n64/197032-john-romeros-daikatana","developer":"Kemco","coverName":"John Romero's Daikatana (USA).n64","players":"2","publisher":"Kemco","esrb":"M - Mature","rating":{"score":2.71,"count":73}},{"id":"ken-griffey-jr-s-slugfest","title":"Ken Griffey Jr.'s Slugfest","year":1999,"genres":["Sports"],"description":"Bursting with stunning realism and high-excitement baseball action, Ken Griffey Jr.'s Slugfest drives home the winning run! Improved player animations and color commentary by Dave Niehaus - 'The Voice of the Mariners' - make you feel like you're really at the game, while easy-to-use controls, updated rosters and statistics, and an optional fantasy draft make it even more fun than being there!","descriptionSource":"http://www.gamefaqs.com/n64/197710-ken-griffey-jrs-slugfest","developer":"Angel Studios","coverName":"Ken Griffey Jr.'s Slugfest (USA).n64","players":"2","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.47,"count":48}},{"id":"killer-instinct-gold","title":"Killer Instinct Gold","year":1996,"genres":["Fighting"],"description":"Killer Instinct Gold rocks the gaming world with its earth-shattering moves and unbelievable graphics. Your battles unfold with lightning-fast action and fluid character animation at 60 frames per second. We faithfully duplicated all the features that made Killer Instinct 2 an arcade hit. We've even thrown in a complete training mode to school you on all the moves! The eye-popping graphics, the explosive hits and jaw-dropping combos make Killer Instinct Gold the only fighting game you'll ever want in your house!","descriptionSource":"http://www.gamefaqs.com/n64/197715-killer-instinct-gold","developer":"Rare Ltd.","coverName":"Killer Instinct Gold (USA).n64","players":"2","publisher":"Nintendo","esrb":"T - Teen","rating":{"score":3.85,"count":204}},{"id":"kirby-64-the-crystal-shards","title":"Kirby 64: The Crystal Shards","year":2000,"genres":["Action","Adventure","Platformer"],"description":"Dart past enemies, soar the skies and swim the depths of the ocean as Kirby takes on Dark Matter in an all-new adventure. Inhale, exhale and swallow your enemies, then copy and combine their abilities and use them as your own! Team up with familiar friends and foes - like Waddle Dee and King Dedede - as you travel through dreamy worlds in search of the lost Crystal Shards.","descriptionSource":"http://www.gamefaqs.com/n64/250600-kirby-64-the-crystal-shards","developer":"HAL Labs","coverName":"Kirby 64 - The Crystal Shards (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.03,"count":304}},{"id":"knife-edge","title":"Knife Edge","year":1998,"genres":["Shooter"],"description":"'Command to Nose Gunner, Command to Nose Gunner. Radar's readin' an army of armored androids that are harshin' our Martian colonies. We're lookin' at boo-coo ground emplacements. Sulfur skies swarming with enemy gunships. F-f-f-four explosive gameplay modes for 1 to 4 players. And six super-vast battle stages with almostinfinite paths to mutually assured destruction. It's a 3D shooter for N64 that makes the Big Bang look like a burp. So gimme full automatic cannons. Lock and load all special weapons. Set Autopilot for maximum warp. And try not to chuck your chimichangas. 'Cuz... we... are... goin'... in...'","descriptionSource":"http://www.gamefaqs.com/n64/197742-knife-edge-nose-gunner","developer":"Kemco","coverName":"Knife Edge - Nose Gunner (Europe).n64","players":"4","publisher":"Kemco","esrb":"E - Everyone","rating":{"score":2.63,"count":54}},{"id":"knife-edge-nose-gunner","title":"Knife Edge: Nose Gunner","year":1998,"genres":["Shooter"],"description":"'Command to Nose Gunner, Command to Nose Gunner. Radar's readin' an army of armored androids that are harshin' our Martian colonies. We're lookin' at boo-coo ground emplacements. Sulfur skies swarming with enemy gunships. F-f-f-four explosive gameplay modes for 1 to 4 players. And six super-vast battle stages with almostinfinite paths to mutually assured destruction. It's a 3D shooter for N64 that makes the Big Bang look like a burp. So gimme full automatic cannons. Lock and load all special weapons. Set Autopilot for maximum warp. And try not to chuck your chimichangas. 'Cuz... we... are... goin'... in...'","descriptionSource":"http://www.gamefaqs.com/n64/197742-knife-edge-nose-gunner","developer":"Kemco","coverName":"Knife Edge - Nose Gunner (USA).n64","players":"4","publisher":"Kemco","esrb":"E - Everyone","rating":{"score":2.63,"count":54}},{"id":"knockout-kings-2000","title":"Knockout Kings 2000","year":1999,"genres":["Sports"],"description":"Get it on as or against 25 of the greatest boxers of all time! Includes Oscar De La Hoya, Sugar Ray Leonard, Evander Holyfield, and THE GREATEST, Muhammad Ali! Arcade-style Slugfest and Career modes. Super KO punches and hidden moves. Knockdown-dragout battles with the greatest boxers ever. Build a champion and fight to the top in Career mode. Pit current champs vs. legendary superstars, or challenge your created boxer against the greats.","descriptionSource":"http://www.gamefaqs.com/n64/197746-knockout-kings-2000","developer":"Black Ops Entertainment","coverName":"Knockout Kings 2000 (USA).n64","players":"2","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":3.86,"count":52}},{"id":"kobe-bryant-in-nba-courtside","title":"Kobe Bryant in NBA Courtside","year":1998,"genres":["Sports"],"description":"Raise the roof with the NBA's newest superstar in Kobe Bryant in NBA Courtside! Run your offense, set picks and slam home alley-oops. Rattle your rivals by double-teaming playmakers, intercepting passes and blocking shots. Supersweet animations include high-flying dunks, crossover dribbles and no-look passes. Take on up to three friends and school 'em with your smooth hardwood style!","descriptionSource":"http://www.gamefaqs.com/n64/197750-kobe-bryant-in-nba-courtside","developer":"Left Field Productions","coverName":"Kobe Bryant's NBA Courtside (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.51,"count":72}},{"id":"lego-racers","title":"LEGO Racers","year":1999,"genres":["Racing"],"description":"Start your engines! Race through exciting LEGO worlds and battle the greatest LEGO Racers of all time! You'll have to out-build, out-drive and out-smart your LEGO competitors to face Rocket Racer in the ultimate championship race! So, get ready. Get set. Go! Build. Customize. Race. Win!","descriptionSource":"http://www.gamefaqs.com/n64/197775-lego-racers","developer":"High Voltage Software","coverName":"LEGO Racers (USA) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi).n64","players":"2","publisher":"Lego Media","esrb":"E - Everyone","rating":{"score":3.45,"count":88}},{"id":"lode-runner-3-d","title":"Lode Runner 3-D","year":1999,"genres":["Platformer","Puzzle"],"description":"Get the gold. Get rid of the Emperor. Get it? Enter the mad Emperor Monk's realm and maneuver between five worlds with your specially modified LR-28 combat transport. Recover the stolen gold, explode a few bombs and collect some gems along the way. Eliminate the Emperor Monk, and return to Earth alive! Featuring 5 unique game worlds and 136 challenging levels, plus 20 bonus levels!","descriptionSource":"http://www.gamefaqs.com/n64/197794-lode-runner-3-d","developer":"Big Bang","coverName":"Lode Runner 3-D (USA).n64","players":"1","publisher":"Infogrames","esrb":"E - Everyone","rating":{"score":3.12,"count":58}},{"id":"lylat-wars","title":"Lylat Wars","year":1997,"genres":["Shooter"],"description":"The Lylat system has been invaded! Join Fox McCloud and his Star Fox team as they fight to save the galaxy from the clutches of the evil Andross. Travel to many different 3-D worlds. Battle the enemy in the air and on the ground and listen in as Fox McCloud interacts with a cast of characters.","descriptionSource":"http://www.gamefaqs.com/n64/198759-star-fox-64","developer":"Nintendo","coverName":"Lylat Wars (Europe) (En,Fr,De).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.42,"count":543}},{"id":"mace-the-dark-age","title":"Mace: The Dark Age","year":1997,"genres":["Fighting"],"description":"Live by the sword. Kill for the mace! Forged in the fires of the Dark Ages, Mace is the hottest 3D fighting game ever! Each medieval character wields a weapon unique to their land of origin. Their only desire - inflict serious pain! Sixteen player-selectable characters, two amazing bosses and six hidden characters. Tons of tasty combos and reversals with simple four-button controls. Become immersed in battle with complete 3D character movement. Behold the interactive multi-level arenas, but beware of the deadly boundaries!","descriptionSource":"http://www.gamefaqs.com/n64/197812-mace-the-dark-age","developer":"Atari","coverName":"Mace - The Dark Age (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":3.34,"count":94}},{"id":"madden-football-64","title":"Madden Football 64","year":1997,"genres":["Sports"],"description":"Madden Football 64 is the first in Electronic Arts' Madden series to appear on the Nintendo 64. In terms of features, it is based closely on the PlayStation/Saturn version of Madden 98 (with the same playing modes and even menus) but there are two important differences: The N64 version does not have an NFL license, so there are generic team names without logos (there is an NFLPA license for real player names), and it is the first game in the series to feature fully polygonal graphics, for both stadiums and players.\n\nConsequently, Madden 64 was the most graphically advanced Madden game at the time of release. Visual features include 5000 frames of animation and a first-person HelmetCam view. AI adjusts during the game to the player's style. Creating, drafting and trading a full roster of players is possible.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/1133","developer":"EA Tiburon","coverName":"Madden Football 64 (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":2.83,"count":50}},{"id":"madden-nfl-2000","title":"Madden NFL 2000","year":1999,"genres":["Sports"],"description":"The speed and power of NFL football! Faster moves and breakaway speed for bigger plays. Body slams and collisions, drag-downs and de-cleaters, explosive sticking and crunching gang tackles. Ultra-fast blur moves, helmet-popping hits, more scoring, special animations, and in-your-face commentary. Multiplayer Franchise mode, authentic stadium atmosphere, Hot Routes, Madden Challenge and more!","descriptionSource":"http://www.gamefaqs.com/n64/197823-madden-nfl-2000","developer":"EA Tiburon","coverName":"Madden NFL 2000 (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":2.84,"count":48}},{"id":"madden-nfl-2001","title":"Madden NFL 2001","year":2000,"genres":["Sports"],"description":"Get ready for a dose of bone-crunching football action on the PlayStation 2 with Madden NFL 2001. Madden NFL 2001 features an all-new and exclusive NFL Coaches Club license, which means you'll see coaches on the sidelines and hear them yelling encouragement, comments and criticisms. Madden 2001 also features individualized details, easy-to-use interface, dynamically enhanced audio and play-by-play recorded with John Madden and his broadcast partner, Pat Summerall, and more!","descriptionSource":"http://www.gamefaqs.com/n64/371618-madden-nfl-2001","developer":"EA Tiburon","coverName":"Madden NFL 2001 (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.22,"count":36}},{"id":"madden-nfl-2002","title":"Madden NFL 2002","year":2001,"genres":["Sports"],"description":"#1 for a reason! Return to glory: Relive the golden days of 16-bit Madden gameplay in Madden Classic mode. Kick off the season with the newest NFL team: Take the field with all 32 NFL teams including the expansion Houston Texans. A game within a game: Run or defend an improved 2-Minute Drill, now featuring Head-To-Head Challenge. Bang-Boom-Pow: Perfect the X's and O's with the help of John Madden in Training mode.","descriptionSource":"http://www.gamefaqs.com/n64/530612-madden-nfl-2002","developer":"BudCat","coverName":"Madden NFL 2002 (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.04,"count":46}},{"id":"madden-nfl-99","title":"Madden NFL 99","year":1998,"genres":["Sports"],"description":"This is all-Madden football! Legendary gameplay. One-button simplicity. The ultimate NFL experience. New super hi-res polygon graphics. Monster hits - feel and hear the impact! 250 new motion captured NFL moves. New Arcade Mode - huge hits, more fun! Over 120 past and present NFL teams. Draft, trade, create, sign, and release players.","descriptionSource":"http://www.gamefaqs.com/n64/197831-madden-nfl-99","developer":"EA Tiburon","coverName":"Madden NFL 99 (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.38,"count":38}},{"id":"magical-tetris-challenge","title":"Magical Tetris Challenge","year":1999,"genres":["Puzzle"],"description":"Join Disney's Mickey, Minnie, Donald and Goofy as they embark on a non-stop adventure full of challenging fun and excitement in Magical Tetris Challenge. Completely addictive, deceptively simple, you'll go wild in a kaleidoscopic shower of falling Tetris pieces in this magical version of the world's most popular video game.","descriptionSource":"http://www.gamefaqs.com/n64/197844-magical-tetris-challenge","developer":"Capcom","coverName":"Magical Tetris Challenge (USA).n64","players":"2","publisher":"Capcom","esrb":"E - Everyone","rating":{"score":3.62,"count":91}},{"id":"major-league-baseball-featuring-ken-griffey-jr","title":"Major League Baseball featuring Ken Griffey Jr.","year":1998,"genres":["Sports"],"description":"Make your dreams of becoming a Major Leaguer a reality! Hit a grand slam, pitch a no-hitter, go for the cycle and steal home - all in the same game! If that's not enough, check out the real-time stat tracking in over 30 major categories. Improve your team by making the right trades and picking up the best free agents. Major League Baseball Featuring Ken Griffey Jr. is so real, every pitch counts!","descriptionSource":"http://www.gamefaqs.com/n64/197847-major-league-baseball-featuring-ken-griffey-jr","developer":"Angel Studios","coverName":"Major League Baseball featuring Ken Griffey Jr. (USA).n64","players":"2","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.56,"count":54}},{"id":"mario-golf","title":"Mario Golf","year":1999,"genres":["Sports"],"description":"Forget buying expensive golf gear--Mario brings the game to you.Mario Golf features four complete 18-hole courses, 11 golfers, and precise play control.Create your own golfer and build up his or her experience and skill levels by competing in various tournaments and head-to-head matches.The more you play, the stronger and more accurate your golfer becomes.There are many different modes of play in Mario Golf, including a wide variety of minigames designed to challenge even the most level-headed swingers.","descriptionSource":"http://www.gamefaqs.com/n64/197859-mario-golf","developer":"Camelot Software Planning","coverName":"Mario Golf (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.02,"count":208}},{"id":"mario-kart-64","title":"Mario Kart 64","year":1997,"genres":["Racing"],"description":"Three... Two... One... GO! The signal light changes and you drop the pedal to the metal. Take on up to three friends in the split-screen VS games, or race solo in the Mario GP. Tell your friends to bring it on in the highly competitive Battle mode. Advanced features allow you to race with your 'Ghost'. The driving data from your best run appears as a transparent character on the screen. No longer must you simply race against the clock - you can actually race against yourself!","descriptionSource":"http://www.gamefaqs.com/n64/197860-mario-kart-64","developer":"Nintendo","coverName":"Mario Kart 64 (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.53,"count":1034}},{"id":"mario-party","title":"Mario Party","year":1999,"genres":["Party"],"description":"Tensions mount for Mario and pals as each declares himself to be the one true Super Star of Marioland. Face your friends and family in a contest of strength, wits and agility as you explore 6 thriling Adventure Boards. Reveal new levels of gaming excitement as you customize your boards with speed blocks, warp blocks and other specialty items. Jam-packed with all the electricity of an entire arcade, the action comes alive for up to 4 players. So grab your friends and get ready for a wild ride because this party never ends!","descriptionSource":"http://www.gamefaqs.com/n64/197861-mario-party","developer":"Hudson","coverName":"Mario Party (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.03,"count":275}},{"id":"mario-party-2","title":"Mario Party 2","year":2000,"genres":["Party"],"description":"Mario and the gang are back for another round of Bowser-bashin' party action! Watch as your favorite Nintendo characters don different duds for each of the five all-new Adventure Boards! A slew of new tricks and devices bring new levels of challenge and excitement to board game play. New board maps, new Mini-Games, new action and new surprises means a whole new batch of fun! Get ready to unleash your best Hip Drops, hammer swings and high-flying high junks for another round of frenzied multi-player action!","descriptionSource":"http://www.gamefaqs.com/n64/197862-mario-party-2","developer":"Hudson","coverName":"Mario Party 2 (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.25,"count":268}},{"id":"mario-party-3","title":"Mario Party 3","year":2001,"genres":["Party"],"description":"Mario and friends are throwing a party and you're invited. It's their biggest bash yet, with seventy totally new Mini-Games and five brand new adventure boards. You'll be the life of the party as you punch, pound and stampede right over your opponents in a multiplayer melee or go head-to-head in the new two-player duel mode. You can even unlock new characters in the one-player challenge. With so much fun and excitement, this isa bash you'll just have to crash!","descriptionSource":"http://www.gamefaqs.com/n64/374848-mario-party-3","developer":"Hudson","coverName":"Mario Party 3 (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.1,"count":269}},{"id":"mario-tennis","title":"Mario Tennis","year":2000,"genres":["Sports"],"description":"All of your favorite characters hit the court in a wild and wacky multiplayer tennis game from the makers of Mario Golf. Mario, Luigi, Bowser, Peach, Toad, and Donkey Kong lead off the all-star, 14-player line-up. The fast-paced action will have you unleashing vicious volleys, life-saving lobs, ballistic backhands and electrifying super-charged smashes!","descriptionSource":"http://www.gamefaqs.com/n64/258820-mario-tennis","developer":"Camelot Software Planning","coverName":"Mario Tennis (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.09,"count":260}},{"id":"mega-man-64","title":"Mega Man 64","year":2001,"genres":["Adventure","Shooter"],"description":"Mega Man blasts his way onto the Nintendo&reg; 64 System for the first time ever! This epic adventure combines the best of classic Mega Man action with enormous bosses, a riveting storyline and all the depth of the hottest RPG. Explore vast 3-D worlds in your quest to find the treasure of all treasures, the Mother Lode. You'll love the stunning 3-D graphics, powerful weapons and non-stop action ...unless of course, you're a boos.","descriptionSource":"http://www.gamefaqs.com/n64/913960-mega-man-64","developer":"Capcom","coverName":"Mega Man 64 (USA).n64","players":"1","publisher":"Capcom","esrb":"E - Everyone","rating":{"score":3.16,"count":128}},{"id":"mia-hamm-soccer-64","title":"Mia Hamm Soccer 64","year":2000,"genres":["Sports"],"description":"Feel the excitement as you take the winning shot with soccer champion Mia Hamm! Be a part of Mia Hamm's All-Star team or take Mia on, as you play for the World Cup in front of thousands of animated fans. Learn the art of a corner kick, a penalty kick or how to beat a goalkeeper one-on-one, and get tips from Mia that you can take with you onto the real field!","descriptionSource":"http://www.gamefaqs.com/n64/577028-mia-hamm-64-soccer","developer":"Silicon Dreams","coverName":"Mia Hamm Soccer 64 (USA) (En,Es).n64","players":"4","publisher":"Southpeak Interactive","esrb":"E - Everyone","rating":{"score":2.4,"count":51}},{"id":"michael-owen-s-world-league-soccer-2000","title":"Michael Owen's World League Soccer 2000","year":2000,"genres":["Sports"],"description":"Feel the excitement as you take the winning shot with soccer champion Mia Hamm! Be a part of Mia Hamm's All-Star team or take Mia on, as you play for the World Cup in front of thousands of animated fans. Learn the art of a corner kick, a penalty kick or how to beat a goalkeeper one-on-one, and get tips from Mia that you can take with you onto the real field!","descriptionSource":"http://www.gamefaqs.com/n64/577028-mia-hamm-64-soccer","developer":"Silicon Dreams","coverName":"Michael Owen's World League Soccer 2000 (Europe).n64","players":"4","publisher":"THQ","esrb":"E - Everyone","rating":null},{"id":"mickey-s-speedway-usa","title":"Mickey's Speedway USA","year":2000,"genres":["Racing"],"description":"Buckle up and get ready to race! Rally across America with Mickey and friends! Race around 20 All-American courses - from Alaska to the Everglades - as you try to track down the Weasels and rescue poor dognapped Pluto. Use Ludwig Von Drake's wacky weapons - such as the 'Antigrav-o-Kit Magno Flyer' or the 'Stormy Weather Whenever Engager' - to give you the edge. Then blast past your friends and listen as the drivers taunt each other using Disney's original character voices!","descriptionSource":"http://www.gamefaqs.com/n64/913923-mickeys-speedway-usa","developer":"Rare Ltd.","coverName":"Mickey's Speedway USA (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.72,"count":126}},{"id":"micro-machines-64-turbo","title":"Micro Machines 64 Turbo","year":1999,"genres":["Racing"],"description":"With Micro Machines&reg; 64 Turbo, you'll race like you've never raced before, in places you only imagined! Zoom across the kitchen table, kick up sand on the beach, race boats in a pond or burn rubber around the pool table - there's no place you can't go! This little game is HUGE!","descriptionSource":"http://www.gamefaqs.com/n64/197918-micro-machines-64-turbo","developer":"Codemasters","coverName":"Micro Machines 64 Turbo (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.65,"count":73}},{"id":"midway-s-greatest-arcade-hits-volume-1","title":"Midway's Greatest Arcade Hits: Volume 1","year":2000,"genres":["Compilation"],"description":"SPY HUNTER: Take on enemy agents with your collection of secret weapons! ROBOTRON 2084: Save the last human family on earth by destroying hordes of marauding mutant robots! ROOTBEER TAPPER: Serve up some frosty rootbeers to thirsty customers! JOUST: Take to the air on your winged bird of prey and dismount your opponents! DEFENDER: Defend the planet from hordes of ravenous space aliens intent on kidnapping all of the humans under your protection! SINISTAR: Prevent the evil Sinistar from being unleashed and destroying everything in its path. Once he forms from floating pieces, the universe is doomed!","descriptionSource":"http://www.gamefaqs.com/n64/437519-midways-greatest-arcade-hits-volume-1","developer":"Digital Eclipse","coverName":"Midway's Greatest Arcade Hits - Volume 1 (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.18,"count":49}},{"id":"mike-piazza-s-strikezone","title":"Mike Piazza's StrikeZone","year":1998,"genres":["Sports"],"description":"DIG IN! Over 700 players! All the stadiums! All the teams and uniforms! All in 3D! Unique player editor allows you to create the ultimate athlete. All new 1998 rosters including two new expansion teams: Arizona Diamondbacks and Tampa Bay Devil Rays! Tons of hidden secrets including super-fast pitches, outrageous curve balls, incredible home runs and more! Fantasy Teams: Create your own rotisserie league. Ultra-realistic conditions affect gameplay: Grass and turf. Day and night. Rain or shine.","descriptionSource":"http://www.gamefaqs.com/n64/915331-mike-piazzas-strike-zone","developer":"Devil's Thumb Entertainment","coverName":"Mike Piazza's StrikeZone (USA).n64","players":"2","publisher":"GT Interactive Software","esrb":"E - Everyone","rating":{"score":2.76,"count":39}},{"id":"milo-s-astro-lanes","title":"Milo's Astro Lanes","year":1998,"genres":["Sports"],"description":"Have you ever bowled against your buddies with a Nuclear Ball on a lane constructed out of an alien's tongue? Probably not. But now you can, as you bowl for the perfect game in Milo's Astro Lanes, the wackiest, most spaced-out bowling blast ever! Use awesome power-ups like the devastating Pea Ball, toxic Cosmic Slime and mighty White Dwarf to thwart your opponents or keep them from stopping you. This insane game is what the future of bowling is all about!","descriptionSource":"http://www.gamefaqs.com/n64/197944-milos-astro-lanes","developer":"Player 1","coverName":"Milo's Astro Lanes (USA).n64","players":"4","publisher":"Crave Entertainment","esrb":"E - Everyone","rating":{"score":2.71,"count":50}},{"id":"mischief-makers","title":"Mischief Makers","year":1997,"genres":["Platformer"],"description":"Professor Theo has been kidnapped by the imperial forces of the evil empire. Now his robotic personal assistant, Marina Liteyears, must save the day! Marina will get some help from the troops who have remained loyal to King Aster. With their help, she'll grab, shake and throw her way to the Professor! Besides rescuing the Professor, Marina will also join in the effort to rebel against that nasty, horrible and evil empire. So, Grab a controller and help our Super Heroine shake up the evil empire!","descriptionSource":"http://www.gamefaqs.com/n64/197950-mischief-makers","developer":"Treasure","coverName":"Mischief Makers (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.72,"count":161}},{"id":"mission-impossible","title":"Mission Impossible","year":1998,"genres":["Action"],"description":"Prepare to enter into the most demanding and dangerous Mission Impossible ever. Your mission, should you decide to accept it, will be to guide your team through a spectacular series of authorized worldwide missions encompassing over 20 levels of gameplay. Razor-sharp reflexes, the ability to make quick decisions, strategic thinking and an extremely high level of accuracy will prove essential. As always, should you, or any member of IM Force be caught or killed, the Secretary will disavow any knowledge of your actions. As usual, Ethan Hunt will be your point man. This game will not self-destruct in five seconds, but you may...","descriptionSource":"http://www.gamefaqs.com/n64/197954-mission-impossible","developer":"Infogrames","coverName":"Mission Impossible (USA).n64","players":"1","publisher":"Infogrames","esrb":"T - Teen","rating":{"score":3.35,"count":84}},{"id":"monaco-grand-prix","title":"Monaco Grand Prix","year":1999,"genres":["Racing"],"description":"Innovative 4-point physics engine calculates and monitors all 4 tires independently, creating the most precise simulation of Grand Prix style racing you will ever experience. 16 international courses, and all tracks to scale with realistic dimensions, scenery and environments. Up to 22 racers competing on each track. Arcade, Amateur, Expert and Pro modes. Indestructible cars or real-life damage, dents and shrapnel. Weather effects and multiple road conditions. Start as an inexperienced driver with an entry-level team. As your skill improves, you're invited to race for more prestigious teams.","descriptionSource":"http://www.gamefaqs.com/n64/197968-monaco-grand-prix","developer":"Ubisoft","coverName":"Monaco Grand Prix (USA).n64","players":"2","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":3.05,"count":50}},{"id":"monopoly","title":"Monopoly","year":1999,"genres":["Board Game"],"description":"Mr. Monopoly is your Master of Ceremonies as the rich characters and colorful worlds of the Atlantic City Boardwalk come to life in full 3D animation! The best-selling board game of all time is better than ever with incredible N64 real-time graphics and expanded features. Enjoy classic Monopoly gameplay with non-stop wheeling and dealing from the rolling lawns of Park Place to the lowly back yards of Baltic Avenue.","descriptionSource":"http://www.gamefaqs.com/n64/915911-monopoly","developer":"Minds-Eye Productions","coverName":"Monopoly (USA).n64","players":"4","publisher":"Hasbro Interactive","esrb":"E - Everyone","rating":{"score":3.03,"count":65}},{"id":"monster-truck-madness-64","title":"Monster Truck Madness 64","year":1999,"genres":["Racing"],"description":"Reach out and crush someone! The world's favorite monster truck game with high-octane off-road racing and bone-crushing battle modes! Mega multi-player mania. 19 trucks to control, including BIGFOOT, Grave Digger, and the WCW / nWo WrestleTrucks! Five battle games and two racing modes for 1 to 4 players. Ten treacherous tracks to tame. Play king of the hill in the Summit Rumble. Extreme off-road racing allows you to find your own shortcuts! Plenty of power-ups to give you an edge over the competition!","descriptionSource":"http://www.gamefaqs.com/n64/197980-monster-truck-madness-64","developer":"Edge of Reality","coverName":"Monster Truck Madness 64 (USA).n64","players":"4","publisher":"Rockstar Games","esrb":"E - Everyone","rating":{"score":3.36,"count":69}},{"id":"mortal-kombat-4","title":"Mortal Kombat 4","year":1998,"genres":["Fighting"],"description":"Shao Kahn has been defeated at the hands of Earth's warriors, and now Shinnok has escaped to his confines in the Netherealm. The war has resumed once again. This time, the battle CAN be won by mortals!","descriptionSource":"http://www.gamefaqs.com/n64/197989-mortal-kombat-4","developer":"Eurocom Entertainment Software","coverName":"Mortal Kombat 4 (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":3.67,"count":162}},{"id":"mortal-kombat-mythologies-sub-zero","title":"Mortal Kombat Mythologies: Sub-Zero","year":1997,"genres":["Fighting","Platformer"],"description":"An all-new storyline takes the Mortal Kombat myth to a new level! Heart-pounding action and hours of exploration will immerse you in Mortal Kombat as never before!","descriptionSource":"http://www.gamefaqs.com/n64/197992-mortal-kombat-mythologies-sub-zero","developer":"Avalanche Software","coverName":"Mortal Kombat Mythologies - Sub-Zero (USA).n64","players":"1","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":2.68,"count":109}},{"id":"mortal-kombat-trilogy","title":"Mortal Kombat Trilogy","year":1996,"genres":["Fighting"],"description":"Shao Kahn's final attempt to control the earth is upon us... 26 immediately playable characters plus 4 hidden characters! The new Aggressor Kombat Mode arms the quick and merciless with more strength and power to inflict heavy, damaging combinations! Over 30 moves and '-Alities' never seen in the arcade. New Brutalities let you pound opponents 'til they explode! New 3-on-3 Kombat Mode delivers a marathon fight-to-the-finish! 7 humiliating Stage Fatalities that send defeated opponents plummeting out of the arena to a grizzly death!","descriptionSource":"http://www.gamefaqs.com/n64/197996-mortal-kombat-trilogy","developer":"Midway","coverName":"Mortal Kombat Trilogy (USA).n64","players":"2","publisher":"GT Interactive Software","esrb":"M - Mature","rating":{"score":3.85,"count":155}},{"id":"mrc-multi-racing-championship","title":"MRC: Multi Racing Championship","year":1997,"genres":["Racing"],"description":"Sit down, strap in and hang on for the most extreme racing challenge the world has to offer. Race over a variety of terrains, battle the elements and secure your place among rally racing's most elite drivers. MRC's fully customizable settings let you equip your vehicle to exploit road conditions and weather to your advantage! Choose from 8 high-performance, fully customizable vehicles, plus two secret vehicles. Navigate through three challenging courses. Enjoy multiple viewing perspectives from a racer's bird's-eye perspective to behind-the-vehicle views. Speed through highly detailed backgrounds, amazing graphics and impressive sound effects for a realistic racing experience.","descriptionSource":"http://www.gamefaqs.com/n64/198014-mrc-multi-racing-championship","developer":"Genki","coverName":"MRC - Multi Racing Championship (USA).n64","players":"2","publisher":"Ocean Software","esrb":"E - Everyone","rating":{"score":3.38,"count":71}},{"id":"ms-pac-man-maze-madness","title":"Ms. Pac-Man: Maze Madness","year":2000,"genres":["Action","Puzzle"],"description":"Chomp your way through mystical worlds to save Pac-Land. Free the lastworlds of Pac-Land fromt he horrid witch Mesmeralda. Videogame's favorite heroine is back to save the day!","descriptionSource":"http://www.gamefaqs.com/n64/436659-ms-pac-man-maze-madness","developer":"Mass Media","coverName":"Ms. Pac-Man - Maze Madness (USA).n64","players":"4","publisher":"Namco Hometek","esrb":"E - Everyone","rating":{"score":3.77,"count":71}},{"id":"mystical-ninja-2-starring-goemon","title":"Mystical Ninja 2 Starring Goemon","year":1999,"genres":["Action","Platformer"],"description":"Goemon and all his friends are back in his greatest adventure yet! Goemon's Great Adventure combines classic Goemon platform action with an all-new twist. The evil time-traveling nun, Bismaru, has summoned Dochuki, a demon prince, to take over the Earth. But first, she wants to marry him! Can Goemon and his gang stop the demon? Can Dochuki escape the cloying clutches of the wacked-out nun? Will Ebisu ever beat his own dumpling eating record? It's an adventure you'll never forget!","descriptionSource":"http://www.gamefaqs.com/n64/915334-goemons-great-adventure","developer":"Konami Computer Entertainment Osaka","coverName":"Mystical Ninja 2 Starring Goemon (Europe) (En,Fr,De).n64","players":"2","publisher":"Konami","esrb":"E - Everyone","rating":{"score":3.97,"count":138}},{"id":"mystical-ninja-starring-goemon","title":"Mystical Ninja Starring Goemon","year":1998,"genres":["Action","Platformer"],"description":"A giant UFO has appeared over Oedo Castle, and the Mystical Ninja is off to save the world again! Control Goemon and his giant robot, Impact, Ebisimaru, a truly twisted ninja, Yae, the part-time militant mermaid, and Sasuke, a mechanical warrior. This brave band must travel from town to town, collecting information and purchasing helpful items in their quest to defeat the dreaded Peach Mountain Shoguns.","descriptionSource":"http://www.gamefaqs.com/n64/198022-mystical-ninja-starring-goemon","developer":"Konami Computer Entertainment Osaka","coverName":"Mystical Ninja Starring Goemon (USA).n64","players":"2","publisher":"Konami","esrb":"E - Everyone","rating":{"score":4.0,"count":143}},{"id":"nagano-winter-olympics-98","title":"Nagano Winter Olympics '98","year":1998,"genres":["Sports"],"description":"The Nagano Winter Olympic Games are here! Experience all of the thrills, spills and 'chills' as you compete for glory against the rest of the world. It's time to find out what you're made of...Can you bring home a medal? 12 exciting Olympic events! 16 different countries! 1-4 player action. Set new world records and save them to your Controller Pak. Real-time motion captured athletes.","descriptionSource":"http://www.gamefaqs.com/n64/198027-nagano-winter-olympics-98","developer":"Konami Computer Entertainment Osaka","coverName":"Nagano Winter Olympics '98 (USA).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":3.01,"count":51}},{"id":"namco-museum-64","title":"Namco Museum 64","year":1999,"genres":["Compilation"],"description":"Keep those quarters in your pants. With Namco Museum, you can set up your own arcade with classics like Pac-Man, Ms. Pac-Man, Galaga, Galaxian, Pole Position and Dig Dug. Genuine arcade translations with genuine arcade options so you can enjoy them at home on the N64! Change settings to control difficulty, number of lives, etc. simply by adjusting each game's dip switch. You're an arcade god! Get all the graphics, sounds and gameplay of the original coin-op hits. Authentic in every detail!","descriptionSource":"http://www.gamefaqs.com/n64/198030-namco-museum-64","developer":"Mass Media","coverName":"Namco Museum 64 (USA).n64","players":"2","publisher":"Namco","esrb":"E - Everyone","rating":{"score":3.74,"count":70}},{"id":"nascar-2000","title":"NASCAR 2000","year":1999,"genres":["Racing"],"description":"Prove you can handle the thunder! Featuring more drivers - Dale Earnhardt Jr., Tony Stewart and Adam Petty join the field of 33 NASCAR drivers and 7 legends. 18 licensed NASCAR tracks, now including Homestead-Miami Speedway. New TV and Crew Chief audio - Bob Jenkins and Benny Parsons in the booth plus Crew Chief and Spotter assistance. Wheel-to-wheel NASCAR competition - go head-to-head on the split-screen! Six driving views, including behind the wheel. Multiple modes - Quick Race, Single Race, or Championship Season.","descriptionSource":"http://www.gamefaqs.com/n64/198038-nascar-2000","developer":"Stormfront Studios","coverName":"NASCAR 2000 (USA).n64","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":2.68,"count":42}},{"id":"nascar-99","title":"NASCAR 99","year":1998,"genres":["Racing"],"description":"Race to Win with NASCAR Cars, Drivers, and Tracks! Race on the high banks, Night racing under the lights, Step in and take the wheel, head to racing, celebrate victory Earnhardt style.","descriptionSource":"http://www.gamefaqs.com/n64/198042-nascar-99","developer":"Stormfront Studios","coverName":"NASCAR 99 (USA).n64","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":2.69,"count":40}},{"id":"nba-courtside-2-featuring-kobe-bryant","title":"NBA Courtside 2 featuring Kobe Bryant","year":1999,"genres":["Sports"],"description":"Step onto the hardwood in the shoes of one of the most exciting and creative players in the NBA today. NBA Courtside 2 delivers unparalleled graphics, incredibly fluid player animations, an extremely wide range of one-player controls and all-new two-player controls. Create a rookie, and depending on how well you play, their skill ratings will increase or decrease. Quick Play, Season Play, Arcade Play, 3-Point Contest, Tournament Mode and four different Season modes.","descriptionSource":"http://www.gamefaqs.com/n64/198058-nba-courtside-2-featuring-kobe-bryant","developer":"Left Field Productions","coverName":"NBA Courtside 2 featuring Kobe Bryant (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.22,"count":48}},{"id":"nba-hangtime","title":"NBA Hangtime","year":1997,"genres":["Sports"],"description":"HANG ON for the time of your life! Soar through the air and slam one home against the big boys! This game ROCKS with special moves, burnin' hoops and high flyin' double dunks! All 29 NBA teams represented with 5-man rosters. Unique features include team fire, alley oops, double dunks and spin moves! Secret codes enable hidden characters, arenas and options. Play against up to four friends or team-up against the computer! Create your own player!","descriptionSource":"http://www.gamefaqs.com/n64/198062-nba-hangtime","developer":"Fun Com","coverName":"NBA Hangtime (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.69,"count":75}},{"id":"nba-in-the-zone-98","title":"NBA in the Zone '98","year":1998,"genres":["Sports"],"description":"For the first time ever NBA In The Zone '98 jams it home on the N64! Feel every rim rockin' dunk with the RUMBLE PAK feature as you take your team through a full regular season and into the NBA finals! All 29 NBA teams plus two NBA All-Star teams. Over 300 NBA players including Shaq and Sir Charles, as well as Penny, Pippen, Ewing, Malone and Glen Rice. Play Exhibition, the NBA Playoffs and the 1997-98 NBA Season Schedule. Full season stat tracking for every player. 300 different motion captured moves.","descriptionSource":"http://www.gamefaqs.com/n64/198064-nba-in-the-zone-98","developer":"Konami Computer Entertainment Osaka","coverName":"NBA in the Zone '98 (USA).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":2.85,"count":34}},{"id":"nba-in-the-zone-99","title":"NBA in the Zone '99","year":1999,"genres":["Sports"],"description":"The only place for hoops action on the Nintendo 64! All 29 NBA teams and over 300 real NBA players. Eight different camera angles with adjustable zoom. Create a player and customize over 30 different categories. All-new motion captured animations - the most realistic ever! Advanced play-calling techniques. Pin-point passing lets you play like the pros! Three-point shootout and slam dunk contest!","descriptionSource":"http://www.gamefaqs.com/n64/198066-nba-in-the-zone-99","developer":"Konami Computer Entertainment Osaka","coverName":"NBA in the Zone '99 (USA).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":2.15,"count":42}},{"id":"nba-in-the-zone-2000","title":"NBA in the Zone 2000","year":2000,"genres":["Sports"],"description":"It's called 'The Zone.' Marcus Camby found it in last year's NBA Playoffs. We took it from him and put it in this box. Open it up. Shoot the lights out! New dunking animations. Let it fly with the game on the line! All-new freethrow design - don't brick it! All-new camera angles! Smooth animations and jump shots!","descriptionSource":"http://www.gamefaqs.com/n64/258197-nba-in-the-zone-2000","developer":"Konami Computer Entertainment Osaka","coverName":"NBA in the Zone 2000 (USA).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":2.9,"count":43}},{"id":"nba-jam-2000","title":"NBA Jam 2000","year":1999,"genres":["Sports"],"description":"All-new 2-on-2 JAM mode featuring 50 dunks and awesome special effects! Custom 2-on-2 JAM mode courts, including street court. Authentic 5-on-5 simulation mode with actual team play styles like the Jazz Pick-and-Roll. Jaw-dropping ultra high-rez graphics! Unique signature moves like the crossover dribble. Create your own JAM player. All 29 teams and over 300 NBA superstars! Over 800 all-new motion captured moves by the 'X-Man' Xavier McDaniel!","descriptionSource":"http://www.gamefaqs.com/n64/198070-nba-jam-2000","developer":"Acclaim","coverName":"NBA Jam 2000 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":2.87,"count":61}},{"id":"nba-jam-99","title":"NBA Jam 99","year":1998,"genres":["Sports"],"description":"NBA JAM 99 has it all! Award-winning hi-rez graphics and 3D sports engine. Over 300 players with real-life faces and smooth skin textures. Authentic 5-on-5 team play styles like the Bulls triangle offense. Bonus 5-on-5 Jam mode with outrageous dunks. Create your own players and teams. Authentic team rosters, uniforms and schedules. Trade, sign, draft and release players. Bill Walton and Kevin Harlan bring you the courtside action. Motion capture by Keith Van Horn of the New Jersey Nets.","descriptionSource":"http://www.gamefaqs.com/n64/198072-nba-jam-99","developer":"Iguana Entertainment","coverName":"NBA Jam 99 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":2.58,"count":48}},{"id":"nba-live-2000","title":"NBA Live 2000","year":1999,"genres":["Sports"],"description":"Rim-Rockin', Take-Your-Soul-to-the-Hole Basketball! Jordan is back: Play Michael 1-on-1 and earn the right to play as Jordan and unlock him into the game! Prove it 1-on-1: Play as or against any current NBA player in the ultimate outdoor court challenge. All-new arcade mode: Over-the-top action, more monster dunks and all-new special effects! Quicker, cleaner moves: Work the crossover to perfection, take off for high-flying jams, or stop-and-pop a three-ball from downtown. Enhanced TV-style presentation: All-new camera angles and enhanced play-by-play for the ultimate live experience!","descriptionSource":"http://www.gamefaqs.com/n64/198077-nba-live-2000","developer":"NuFX","coverName":"NBA Live 2000 (USA) (En,Fr,De,Es).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":2.87,"count":45}},{"id":"nba-live-99","title":"NBA Live 99","year":1998,"genres":["Sports"],"description":"The Soul of Hoops comes to LIFE on the N64! Featuring classic NBA live gameplay, new high-flying Arcade mode, authentic high-res NBA arenas, All-Star action and 3-point shootouts! Real-life player reactions with Pro-Action AI. Real NBA motion captured moves. Create, trade, sign and release players. All the teams, all the players!","descriptionSource":"http://www.gamefaqs.com/n64/198086-nba-live-99","developer":"NuFX","coverName":"NBA Live 99 (USA) (En,Fr,De,Es,It).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.51,"count":41}},{"id":"nba-pro-98","title":"NBA Pro 98","year":1998,"genres":["Sports"],"description":"For the first time ever NBA In The Zone '98 jams it home on the N64! Feel every rim rockin' dunk with the RUMBLE PAK feature as you take your team through a full regular season and into the NBA finals! All 29 NBA teams plus two NBA All-Star teams. Over 300 NBA players including Shaq and Sir Charles, as well as Penny, Pippen, Ewing, Malone and Glen Rice. Play Exhibition, the NBA Playoffs and the 1997-98 NBA Season Schedule. Full season stat tracking for every player. 300 different motion captured moves.","descriptionSource":"http://www.gamefaqs.com/n64/198064-nba-in-the-zone-98","developer":"Konami Computer Entertainment Osaka","coverName":"NBA Pro 98 (Europe).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":2.85,"count":34}},{"id":"nba-pro-99","title":"NBA Pro 99","year":1999,"genres":["Sports"],"description":"The only place for hoops action on the Nintendo 64! All 29 NBA teams and over 300 real NBA players. Eight different camera angles with adjustable zoom. Create a player and customize over 30 different categories. All-new motion captured animations - the most realistic ever! Advanced play-calling techniques. Pin-point passing lets you play like the pros! Three-point shootout and slam dunk contest!","descriptionSource":"http://www.gamefaqs.com/n64/198066-nba-in-the-zone-99","developer":"Konami Computer Entertainment Osaka","coverName":"NBA Pro 99 (Europe).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":2.15,"count":42}},{"id":"nba-showtime-nba-on-nbc","title":"NBA Showtime: NBA on NBC","year":1999,"genres":["Sports"],"description":"The NBA like you've never seen it before! NBA Showtime: NBA on NBC brings you the top players from each team in a heart-pounding, pulse-racing above-the-rim match-up! You'll see the intensity on their faces and hear it in their voices, you'll feel the power of every pass and every shot! This is what the NBA is all about! Go for rebounds and 3-pointers in all 28 arenas around the league. Choose from over 130 real NBA players plus hidden characters!","descriptionSource":"http://www.gamefaqs.com/n64/198092-nba-showtime-nba-on-nbc","developer":"Eurocom Entertainment Software","coverName":"NBA Showtime - NBA on NBC (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.02,"count":34}},{"id":"nfl-blitz","title":"NFL Blitz","year":1998,"genres":["Sports"],"description":"No refs. No rules. No mercy! NFL Blitz is the NFL at its finest, featuring easy to run plays and unparalleled action, all in breakneck speed. With no penalties, no substitutions, and nowhere to hide, NFL Blitz is more than a game, it's an NFL highlight film! Fastest football gameplay ever, with easy to learn arcade-style play and simple point-and-shoot passing. In Season mode, you can play out the real '98 NFL football schedule. You might play in rain, snow or mud. And don't forget about those night games! Secret players, tons of power-ups and wild camera action will keep your adrenaline pumping!","descriptionSource":"http://www.gamefaqs.com/n64/198141-nfl-blitz","developer":"Midway","coverName":"NFL Blitz (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":4.06,"count":76}},{"id":"nfl-blitz-2000","title":"NFL Blitz 2000","year":1999,"genres":["Sports"],"description":"It's back and it's better than ever! NFL Blitz 2000 adds 4-player support, new offensive and defensive plays, realistic weather conditions, new stadiums and a Tournament mode! Customize offensive and defensive plays to your liking. Call audibles at the line of scrimmage. You've got control now! Passing made easy with new 'Blitz Passing' for one-touch long bombs! 'ON-FIRE' mode gives super power performance to your players! With non-stop action and a 'pick-it-up-and-play' learning curve, NFL BLITZ 2000 is THE game for every football fan!","descriptionSource":"http://www.gamefaqs.com/n64/198145-nfl-blitz-2000","developer":"Midway","coverName":"NFL Blitz 2000 (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.71,"count":46}},{"id":"nfl-blitz-2001","title":"NFL Blitz 2001","year":2000,"genres":["Sports"],"description":"No refs. No rules. No mercy! NFL Blitz is back as this year's exclusive 7-on-7 extreme-style football game with all the NFL teams, players and new hard-line features like... All-New Mini-Game Mode: Improve your skills and become a master of the controls. Exciting New Look: Awesome and outrageous animations and celebrations. New Killer Audio: Impressive sound FX, voice-overs and music. New Player Artificial Intelligence (AI): Easy to have fun, challenging to master. New stadiums, expanded play books, and updated rosters.","descriptionSource":"http://www.gamefaqs.com/n64/376261-nfl-blitz-2001","developer":"Midway","coverName":"NFL Blitz 2001 (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.92,"count":50}},{"id":"nfl-blitz-special-edition","title":"NFL Blitz: Special Edition","year":2001,"genres":["Sports"],"description":"Real Teams, Real Players, Real Attitude! Buckle your chin strap and brace yourself for adrenaline style football like only Blitz can dish out! NFL Blitz Special Edition is completely updated for the NFL 2001-02 season featuring current teams, schedules and uniforms. Prepare yourself to take command of the fastest football video game on earth!","descriptionSource":"http://www.gamefaqs.com/n64/569431-nfl-blitz-special-edition","developer":"Point of View","coverName":"NFL Blitz - Special Edition (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.59,"count":41}},{"id":"nfl-qb-club-2001","title":"NFL QB Club 2001","year":2000,"genres":["Sports"],"description":"All 31 NFL teams and 1,500 NFL players. Create and manage your own team. 31 team-specific playbooks or create your own. Play-by-play from Mike Patrick and Randy Cross. Precision artificial intelligence for real NFL gameplay. All-new Shoulder Charge feature for busting through defenders. Replay key moments of all 34 Super Bowls. All-new E-Z pass/catch controls. Incredibly detailed player models. Game speed maximized for the N64!","descriptionSource":"http://www.gamefaqs.com/n64/198158-nfl-qb-club-2001","developer":"High Voltage Software","coverName":"NFL QB Club 2001 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":2.91,"count":44}},{"id":"nfl-quarterback-club-2000","title":"NFL Quarterback Club 2000","year":1999,"genres":["Sports"],"description":"NFL Quarterback Club 2000 is here! Featuring 3rd generation ultra high-rez graphics for incredible NFL realism, over 1,200 new motion captured animations, all-new Pin Point Passing for unprecedented control, new player models with real-life faces, eye black and breathe strips. Choose from 31 team-specific playbooks or create your own. Replay key moments of all 33 Super Bowls with authentic game stats. Total team management - draft, sign, trade, release, create players.","descriptionSource":"http://www.gamefaqs.com/n64/198156-nfl-quarterback-club-2000","developer":"Acclaim","coverName":"NFL Quarterback Club 2000 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":2.61,"count":32}},{"id":"nfl-quarterback-club-98","title":"NFL Quarterback Club 98","year":1997,"genres":["Sports"],"description":"Exclusive NFL license for the 97-98 season. All 30 NFL teams, 3D rendered stadiums and over 1,500 players. Comprehensive NFL playbooks includes plays designed by two-time NFL MVP Brett Favre! Fifty historic and custom simulations allow gamers to replay classic NFL games and create new pressure-packed situations. Trade, create, draft, sign and release players. Create new teams and manage the salary cap. Track season-long player and team statistics including league leaders in 9 categories by Stats, Inc.","descriptionSource":"http://www.gamefaqs.com/n64/198160-nfl-quarterback-club-98","developer":"Iguana Entertainment","coverName":"NFL Quarterback Club 98 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.46,"count":33}},{"id":"nfl-quarterback-club-99","title":"NFL Quarterback Club 99","year":1998,"genres":["Sports"],"description":"The #1 football game on N64 just got a whole lot better! All 31 NFL teams, 3D rendered stadiums and over 1,500 players. Authentic team playbooks like the 49ers West Coast Defense and Steelers Ground Attack. All-new artificial intelligence developed by New York Jets offensive coordinator Charlie Weis. 250 all-new motion captured animations. Award-winning hi-rez graphics. Create your own players, coaches, teams, uniforms and playbooks!","descriptionSource":"http://www.gamefaqs.com/n64/198161-nfl-quarterback-club-99","developer":"Iguana Entertainment","coverName":"NFL Quarterback Club 99 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":2.48,"count":28}},{"id":"nhl-99","title":"NHL 99","year":1998,"genres":["Sports"],"description":"The most celebrated hockey game comes to the Nintendo 64. Battle along the boards, feed the open man, patrol the ice!Game Features:*Beginner lever - pick up and play!*Coaching strategies from Stanley Cup Winner Marc Crawford*Commentary by Bill Clement*5 game modes*18 top international teams*Updated 1998 roster-expansion Nashville Predators","descriptionSource":"http://www.gamefaqs.com/n64/198175-nhl-99","developer":"MBL Research","coverName":"NHL 99 (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.27,"count":49}},{"id":"nhl-blades-of-steel-99","title":"NHL Blades of Steel '99","year":1999,"genres":["Sports"],"description":"Non-stop NHL action! The newest all-star in the Konami Sports Series hits the ice! Get ready for a whole new game! NHL Blades of Steel '99 hits the ice with all the NHL players, stats and action. Motion captured animation, adjustable team strategies and fully detailed NHL stadiums with real ice conditions. Updated 98-99 rosters called out by NHL TV announcer Randy Hahn. Trade players and sign free agents. Full season stat tracking and league leaders.","descriptionSource":"http://www.gamefaqs.com/n64/366925-nhl-blades-of-steel-99","developer":"Konami Computer Entertainment Osaka","coverName":"NHL Blades of Steel '99 (USA).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":2.49,"count":39}},{"id":"nhl-breakaway-98","title":"NHL Breakaway 98","year":1998,"genres":["Sports"],"description":"Hit the ice with NHL Breakaway '98! All 26 NHL teams and over 600 players from the NHLPA. Variable player sizes, from hulking defensemen down to speedy wingers. Playbook based AI, so teams play their actual styles - forecheck, trap, dump and chase. Five gameplay modes: Exhibition, Season, Playoffs, Practice and Shoot-Out modes. Create players - assigned name actually appears on the player's jersey. Season wins provide bonus points which improve coaching, player development, injury therapies and more.","descriptionSource":"http://www.gamefaqs.com/n64/198179-nhl-breakaway-98","developer":"Iguana Entertainment","coverName":"NHL Breakaway 98 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.38,"count":37}},{"id":"nhl-breakaway-99","title":"NHL Breakaway 99","year":1998,"genres":["Sports"],"description":"All 27 NHL teams and over 600 players including the expansion Nashville Predators. Symbol-based passing and non-puck handler control. Real-life player sizes and weights. Create, trade, sign and release players. Set team style for physical play, power plays and penalty killing. Updated 1998-99 team jerseys, rosters, schedules and realigned divisions. Actual arena names for the ultimate NHL realism!","descriptionSource":"http://www.gamefaqs.com/n64/198181-nhl-breakaway-99","developer":"Iguana Entertainment","coverName":"NHL Breakaway 99 (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":2.31,"count":37}},{"id":"nhl-pro-99","title":"NHL Pro 99","year":1999,"genres":["Sports"],"description":"Non-stop NHL action! The newest all-star in the Konami Sports Series hits the ice! Get ready for a whole new game! NHL Blades of Steel '99 hits the ice with all the NHL players, stats and action. Motion captured animation, adjustable team strategies and fully detailed NHL stadiums with real ice conditions. Updated 98-99 rosters called out by NHL TV announcer Randy Hahn. Trade players and sign free agents. Full season stat tracking and league leaders.","descriptionSource":"http://www.gamefaqs.com/n64/366925-nhl-blades-of-steel-99","developer":"Konami Computer Entertainment Osaka","coverName":"NHL Pro 99 (Europe).n64","players":"4","publisher":"Konami","esrb":"E - Everyone","rating":{"score":2.49,"count":39}},{"id":"nightmare-creatures","title":"Nightmare Creatures","year":1998,"genres":["Action"],"description":"In 1834 on London's blackest eve, a secret cult known as The Brotherhood of Hecate rediscovered the key to man's unholiest fears. It was through this arcane act of terror that the evil leader of the Brotherhood, Adam Crowley, swore to take over the world... Ever since this fateful night, not a London street, alley or town square has escaped the screams of 'Nightmare Creatures!'","descriptionSource":"http://www.gamefaqs.com/n64/198197-nightmare-creatures","developer":"Kalisto","coverName":"Nightmare Creatures (USA).n64","players":"1","publisher":"Activision","esrb":"M - Mature","rating":{"score":3.54,"count":65}},{"id":"nuclear-strike-64","title":"Nuclear Strike 64","year":1999,"genres":["Shooter","Strategy"],"description":"NUCLEAR STRIKE 64 for the N64 features more enemies than ever before, bigger explosions, improved enemy targeting, and photo-realistic environments! Control more than ten different attack vehicles on smart battlefields, where the AI reacts to the player's behavior!","descriptionSource":"http://www.gamefaqs.com/n64/198217-nuclear-strike-64","developer":"Pacific Coast Power & Light","coverName":"Nuclear Strike 64 (USA).n64","players":"1","publisher":"THQ","esrb":"E - Everyone","rating":{"score":3.51,"count":69}},{"id":"off-road-challenge","title":"Off Road Challenge","year":1998,"genres":["Racing"],"description":"The END of the ROAD is only the BEGINNING. Strap yourself in and get ready to ride! Players battle the elements and each other in a race that takes them across 6 rugged courses including the Mojave Desert, Las Vegas and Pike's Peak! Choose Circuit Mode and climb your way to the top of the heap. Course terrain includes snow, water, asphalt, dirt, sand, rocks and mud. Four selectable trucks and four hidden trucks. Players can customize trucks in the Speed Shop.","descriptionSource":"http://www.gamefaqs.com/n64/198228-off-road-challenge","developer":"Avalanche Software","coverName":"Off Road Challenge (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.15,"count":63}},{"id":"ogre-battle-64-person-of-lordly-caliber","title":"Ogre Battle 64: Person of Lordly Caliber","year":2000,"genres":["RPG","Strategy"],"description":"The Holy Lodis Empire is planning the domination of the entire continent of Zeteginia! It is up to you to raise the flag of revolution and rid the land of the Lodis threat. Make decisions in real-time and take control of numerous characters to prove victorious on the battlefield and regain freedom for all people!","descriptionSource":"http://www.gamefaqs.com/n64/198230-ogre-battle-64","developer":"Quest","coverName":"Ogre Battle 64 - Person of Lordly Caliber (USA).n64","players":"1","publisher":"Atlus","esrb":"T - Teen","rating":{"score":4.04,"count":117}},{"id":"olympic-hockey-98","title":"Olympic Hockey 98","year":1998,"genres":["Sports"],"description":"For the first time in history, NHLPA pros are descending upon the Olympic Winter Games. Be a witness as regular season opponents join together as teammates. Kamensky and Yashin are laced up for Russia. Kariya and Roy get the nod for Canada. Modano and Leetch are in for the United States. The rosters are real. The graphics will make you sweat. It's country against country in this engagement. And the price of glory isn't gonna be pretty!","descriptionSource":"http://www.gamefaqs.com/n64/198232-olympic-hockey-98","developer":"Treyarch","coverName":"Olympic Hockey 98 (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":2.63,"count":30}},{"id":"operation-winback","title":"Operation WinBack","year":1999,"genres":["Shooter"],"description":"The first blast wiped out your Space Center. In just 3 hours, the hi-tech weapons satellite will strike again... It's your job to make sure that doesn't happen. Featuring intense third-person shooting action, precision laser-sighting aiming mechanism, immense 3D environments, battle heavily-armed boss characters and 'smart' enemies, 4-player Deathmatch, along with Lethal Tag, Cube Hunt, and Quick Draw.","descriptionSource":"http://www.gamefaqs.com/n64/199307-winback-covert-operations","developer":"Omega Force","coverName":"Operation WinBack (Europe) (En,Fr,De,Es,It).n64","players":"4","publisher":"Koei","esrb":"T - Teen","rating":{"score":3.53,"count":88}},{"id":"paper-mario","title":"Paper Mario","year":2001,"genres":["Platformer","RPG"],"description":"Mario pals around in an all-new action adventure! Mario's back in his first adventure since Super Mario 64, and this time, Bowser's bent on preventing a storybook ending. When Princess Peach is kidnapped, Mario plots to rescue the seven Star Spirits and rid the Mushroom Kingdom of Koopa's cruel cohorts. As he travels from the tropical jungles of Lavalava Island to the frosty heights of Shiver Mountain, he'll meet up with seven all-new companions... and he'll need help from each one or there'll be no happily ever after.","descriptionSource":"http://www.gamefaqs.com/n64/198849-paper-mario","developer":"Intelligent Systems","coverName":"Paper Mario (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.44,"count":486}},{"id":"paperboy","title":"Paperboy","year":1999,"genres":["Action"],"description":"There's a new Paperboy on your block! The arcade classic returns in 3D for an added dimension of fun. Deliver the Daily Sun while dodging grumpy neighbors, mad gorillas, vampires, and tornadoes. Find hidden routes and get air doing freestyle bike tricks. Only Paperboy can save the town from disaster! Featuring over 45 routes and 100 interactive obstacles, fully user-defined stunt system, and play as a Paperboy or girl!","descriptionSource":"http://www.gamefaqs.com/n64/198263-paperboy","developer":"High Voltage Software","coverName":"Paperboy (USA).n64","players":"1","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":2.21,"count":78}},{"id":"penny-racers","title":"Penny Racers","year":1999,"genres":["Racing"],"description":"Kart racing at its best! 13 cool Penny racers body styles. Perform insane stunts like power slides, drifting, wheelies and 'barrel rolls.' Nearly 100 upgrades, modifications and weapons to choose from. Four-player split-screen mayhem and a Track Editor for unlimited courses!","descriptionSource":"http://www.gamefaqs.com/n64/198272-penny-racers","developer":"Locomotive Corporation","coverName":"Penny Racers (USA).n64","players":"4","publisher":"THQ","esrb":"E - Everyone","rating":{"score":3.15,"count":65}},{"id":"perfect-dark","title":"Perfect Dark","year":2000,"genres":["Shooter","Stealth"],"description":"Step into the Dark... As Carrington Institute's most promising new Agent, Joanna Dark must uncover the truth behind the dataDyne Corporation's recent technological breakthroughs - breakthroughs which could have serious consequences for mankind.","descriptionSource":"http://www.gamefaqs.com/n64/198275-perfect-dark","developer":"Rare Ltd.","coverName":"Perfect Dark (USA).n64","players":"4","publisher":"Nintendo","esrb":"M - Mature","rating":{"score":4.42,"count":359}},{"id":"pga-european-tour","title":"PGA European Tour","year":2000,"genres":["Sports"],"description":"Realism, Authenticity, Sophistication and a European Touch! Play on four authentic European golf courses. Compete in European Tour and six non-tour modes. Genuine commentaries from BBC's famous Peter Allis. Go head-to-head with 64 established European stars. Realistic sound and weather effects. A true golf simulation with simple and intuitive feel.","descriptionSource":"http://www.gamefaqs.com/n64/198280-pga-european-tour","developer":"Infogrames","coverName":"PGA European Tour (USA).n64","players":"4","publisher":"Infogrames","esrb":"E - Everyone","rating":{"score":3.12,"count":38}},{"id":"pga-european-tour-golf","title":"PGA European Tour Golf","year":2000,"genres":["Sports"],"description":"Realism, Authenticity, Sophistication and a European Touch! Play on four authentic European golf courses. Compete in European Tour and six non-tour modes. Genuine commentaries from BBC's famous Peter Allis. Go head-to-head with 64 established European stars. Realistic sound and weather effects. A true golf simulation with simple and intuitive feel.","descriptionSource":"http://www.gamefaqs.com/n64/198280-pga-european-tour","developer":"Infogrames","coverName":"PGA European Tour Golf (Europe) (En,Fr,De,Es,It).n64","players":"4","publisher":"Infogrames","esrb":"E - Everyone","rating":{"score":3.12,"count":38}},{"id":"pilotwings-64","title":"Pilotwings 64","year":1996,"genres":["Flight"],"description":"Forget about those other flying games. This is the ultimate flight experience! Pilotwings 64 carries you off into a vast three-dimensional environment. Pilot several different vehicles and take in breathtaking sights! Successfully complete flight tests to earn your flight badge. Get a high enough score and you'll get a chance at bonus games such as Cannonball and Sky Diving! Soar into the wild blue yonder with Pilotwings 64!","descriptionSource":"http://www.gamefaqs.com/n64/198292-pilotwings-64","developer":"Nintendo","coverName":"Pilotwings 64 (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.97,"count":215}},{"id":"pok-mon-puzzle-league","title":"Pokémon Puzzle League","year":2000,"genres":["Puzzle"],"description":"Discover the most frantic, frenzied, fun-filled Pok&eacute;mon challenge ever--Pok&eacute;mon Puzzle League! Line up three or more blocks of the same type to clear them off the screen. Create chains and combos to send garbage to your opponent. Collect badges from other Pok&eacute;mon trainers to earn the right to enter the ultimate competition... a battle against the mysterious Puzzle Master!","descriptionSource":"http://www.gamefaqs.com/n64/913924-pokemon-puzzle-league","developer":"Nintendo","coverName":"Pokemon Puzzle League (USA).n64","players":"2","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.88,"count":138}},{"id":"pok-mon-snap","title":"Pokémon Snap","year":1999,"genres":["Shooter"],"description":"The Professor has asked you to capture the Wild Pokémon of Pok&eacute;mon island...on film! Tour the island in your ZERO-ONE vehicle and snap pictures of Pok&eacute;mon in their natural habitat. Wild Pok&eacute;mon are often camera-shy, so you'll have to use special items to bring them out in the open. Only the best shots will do for the Professor's Pok&eacute;mon Report, so sharpen your photography skills and get ready to SNAP!","descriptionSource":"http://www.gamefaqs.com/n64/198311-pokemon-snap","developer":"Hal","coverName":"Pokemon Snap (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.92,"count":282}},{"id":"pok-mon-snap-station","title":"Pokémon Snap Station","year":1999,"genres":["Shooter"],"description":"Professor Oak needs your help!\n\nThe Professor has asked you to capture the Wild Pokémon of Pokémon Island… on film! Tour the island in your ZERO-ONE vehicle and snap pictures of Pokémon in their natural habitat. Wild Pokémon are often camera-shy, so you’ll have to use special items to bring them out in the open. Only the best shots will do for the Professor’s Pokémon Report, so sharpen your photography skills and get ready to SNAP!\n\n* The first-ever N64 game to feature the world-famous Pokémon -- fully rendered in 3-D!\n* Explore the many environments of Pokémon Island, like the sunny beach, the mysterious caves and even a red-hot volcano!\n* Many different types of Pokémon inhabit the island. See how many you can catch on film!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/390","developer":"HAL Laboratory","coverName":"Pokemon Snap Station (USA) (Promo).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.92,"count":282}},{"id":"pok-mon-stadium","title":"Pokémon Stadium","year":2000,"genres":["Strategy"],"description":"At long last, all of your favorite Pok&eacute;mon are rady to go head-to-head on the N64&reg;! Whether you're battle a friend, a Gym Leader or a tournament contestant, you're about to witness some of the most spectacular battle scenes in Pok&eacute;mon history! Select a team from a huge stable of 'rental' battlers, or use the included N64 Transfer Pak&trade; to upload your own team from Pok&eacute;mon Red, Blue or Yellow! This Stadium is packed and ready to rock!","descriptionSource":"http://www.gamefaqs.com/n64/198312-pokemon-stadium","developer":"HAL Labs","coverName":"Pokemon Stadium (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.94,"count":260}},{"id":"pok-mon-stadium-2","title":"Pokémon Stadium 2","year":2001,"genres":["Strategy"],"description":"Hundreds of Pok&eacute;mon in Three-mendous 3-D! What's sweeter than victory in a Pok&eacute;mon battle! Victory in a 3-D arena on the N64&trade;! Set your strategy and stand back while your Pok&eacute;mon battle it out. You can even set the Pok&eacute;mon you've trained--fully rendered in 3-D and ready for battle!","descriptionSource":"http://www.gamefaqs.com/n64/452036-pokemon-stadium-2","developer":"HAL Labs","coverName":"Pokemon Stadium 2 (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.96,"count":218}},{"id":"polaris-snocross","title":"Polaris SnoCross","year":2000,"genres":["Racing"],"description":"If it doesn't say Polaris... it ain't SnoCross! Join the Polaris Snowmobile Racing Team and dare to tame the mountain! Pull off a variety of insane tricks as you master the challenges of monster jumps, hidden pitfalls, shortcuts, and treacherous terrain. Race against fiercely competitive AI characters, or take on your own friends in multi-player mode. Feel your customized Polaris sled move, twist and turn just like a real snowmobile!","descriptionSource":"http://www.gamefaqs.com/n64/256695-polaris-snocross","developer":"Vicarious Visions","coverName":"Polaris SnoCross (USA).n64","players":"4","publisher":"Vatical Entertainment","esrb":"E - Everyone","rating":{"score":2.96,"count":52}},{"id":"power-rangers-lightspeed-rescue","title":"Power Rangers: Lightspeed Rescue","year":2000,"genres":["Action"],"description":"POWER RANGERS RESCUE READY! The Power Rangers are saving the world on Nintendo 64! Rescue innocent people from the battlings. Drive cool Power Rangers vehicles! Fight huge monsters in awesome environments. Battle against your friends in the Megazord Arena!","descriptionSource":"http://www.gamefaqs.com/n64/562948-power-rangers-lightspeed-rescue","developer":"Mass Media","coverName":"Power Rangers - Lightspeed Rescue (USA).n64","players":"2","publisher":"THQ","esrb":"E - Everyone","rating":{"score":2.07,"count":52}},{"id":"premier-manager-64","title":"Premier Manager 64","year":1999,"genres":["Simulation","Sports"],"description":"Think you can manage a club better than the professionals? The team, the tactics, the sponsorship deals, the finances, the board of directors... Premier Manager 64 gives you everything you need to take on the toughest challenge of all. This is not just a game; this is total football management.","descriptionSource":"http://www.gamefaqs.com/n64/578921-premier-manager-64","developer":"Gremlin Interactive","coverName":"Premier Manager 64 (Europe).n64","players":"1","publisher":"Gremlin Interactive","esrb":"Not Rated","rating":{"score":2.67,"count":32}},{"id":"quake-64","title":"Quake 64","year":1998,"genres":["Shooter"],"description":"Heart-pounding gameplay, spectacular graphics and brain-shattering sound effects - guaranteed to have players jumping out of their skins! Incorporates the ferocity of the single-player game with the ultimate bloodlust of the two-player splitscreen Deathmatch. A true 3D polygonal environment that includes the most horrific creatures to grace a console. Startling dynamic lighting, levels designed by the masters, and an arsenal of the most awesome weaponry to match.","descriptionSource":"http://www.gamefaqs.com/n64/198375-quake","developer":"Midway Studios - San Diego","coverName":"Quake 64 (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":3.49,"count":107}},{"id":"quake-ii","title":"Quake II","year":1999,"genres":["Shooter"],"description":"Authentic Nintendo 64 effects and newer, fiercer levels pack stunning graphic detail into an already vicious version of Quake II! Featuring Two-, Three-, and Four-player Deathmatch, fully customizable controls and save game features, this masterpiece takes gaming to an undefined level! Eerie environments of light and shadow loom within newly designed, mission-based levels not found in the PC version. Incredible engine speed and fluidity intensify each level to a fast-paced, high-action gameplay experience!","descriptionSource":"http://www.gamefaqs.com/n64/198378-quake-ii","developer":"Raster","coverName":"Quake II (USA).n64","players":"4","publisher":"Activision","esrb":"M - Mature","rating":{"score":3.72,"count":87}},{"id":"quest-64","title":"Quest 64","year":1998,"genres":["RPG"],"description":"Celtland has been cast into chaos by the theft of Eletale's Book.This mystical volume contains the secrets of the Spirit Tamers.Control Brian, a magician's apprentice, as he explores the expansive countryside and villages on his quest.If he does not reclaim the book, the Kingdom of Celtland will be cast into darkness forever.","descriptionSource":"http://www.gamefaqs.com/n64/198386-quest-64","developer":"Imagineer","coverName":"Quest 64 (USA).n64","players":"1","publisher":"Konami","esrb":"E - Everyone","rating":{"score":3.47,"count":115}},{"id":"racing-simulation-2","title":"Racing Simulation 2","year":1999,"genres":["Racing"],"description":"Innovative 4-point physics engine calculates and monitors all 4 tires independently, creating the most precise simulation of Grand Prix style racing you will ever experience. 16 international courses, and all tracks to scale with realistic dimensions, scenery and environments. Up to 22 racers competing on each track. Arcade, Amateur, Expert and Pro modes. Indestructible cars or real-life damage, dents and shrapnel. Weather effects and multiple road conditions. Start as an inexperienced driver with an entry-level team. As your skill improves, you're invited to race for more prestigious teams.","descriptionSource":"http://www.gamefaqs.com/n64/197968-monaco-grand-prix","developer":"Ubisoft","coverName":"Monaco Grand Prix - Racing Simulation 2 (Europe) (En,Fr,Es,It).n64","players":"2","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":3.05,"count":50}},{"id":"rakuga-kids","title":"Rakuga Kids","year":1998,"genres":["Fighting"],"description":"Twinkle Town is the perfect picture of chaos. The local Kids have made their Graffiti heroes miraculously come to life with some magic crayons.Now their wild cartoon characters are ready to unleash a fast, funny and furious fighting game, where fun comes first.Rakugakids takes grafitti drawings and lets you control them in this crazy fight of fantasy.","descriptionSource":"http://www.gamefaqs.com/n64/562842-rakuga-kids","developer":"KCEK","coverName":"Rakuga Kids (Europe).n64","players":"2","publisher":"Konami","esrb":"Not Rated","rating":{"score":2.81,"count":54}},{"id":"rally-challenge-2000","title":"Rally Challenge 2000","year":2000,"genres":["Racing"],"description":"RALLY CHALLENGE 2000 takes you on a scorching tour around the world. Get behind the wheel of one of nine authentic WRC cars, each with its own unique settings for speed, torque and steering. Experience road rage of global proportions. Nasty weather and wicked terrain make even straightaways life-threatening. Go it alone or head-to-head with up to four players. Check out instant replay of all the action from multiple angles. Keep your road rage in check - collision damage could put you on the sidelines.","descriptionSource":"http://www.gamefaqs.com/n64/354052-rally-challenge-2000","developer":"Genki","coverName":"Rally Challenge 2000 (USA).n64","players":"4","publisher":"Southpeak Interactive","esrb":"E - Everyone","rating":{"score":3.0,"count":45}},{"id":"rampage-2-universal-tour","title":"Rampage 2: Universal Tour","year":1999,"genres":["Action"],"description":"Your 3 favorite human-munching badly-behaved mutants have been captured! Unfortunately, for the humans inhabiting Earth, brand new mutants have been sent to rescue George, Lizzy, and Ralph. You'll meet Ruby the Lobster, Boris the Rhino, and Curtis the Rat as they destroy cities in North America, Asia, and Europe! Get ready for destruction, mayhem, alien exterminators and the best buffet in town - the people of Earth! Hope you're hungry!","descriptionSource":"http://www.gamefaqs.com/n64/198408-rampage-2-universal-tour","developer":"Avalanche Software","coverName":"Rampage 2 - Universal Tour (USA).n64","players":"3","publisher":"Midway Home Entertainment","esrb":"T - Teen","rating":{"score":3.27,"count":104}},{"id":"rampage-world-tour","title":"Rampage: World Tour","year":1998,"genres":["Action"],"description":"A wild smash-'em-up romp with universal appeal! Simple enough for any player. Plenty of depth and challenge to appeal to serious gamers as well. Bring a friend or two on a non-stop RAMPAGE while you inflict some major damage and destruction. Demolish buildings, swat down aircraft, eat people and rack up points, while destroying entire cities! More than 130 standard levels, 14 bonus levels, 4 grudge match levels and many hidden levels! Special bosses and some tasty humans give Lizzy, George or Ralph a major health boost.","descriptionSource":"http://www.gamefaqs.com/n64/198410-rampage-world-tour","developer":"Saffire","coverName":"Rampage - World Tour (USA).n64","players":"3","publisher":"Midway Home Entertainment","esrb":"T - Teen","rating":{"score":3.53,"count":116}},{"id":"rat-attack","title":"Rat Attack!","year":2000,"genres":["Puzzle"],"description":"RAT ATTACK! Nuke 'em! The mutant rat invasion is on! And the little rodents have a freakish plot: create bazillions of bizarre and deadly rats bent on trashing everything they can sink their teeth into! YOU gotta stop 'em! Become one of the SCRATCH CATS, an elite squad of eight cat commandos dedicated to protecting the world from its biggest threat yet! Over 50 action-packed levels, 15 specifically designed for multi-player. Six Scratch Cat characters to choose from, plus two hidden 'super' cats!","descriptionSource":"http://www.gamefaqs.com/n64/198414-rat-attack","developer":"Pure Entertainment","coverName":"Rat Attack! (USA) (En,Fr,De,Es,It,Nl).n64","players":"4","publisher":"Mindscape","esrb":"E - Everyone","rating":{"score":3.45,"count":40}},{"id":"rayman-2-the-great-escape","title":"Rayman 2: The Great Escape","year":1999,"genres":["Platformer"],"description":"Enter a massive 3-D action adventure of amazing beauty and challenge. The pirate terror has enslaved the world and only Rayman's speed, agility, and magical powers can save all. Race and battle across 45 intricately designed areas - rainforests, jungles, narrow canyon passes, even into the mighty pirate ship itself.","descriptionSource":"http://www.gamefaqs.com/n64/198423-rayman-2-the-great-escape","developer":"Ubisoft Montpellier","coverName":"Rayman 2 - The Great Escape (USA) (En,Fr,De,Es,It).n64","players":"1","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":4.07,"count":139}},{"id":"razor-freestyle-scooter","title":"Razor Freestyle Scooter","year":2001,"genres":["Sports"],"description":"Razor Freestyle Scooter is your opportunity to control urban thrashers who cut through massive radical environments. Throw tight tricks like heel-flips, candybars, supermen and can-cans. Add to the timebar by pulling off phat air on insane ramps and halfpipes. Grind ledges, high-flying wires, barrels and benches. Collect wheels to unlock the coolest parks and characters!","descriptionSource":"http://www.gamefaqs.com/n64/567306-razor-freestyle-scooter","developer":"Titanium Studios","coverName":"Razor Freestyle Scooter (USA).n64","players":"2","publisher":"Crave Entertainment","esrb":"E - Everyone","rating":{"score":2.54,"count":35}},{"id":"re-volt","title":"Re-Volt","year":1999,"genres":["Racing"],"description":"Radio control racing done right! Rip it up with realistic physics, power-packed weapons and interactive environments! Blast through traffic with bottle rockets, water balloons and oil slicks! Four-player racing madness! Stunt Track, Battle Tag and four different racing modes. Barrel through museums, trash toy stores or design your own track with our custom editor! True R/C physics! Objects and surfaces affect the action just like real life.","descriptionSource":"http://www.gamefaqs.com/n64/198471-re-volt","developer":"Acclaim","coverName":"Re-Volt (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.45,"count":66}},{"id":"ready-2-rumble-boxing","title":"Ready 2 Rumble Boxing","year":1999,"genres":["Fighting","Sports"],"description":"Let's Get Ready To Rumble. 16 fighters who are ready to get down and get it on. An arsenal of taunts and verbal assaults. In-game announcements by Michael Buffer. Low blows, lunging hooks, overhead punches and more. Hidden combo moves for crushing punishment. Rumble power unleashes extreme moves. Arcade, championship and training modes. Create and save your ideal boxer.","descriptionSource":"http://www.gamefaqs.com/n64/198429-ready-2-rumble-boxing","developer":"Point of View","coverName":"Ready 2 Rumble Boxing (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"T - Teen","rating":{"score":3.74,"count":69}},{"id":"ready-2-rumble-boxing-round-2","title":"Ready 2 Rumble Boxing: Round 2","year":2000,"genres":["Fighting","Sports"],"description":"The King of the Ring is back! 17 boxers: Afro Thunder and company return with 13 all-new characters including four special celebrity characters! New rumble modes: Save up your power for a Knock-Em-Out-of-the-Ring Punch! Party modes: New Tournament and Team Battle modes for head-to-head competition for you and all your friends. New mini-games: Increase your speed, strength and agility by training with rumble pads, jump rope, speed bag and more. Improved single-player AI: Smarter, harder, and faster!","descriptionSource":"http://www.gamefaqs.com/n64/437242-ready-2-rumble-boxing-round-2","developer":"Point of View","coverName":"Ready 2 Rumble Boxing - Round 2 (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"T - Teen","rating":{"score":3.17,"count":57}},{"id":"resident-evil-2","title":"Resident Evil 2","year":1999,"genres":["Action","Horror"],"description":"Ready or not, the terror of Resident Evil 2 is here.In chapter one, the case of the disastrous T-virus outbreak--a mutagenic toxin designed for biological weapons--was eventually closed but the experiments were far from over.Control the destiny of Leon Kennedy or Claire Redfield as their nightmare begins when a biotech terror runs rampant in Raccoon City.Relentless zombies and hideous monsters are all out for a taste of your blood.If the suspense doesn't kill you, something else will.","descriptionSource":"http://www.gamefaqs.com/n64/198457-resident-evil-2","developer":"Angel Studios","coverName":"Resident Evil 2 (USA).n64","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.25,"count":179}},{"id":"road-rash-64","title":"Road Rash 64","year":1999,"genres":["Action","Racing"],"description":"180 MPH slap in the face, anyone? Multi-player modes for up to four players including Deathmatch, Cop Mode and Tag. New weapons and moves like the dreaded spoke jam. Intense pack brawling, including grudges and alliances. 200 miles of interconnected tracks and environments. Over 25 bikes and characters to choose from. Thrashin' soundtrack featuring Sugar Ray, The Mermen and more!","descriptionSource":"http://www.gamefaqs.com/n64/198491-road-rash-64","developer":"Pacific Coast Power & Light","coverName":"Road Rash 64 (USA).n64","players":"4","publisher":"THQ","esrb":"T - Teen","rating":{"score":3.29,"count":109}},{"id":"roadsters","title":"Roadsters","year":1999,"genres":["Racing"],"description":"Buckle up and brace yourself as you take the wheel of a tricked-out, asphalt-kicking, supercharged Roadster. Hurtle around one of ten different adrenaline-pumping tracks at 200 MPH. Feel the wind tearing your hair from its roots. Knock elbows with the competition. You're in a rocket ship without a roof. You're Roadster racing, baby! Win races. Win cash. Turn your Roadster into a monster, 'cause you'll need all the help you can get. Out here the speeds are faster, the turns are tighter and if you blink, you're roadkill!","descriptionSource":"http://www.gamefaqs.com/n64/198496-roadsters","developer":"Titus Software","coverName":"Roadsters (USA) (En,Fr,Es).n64","players":"4","publisher":"Titus Software","esrb":"E - Everyone","rating":{"score":3.55,"count":55}},{"id":"robotron-64","title":"Robotron 64","year":1998,"genres":["Shooter"],"description":"YOU CAN SAVE THE WORLD! All the excitement and speed of the original classic is back and updated with state-of-the-art graphics specifically designed for the N64. Intense, non-stop action versus a mechanical army of robots. 200 levels of frantic destruction in detailed, ever-changing 3D arenas. Multiple power-ups scattered throughout each level offer more powerful weaponry, as waves of never-ending Robotrons continue the attack. All the classic Robotron characters return, plus 26 new enemies, each rendered in 3D. Multitudes of hidden cheat codes and bonus rounds.","descriptionSource":"http://www.gamefaqs.com/n64/198501-robotron-64","developer":"Player 1","coverName":"Robotron 64 (USA).n64","players":"2","publisher":"Crave Entertainment","esrb":"T - Teen","rating":{"score":3.63,"count":78}},{"id":"rocket-robot-on-wheels","title":"Rocket: Robot on Wheels","year":1999,"genres":["Platformer"],"description":"Whoopie World, the greatest amusement park ever, is ready to open, but second-banana park mascot, Jojo the Raccoon, has gone nuts. He's taken over the park! Can Rocket, the most advanced amusement park robot ever, save the day? Rocket's a one wheel wonder with double-jump booster rockets and 7 cool cars to drive. He's got a tractor beam that can pick up almost anything, swing from ledges, trees, even toss freeze & smash objects. Rocket's got the moves & he's got the tools to make things right.","descriptionSource":"http://www.gamefaqs.com/n64/198506-rocket-robot-on-wheels","developer":"Sucker Punch","coverName":"Rocket - Robot on Wheels (USA).n64","players":"1","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":3.56,"count":72}},{"id":"rr64-ridge-racer-64","title":"RR64: Ridge Racer 64","year":2000,"genres":["Racing"],"description":"Race into action with RR64! It's got all the fast-paced arcade action you've come to expect from the Ridge Racer name, plus extra features you've never seen before! Race with up to four players simultaneously on the same screen. Compete on never-before-seen tracks and witness amazing special effects. You've never seen a Ridge Racer like this! Choose from 25 cars and race on 9 different courses.","descriptionSource":"http://www.gamefaqs.com/n64/198475-ridge-racer-64","developer":"Nintendo","coverName":"RR64 - Ridge Racer 64 (USA).n64","players":"4","publisher":"Nintendo of America","esrb":"E - Everyone","rating":{"score":3.93,"count":120}},{"id":"rugrats-in-paris-the-movie","title":"Rugrats in Paris: The Movie","year":2000,"genres":["Platformer"],"description":"The Rugrats are going to Paris! Join Tommy, Chuckie, Kimi and the rest of the Rugrats gang as they journey through Paris and EUROREPTARLAND. France will never be the same. Roar through the streets of Paris, win carnival games and prizes, get choppin' with Chuckie Chan, bump your buddies on the bumper cars!","descriptionSource":"http://www.gamefaqs.com/n64/913697-rugrats-in-paris-the-movie","developer":"Avalanche Software","coverName":"Rugrats in Paris - The Movie (USA).n64","players":"4","publisher":"THQ","esrb":"E - Everyone","rating":{"score":2.93,"count":46}},{"id":"rugrats-scavenger-hunt","title":"Rugrats: Scavenger Hunt","year":1999,"genres":["Board Game","Strategy"],"description":"Scavenge through three games in one! Reptar Rally: The babies visit Reptar on his candy island to help him collect as many sweets as possible. Angelica's Temple of Gloom: The babies are transported to the ancient Aztec Temple of Kokobola. Find all the pieces to the broken Aztec statue before Angelica does, or else... Pirate Treasure Hunt: Play diaper-to-diaper and search through a sunken pirate ship looking for hidden tresure!","descriptionSource":"http://www.gamefaqs.com/n64/915333-rugrats-scavenger-hunt","developer":"Realtime Associates","coverName":"Rugrats - Scavenger Hunt (USA).n64","players":"4","publisher":"THQ","esrb":"E - Everyone","rating":{"score":2.32,"count":52}},{"id":"rugrats-treasure-hunt","title":"Rugrats: Treasure Hunt","year":1999,"genres":["Board Game","Strategy"],"description":"Scavenge through three games in one! Reptar Rally: The babies visit Reptar on his candy island to help him collect as many sweets as possible. Angelica's Temple of Gloom: The babies are transported to the ancient Aztec Temple of Kokobola. Find all the pieces to the broken Aztec statue before Angelica does, or else... Pirate Treasure Hunt: Play diaper-to-diaper and search through a sunken pirate ship looking for hidden tresure!","descriptionSource":"http://www.gamefaqs.com/n64/915333-rugrats-scavenger-hunt","developer":"Realtime Associates","coverName":"Rugrats - Treasure Hunt (Europe).n64","players":"4","publisher":"THQ","esrb":"E - Everyone","rating":{"score":2.32,"count":52}},{"id":"rush-2-extreme-racing-usa","title":"Rush 2: Extreme Racing USA","year":1998,"genres":["Racing"],"description":"Performance... Adrenaline... Speed! These are the ingredients in the next generation of Rush Mania! Feel the Rush once again as you blast through some of the hottest spots in America! You want death-defying jumps and treacherous shortcuts? You'll find 'em, along with much more, in 8 new venues! Time to polish your speed demon driving skills! You'll be smokin' the radar guns in places like Las Vegas, New York City, Hawaii, Los Angeles and Seattle. And of course, there's that garden spot known as Alcatraz Island. Yeah, we're talkin' about The Rock.","descriptionSource":"http://www.gamefaqs.com/n64/198527-rush-2-extreme-racing-usa","developer":"Atari Games (Midway)","coverName":"Rush 2 - Extreme Racing USA (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.73,"count":95}},{"id":"s-c-a-r-s","title":"S.C.A.R.S.","year":1998,"genres":["Racing"],"description":"Untamed racing in the ultimate killer cars! Nine brutal 3D tracks across volcanoes, jungles, oceans and more. Nine killer cars armed with missiles, time bombs, boomerangs and more. Night and rain racing. Challenge, Grand Prix, and Custom Cup racing! Two and four player racing.","descriptionSource":"http://www.gamefaqs.com/n64/198533-scars","developer":"Vivid Image","coverName":"S.C.A.R.S. (USA).n64","players":"4","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":3.38,"count":62}},{"id":"san-francisco-rush-2049","title":"San Francisco Rush 2049","year":2000,"genres":["Racing"],"description":"San Francisco Rush 2049 - The original arcade racing hit now with three action-packed games in one! Race Mode: Scream through futuristic San Francisco tracks. Stunt Mode: Insane air and gravity-defying tricks. Battle Mode: Lock and load your way through eight killer battle arenas. Also featuring 19 all-new tracks and 13 selectable cars, with all-new customization! New and improved graphics and vehicle physics. Experience and 'feel' the RUSH!","descriptionSource":"http://www.gamefaqs.com/n64/198529-san-francisco-rush-2049","developer":"Midway","coverName":"San Francisco Rush 2049 (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.59,"count":87}},{"id":"san-francisco-rush-extreme-racing","title":"San Francisco Rush: Extreme Racing","year":1997,"genres":["Racing"],"description":"Put the pedal to the metal, smoke the tires, and pour on the speed with San Francisco Rush! Hit the road in one of eight unique race cars ranked in four distinct performance classes. Burn rubber through the 3D modeled hills and landmarks of San Francisco. Choose from six accurately detailed tracks that can be adjusted with the games 'Mirror' or 'Backwards' options for a total of 24 incredible tracks! Spectacular hidden shortcuts on each track! Realistic sensation of catching air and landing hard - supports N64 Rumble Pak!","descriptionSource":"http://www.gamefaqs.com/n64/198546-san-francisco-rush-extreme-racing","developer":"Atari Games (Midway)","coverName":"San Francisco Rush - Extreme Racing (USA) (En,Fr,De).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.61,"count":103}},{"id":"scooby-doo-classic-creep-capers","title":"Scooby-Doo!: Classic Creep Capers","year":2001,"genres":["Adventure"],"description":"Like wow! Scooby and the gang face off against some all-time classic villains, including The Witch Doctor, The Black Knight, and The Snow Ghost. Help guide Scooby and the gang through three classic episodes and one all-new episode. It's your job to search for clues and unmask the ghoulish villains!","descriptionSource":"http://www.gamefaqs.com/n64/374845-scooby-doo-classic-creep-capers","developer":"Terraglyph Interactive Studios","coverName":"Scooby-Doo! - Classic Creep Capers (USA).n64","players":"1","publisher":"THQ","esrb":"E - Everyone","rating":{"score":3.16,"count":68}},{"id":"shadow-man","title":"Shadow Man","year":1999,"genres":["Action","Adventure","Horror"],"description":"He is coming, stalking criminals in spirit world and real world. A possessed man is coming, a voodoo mask in his chest and lines of power in his back. Shadow Man is coming. Trailing evil from Liveside to Deadside. To stop an apocalypse. To save your soul.","descriptionSource":"http://www.gamefaqs.com/n64/198601-shadow-man","developer":"Acclaim Studios Teeside","coverName":"Shadow Man (USA).n64","players":"1","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.82,"count":91}},{"id":"shadowgate-64-trials-of-the-four-towers","title":"Shadowgate 64: Trials of the Four Towers","year":1999,"genres":["Adventure"],"description":"An ancient evil stirs. Reaching from beyond the grave, it warps the minds of men who would release it. Soon, very soon, the dreaded Warlock Lord will again be unleashed upon the land. This time there is no one to stop it. No one except for an unfortunate Halfling, caught in the middle of the cataclysmic events events unfolding within the ruins of Castle Shadowgate... This all-new adventure catapults you back into the world of the award-wining computer and NES masterpiece. A magical world now surrounding you in full 3D splendor. A world of wonder, which beckons you to unravel its mysteries.","descriptionSource":"http://www.gamefaqs.com/n64/198608-shadowgate-64-trials-of-the-four-towers","developer":"Infinite Ventures","coverName":"Shadowgate 64 - Trials of the Four Towers (USA) (En,Es).n64","players":"1","publisher":"Kotobuki System","esrb":"E - Everyone","rating":{"score":3.43,"count":76}},{"id":"snowboard-kids","title":"Snowboard Kids","year":1998,"genres":["Racing"],"description":"Rip it up on nine courses worth of various terrain! Pull over 36 big air tricks in your quest for the ultimate deck. And with Rumble Pak compatibility, you'll definitely feel it if you stick those maneuvers or not! Featuring five characters, each with unique moves, five modes of play, including pipes, four-player battle races, and nine customizable beginning boards.","descriptionSource":"http://www.gamefaqs.com/n64/366874-snowboard-kids","developer":"Racdym","coverName":"Snowboard Kids (USA).n64","players":"4","publisher":"Atlus","esrb":"E - Everyone","rating":{"score":3.88,"count":106}},{"id":"snowboard-kids-2","title":"Snowboard Kids 2","year":1999,"genres":["Racing"],"description":"Just when you thought it was safe to hit the slopes... Here comes those kids to tear it up again in the outrageous sequel, Snowboard Kids 2. However, all is not well in Snow Town. Enter Damien, the mischievous little brat from the underworld... and he'll stop at nothing to ruin the fun of our Snowboard Kids. It's up to you and the rest of the Snowboard Kids to defeat the evil Damien!","descriptionSource":"http://www.gamefaqs.com/n64/198684-snowboard-kids-2","developer":"Racdym","coverName":"Snowboard Kids 2 (USA).n64","players":"4","publisher":"Atlus","esrb":"E - Everyone","rating":{"score":4.06,"count":105}},{"id":"south-park","title":"South Park","year":1998,"genres":["Shooter"],"description":"A giant comet is heading toward South Park and it's up to you to save them! Beware of anal-probing aliens, big evil clones, and demented turkeys. It's the only game big enough for Cartman's big fat ass. Sweet environments without any lame, tree-hugging hippies. Play as all your favorite South Park characters. Authentic voices from South Park, including Isaac Hayes as Chef. Howdy-ho your way through mega four-player action!","descriptionSource":"http://www.gamefaqs.com/n64/198710-south-park","developer":"Iguana Entertainment","coverName":"South Park (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.24,"count":122}},{"id":"south-park-rally","title":"South Park Rally","year":2000,"genres":["Racing"],"description":"Get drivin' with your bad self! Face off against Cartman, Grandpa, Scuzzlebutt, Starvin' Marvin and the rest of South Park in the wildest, raunchiest road race ever. Loaded with dozens of insane vehicles and sweet custom sound-bites! Break like the wind with Terrance and Phillip! Honk if you're packin' sweet pick-ups!","descriptionSource":"http://www.gamefaqs.com/n64/198713-south-park-rally","developer":"Tantalus Interactive","coverName":"South Park Rally (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.26,"count":76}},{"id":"south-park-chef-s-luv-shack","title":"South Park: Chef's Luv Shack","year":1999,"genres":["Party","Quiz"],"description":"It's one big multi-player luv-in! All your favorite South Park characters are waiting for you at Chef's Luv Shack. Spreading the hot buttered game lovin' with dozens of crazy mini-games. Testing your South Park knowledge with outrageous trivia questions. And telling it like it is with insane sound-bites! Featuring authentic voices from South Park including Isaac Hayes as Chef!","descriptionSource":"http://www.gamefaqs.com/n64/198717-south-park-chefs-luv-shack","developer":"Acclaim Studios Austin","coverName":"South Park - Chef's Luv Shack (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.28,"count":59}},{"id":"space-invaders","title":"Space Invaders","year":1999,"genres":["Shooter"],"description":"Attention all Earthlings!Relentless alien hordes have been identified near you.Be aware - the classic arcade update has proven to be even more dangerously addictive than ever before.Space Invaders skyrockets the legendary arcade franchise to new heights with out-of-this-world 3D graphics, explosive special effects, enhanced firepower, high-resolution cinematics, and frenetic multiplayer modes in graphically rich space worlds.Classic Arcade Action: Brave 100 levels of classic shoot-and-dodge-style gameplay now in 3D and updated with a host of innovative features!Visit a variety of space worlds, including Pluto, Saturn, Mars, and Earth-each with dynamic terrain and interactive background elements.","descriptionSource":"http://www.gamefaqs.com/n64/198723-space-invaders","developer":"Z-Axis, Ltd.","coverName":"Space Invaders (USA).n64","players":"2","publisher":"Activision","esrb":"E - Everyone","rating":{"score":3.56,"count":63}},{"id":"spacestation-silicon-valley","title":"SpaceStation Silicon Valley","year":1998,"genres":["Platformer"],"description":"Silicon Valley was intended to be the most technologically advanced amusement park civilization has ever known. Shortly after take-off, it disappeared. Now, in the year 3000, it's back and on a collision course with Earth! It's up to you to conquer the 30 levels in four incredibly lavish environments, take control of the totally original, wacky and - at times - life threatening characters and unlock the mysteries of the Valley. It's all great fun but remember, the fate of the world is in your hands!","descriptionSource":"http://www.gamefaqs.com/n64/198727-space-station-silicon-valley","developer":"DMA Design","coverName":"SpaceStation Silicon Valley (USA).n64","players":"1","publisher":"Take-Two Interactive Software","esrb":"E - Everyone","rating":{"score":3.74,"count":108}},{"id":"spider-man","title":"Spider-Man","year":2000,"genres":["Action"],"description":"He spins a web, swings across the sky and lands with a somersault onto the Daily Bugle building. Who is this masked hero? It's you! Fight, jump and web-sling as Spider-Man as you take on a legion of sinister villains. The city is depending on you.","descriptionSource":"http://www.gamefaqs.com/n64/366269-spider-man","developer":"Edge of Reality","coverName":"Spider-Man (USA).n64","players":"1","publisher":"Activision","esrb":"E - Everyone","rating":{"score":3.83,"count":119}},{"id":"star-fox-64","title":"Star Fox 64","year":1997,"genres":["Shooter"],"description":"The Lylat system has been invaded! Join Fox McCloud and his Star Fox team as they fight to save the galaxy from the clutches of the evil Andross. Travel to many different 3-D worlds. Battle the enemy in the air and on the ground and listen in as Fox McCloud interacts with a cast of characters.","descriptionSource":"http://www.gamefaqs.com/n64/198759-star-fox-64","developer":"Nintendo","coverName":"Star Fox 64 (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.42,"count":543}},{"id":"star-soldier-vanishing-earth","title":"Star Soldier: Vanishing Earth","year":1998,"genres":["Shooter"],"description":"In the year 2098 mankind had been critically attacked by a military force from Zeograd, a hostile planet in a far off galaxy. Commander Parker Deehan of Special Interception Airforce (SIA) decided to deploy and pilot the F98 Star Soldier fighter craft into the front line of battle against Zeograd. Losing the battle meant the extinction of mankind and the total annihilation of Earth!","descriptionSource":"http://www.gamefaqs.com/n64/562857-star-soldier-vanishing-earth","developer":"Hudson Soft","coverName":"Star Soldier - Vanishing Earth (USA).n64","players":"1","publisher":"Electro Brain","esrb":"E - Everyone","rating":{"score":3.66,"count":79}},{"id":"star-wars-episode-i-battle-for-naboo","title":"Star Wars Episode I: Battle for Naboo","year":2000,"genres":["Action"],"description":"Attention defenders of Naboo! The Trade Federation must be stopped! Storm through more than 15 missions over land, sea and space as your freedom fighters rally against the droid armies. Take control of 7 vehicles: the Naboo starfighter, Gian speeder, and new craft like the heavy STAP, Trade Federation gunboat and more. More than 15 missions: escape from Theed, search & destroy, sabotage, reconnaissance, convoy. Battle against Trade Federation droid starfighters, AATs, destroyer droids, battle droids. Change vehicles mid-mission through specially designated hangars.","descriptionSource":"http://www.gamefaqs.com/n64/914230-star-wars-episode-i-battle-for-naboo","developer":"Factor 5","coverName":"Star Wars Episode I - Battle for Naboo (USA).n64","players":"1","publisher":"LucasArts Entertainment","esrb":"T - Teen","rating":{"score":3.73,"count":91}},{"id":"star-wars-episode-i-racer","title":"Star Wars Episode I: Racer","year":1999,"genres":["Racing"],"description":"Join Jedi-to-be Anakin Skywalker in the Star Wars race of your life! Relive all the thrills and excitement of the Podracer sequence from Star Wars: Episode I. Hang on tight - with afterburners on, Podracers max out at a simulated 600 mph! Race in furious competition against more than 21 opponents! Take on over 21 tracks in 8 unique worlds. Avoid hazards such as methane lakes, meteor showers and Tusken Raiders! Featuring spectacular 3D environments!","descriptionSource":"http://www.gamefaqs.com/n64/198780-star-wars-episode-i-racer","developer":"LucasArts","coverName":"Star Wars Episode I - Racer (USA).n64","players":"2","publisher":"LucasArts Entertainment","esrb":"E - Everyone","rating":{"score":4.16,"count":219}},{"id":"star-wars-rogue-squadron","title":"Star Wars: Rogue Squadron","year":1998,"genres":["Shooter"],"description":"Fly against the evil Empire! As Luke Skywalker, co-founder of the Rebel Alliance's elite Rogue Squadron, you must combat the evil Galactic Empire! Engage in intense, fast-paced planetary air-to-ground and air-to-air missions - dogfights, search and destroy, reconnaissance, bombing runs, rescue assignments and more! Pilot X-wings, Y-wings, A-wings, V-wings and Snowspeeders with powerful weapons in over 15 missions battling TIE fighters, TIE bombers, Imperial shuttles, AT-AT walkers, AT-STs and other challenging foes.","descriptionSource":"http://www.gamefaqs.com/n64/198787-star-wars-rogue-squadron","developer":"Factor 5","coverName":"Star Wars - Rogue Squadron (USA).n64","players":"1","publisher":"Nintendo","esrb":"T - Teen","rating":{"score":4.21,"count":224}},{"id":"star-wars-shadows-of-the-empire","title":"Star Wars: Shadows of the Empire","year":1996,"genres":["Shooter"],"description":"A long time ago in a galaxy far, far away... As Luke Skywalker and the Rebel Alliance struggle to defeat Darth Vader and the Empire, a new threat arises. Dark Prince Xizor, head of the Black Sun crime syndicate, aspires to take Darth Vader's place at the Emperor's side. To do that, he must eliminate young Skywalker. As Dash Rendar, it's up to you to protect Luke and help the Alliance defeat the evil Xizor. Watch out for infamous bounty hunters and deadly stormtroopers! May the Force be with you!","descriptionSource":"http://www.gamefaqs.com/n64/198789-star-wars-shadows-of-the-empire","developer":"LucasArts","coverName":"Star Wars - Shadows of the Empire (USA).n64","players":"1","publisher":"Nintendo","esrb":"T - Teen","rating":{"score":4.02,"count":247}},{"id":"starcraft-64","title":"StarCraft 64","year":2000,"genres":["Strategy"],"description":"In the distant future, a small group of human exiles have been doomed to fight for their survival on the edge of the universe. Three powerful species, the Terrans, Protoss and Zerg, are locked in a fierce battle over the fate of the galaxy. The time for war has come. Manage resources, build armies, devise strategies and master the specialized technologies of each species as you enter a universe of unparalleled tactical excitement. Over 50 single-player missions, including new scenarios specially created for the N64.","descriptionSource":"http://www.gamefaqs.com/n64/198791-starcraft-64","developer":"Mass Media","coverName":"StarCraft 64 (USA).n64","players":"2","publisher":"Nintendo","esrb":"T - Teen","rating":{"score":3.48,"count":82}},{"id":"starshot-space-circus-fever","title":"Starshot: Space Circus Fever","year":1999,"genres":["Action","Platformer"],"description":"Take a ride through the cosmos with Starshot, the star juggler of the Space Circus. Your courage and skill will be challenged as you battle to overcome Wolfgang von Ravel, the evil boss of your crooked competitor - the Virtua Circus. Only you can save the Space Circus from extinction! Total freedom of movement in a world of rich 3D graphics! Starshot can walk, run, talk, jump, swim and fly, while shooting stars that he can control! Featuring more than 300 'cosmical' characters from a variety of planets!","descriptionSource":"http://www.gamefaqs.com/n64/198799-starshot-space-circus-fever","developer":"Infogrames","coverName":"Starshot - Space Circus Fever (USA) (En,Fr,Es).n64","players":"1","publisher":"Infogrames","esrb":"E - Everyone","rating":{"score":3.14,"count":38}},{"id":"stunt-racer-64","title":"Stunt Racer 64","year":2000,"genres":["Racing"],"description":"The future of racing is here! Stunt Racer 64 combines the cutthroat world of auto racing with incredible stunts to reach new heights in excitement! Jostle for position through roller coaster tracks worthy of a theme park. Stunt Racer 64 is more than just racing - it's a daredevil thrill ride! Featuring 11 daredevil tracks to conquer, including half pipes and stunt tracks, and 29 stylish retro vehicles with futuristic power upgrades. Accumulate cash by winning races and pulling off dangerous stunts to add vehicles to your collection with the prize money!","descriptionSource":"http://www.gamefaqs.com/n64/579310-stunt-racer-64","developer":"Boss Game Studios","coverName":"Stunt Racer 64 (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.42,"count":59}},{"id":"super-bowling","title":"Super Bowling","year":2001,"genres":["Sports"],"description":"Introducing a brand new lane system with SUPER BOWLING! Features include dynamic pin action, four great game modes, eight unique characters to choose from, power and spin throwing system, a variety of lanes and accessories, and 1 - 4 player action!","descriptionSource":"http://www.gamefaqs.com/n64/576678-super-bowling","developer":"Athena","coverName":"Super Bowling (USA).n64","players":"4","publisher":"UFO Interactive Games","esrb":"E - Everyone","rating":{"score":3.34,"count":44}},{"id":"super-mario-64","title":"Super Mario 64","year":1996,"genres":["Action","Platformer"],"description":"Mario is super in a whole new way! Combining the finest 3-D graphics ever developed for a video game and an explosive sound track, Super Mario 64 becomes a new standard for video games. It's packed with bruising battles, daunting obstacle courses and underwater adventures. Retrieve the Power Stars from their hidden locations and confront your arch nemesis - Bowser, King of the Koopas!","descriptionSource":"http://www.gamefaqs.com/n64/198848-super-mario-64","developer":"Nintendo","coverName":"Super Mario 64 (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.71,"count":1671}},{"id":"super-smash-bros","title":"Super Smash Bros.","year":1999,"genres":["Fighting"],"description":"It's a Bumpin', Bruisin', Brawlin' Bash! The many worlds of Nintendo collide in the ultimate showdown of strength and skill! Up to four players can choose their favorite characters - complete with signature attacks - and go at it in Team Battles and Free-For-Alls. Or venture out on your own to conquer the 14 stages in single-player mode. Either way, Super Smash Bros. is a no-holds-barred action-fest that will keep you coming back for more!","descriptionSource":"http://www.gamefaqs.com/n64/198854-super-smash-bros","developer":"HAL Labs","coverName":"Super Smash Bros. (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.42,"count":668}},{"id":"supercross-2000","title":"Supercross 2000","year":1999,"genres":["Racing"],"description":"Ride, Race, and Fly with Style! Choose from 24 top Supercross and Freestyle riders. Awesome handlebar-to-handlebar racing! 16 real stadium tracks develop grooves and ruts as the race develops. Realistic motorcycle handling in Pro mode or easier control in Beginner mode. Multiple game modes: Quick Race, Single Race, Season and Freestyle Jump-Off! Two-player split-screen gameplay and spectacular hi-res graphics!","descriptionSource":"http://www.gamefaqs.com/n64/198859-supercross-2000","developer":"MBL Research","coverName":"Supercross 2000 (USA).n64","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.33,"count":59}},{"id":"superman","title":"Superman","year":1999,"genres":["Action","Adventure"],"description":"Lois Lane and Jimmy Olsen have disappeared - they've been kidnapped by the malevolent powers of Lex Luthor and Braniac, who have brought them into a virtual reality version of Metropolis. Superman must come to the rescue! The Man of Steel must work through this virtual dimension and find a way to conquer the evil masterminds that created it. Experience the incredible powers of Superman first-hand as you battle to rescue Lois Lane from the clutches of Metallo, then attempt to free Jimmy Olsen from the steel grip of Darkseid. Race into outer space to face Braniac's evil alien technology. Above all else, destroy Luthor's deadly dream of a virtual reality Metropolis!","descriptionSource":"http://www.gamefaqs.com/n64/198862-superman","developer":"Titus Software","coverName":"Superman (Europe) (En,Fr,De,Es,It,Nl).n64","players":"4","publisher":"Titus Software","esrb":"E - Everyone","rating":{"score":1.39,"count":153}},{"id":"superman-the-new-superman-adventures","title":"Superman: The New Superman Adventures","year":1999,"genres":["Action","Adventure"],"description":"Lois Lane and Jimmy Olsen have disappeared - they've been kidnapped by the malevolent powers of Lex Luthor and Braniac, who have brought them into a virtual reality version of Metropolis. Superman must come to the rescue! The Man of Steel must work through this virtual dimension and find a way to conquer the evil masterminds that created it. Experience the incredible powers of Superman first-hand as you battle to rescue Lois Lane from the clutches of Metallo, then attempt to free Jimmy Olsen from the steel grip of Darkseid. Race into outer space to face Braniac's evil alien technology. Above all else, destroy Luthor's deadly dream of a virtual reality Metropolis!","descriptionSource":"http://www.gamefaqs.com/n64/198862-superman","developer":"Titus Software","coverName":"Superman - The New Superman Aventures (USA) (En,Fr,Es).n64","players":"4","publisher":"Titus Software","esrb":"E - Everyone","rating":{"score":1.39,"count":153}},{"id":"tarzan","title":"Tarzan","year":2000,"genres":["Action","Platformer"],"description":"Overcome the jungle's most dangerous perils in this action-packed adventure.Based on the animated film, Tarzan allows you to relive Tarzan's journey through life from a headstrong youth to a courageous adult.Your innate jungle abilities will allow you to swing, climb, run, jump, and surf through 13 beautiful environments, while interacting with unique characters, riding elephants, and solving challenging puzzles.It's now up to you to master the moves of this unique jungle hero and save Tarzan's family from a ruthless hunter.","descriptionSource":"http://www.gamefaqs.com/n64/198890-disneys-tarzan","developer":"Eurocom Entertainment Software","coverName":"Tarzan (USA).n64","players":"1","publisher":"Activision","esrb":"E - Everyone","rating":{"score":3.74,"count":95}},{"id":"taz-express","title":"Taz Express","year":2000,"genres":["Platformer"],"description":"Taz - a delivery boy? Would you trust THIS guy to deliver your fragile package?Tired of seeing Taz do nothing but hang around the house and watch TV, She-Devil decides Taz needs to find a job. She finds the perfect one for him - as a delivery boy for the next courier service, 'Taz Express'. Your job: Help Taz protect the package long enough to deliver it.","descriptionSource":"http://www.gamefaqs.com/n64/570144-looney-tunes-taz-express","developer":"Zed Two Limited","coverName":"Taz Express (Europe) (En,Fr,De,Es,It,Nl).n64","players":"1","publisher":"Infogrames","esrb":"Not Rated","rating":{"score":3.54,"count":49}},{"id":"tetrisphere","title":"Tetrisphere","year":1997,"genres":["Puzzle"],"description":"What would you do if your friends were trapped at the core of a sphere layered in hundreds of Tetris pieces? You'd have a BLAST! Tetrisphere is a whole new way to play Tetris, the world's most popular home video puzzle game. Explore over 300 levels of unique 3D gameplay charged with high voltage action. Choose to take control of Wheels, Jak, Rocket, Gear, Turbine or Stomp to experience 3D puzzle excitement like never before!","descriptionSource":"http://www.gamefaqs.com/n64/198946-tetrisphere","developer":"H2O Interactive","coverName":"Tetrisphere (USA).n64","players":"2","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.39,"count":82}},{"id":"tg-rally-2","title":"TG Rally 2","year":1999,"genres":["Racing"],"description":"The second rally racer from Kemco on the N64 provides a vastly different style of rally racing to the original Top Gear Rally.\n\nAlong with the new option to join a rally racing team, who supports you through-out each championship cup you take part in. Money raised by each victory or top place in the cups goes towards improving your car, or repairing any problems. If you take a wrong turn and damage a part of your car (which can be anything from tires to a full engine), the repairs come out of your pocket. New sponsorship deals and bigger team call ups will also come into play the better you race, allowing the chance to drive the more powerful rally cars and play for big money.\n\nYou can also take part in the usual arcade rally style against 4 other cars, with the first to get to the finish taking the points. 2 players can play as part of one team during a championship campaign, as well up to four players split screen in the arcade mode.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/1222","developer":"Saffire","coverName":"TG Rally 2 (Europe).n64","players":"4","publisher":"Kotobuki System","esrb":"E - Everyone","rating":{"score":3.67,"count":55}},{"id":"the-legend-of-zelda-majora-s-mask","title":"The Legend of Zelda: Majora's Mask","year":2000,"genres":["Action","Adventure"],"description":"Thrown into a parallel world by the mischievous actions of a possessed Skull Kid, Link finds a land in grave danger. The dark power of a relic called Majora's Mask has wreaked havoc on the citizens of Termina, but their most urgent problem is a suicidal moon crashing toward the world. Link has only 72 hours to find a way to stop its descent.","descriptionSource":"http://www.gamefaqs.com/n64/197770-the-legend-of-zelda-majoras-mask","developer":"Nintendo","coverName":"Legend of Zelda, The - Majora's Mask (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.62,"count":749}},{"id":"the-legend-of-zelda-ocarina-of-time","title":"The Legend of Zelda: Ocarina of Time","year":1998,"genres":["Action","Adventure"],"description":"As a young boy, Link is tricked by Ganondorf, the King of the Gerudo Thieves. The evil human uses Link to gain access to the Sacred Realm, where he places his tainted hands on Triforce and transforms the beautiful Hyrulean landscape into a barren wasteland. Link is determined to fix the problems he helped to create, so with the help of Rauru he travels through time gathering the powers of the Seven Sages.","descriptionSource":"http://www.gamefaqs.com/n64/197771-the-legend-of-zelda-ocarina-of-time","developer":"Nintendo","coverName":"Legend of Zelda, The - Ocarina of Time (USA).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.75,"count":1306}},{"id":"the-legend-of-zelda-ocarina-of-time-master-quest","title":"The Legend of Zelda: Ocarina of Time: Master Quest","year":2002,"genres":["Action","Adventure","RPG"],"description":"The Legend of Zelda: Ocarina of Time Master Quest is a reworked version of the original Ocarina of Time for the Nintendo 64. Master Quest contains largely the same content as the original Ocarina of Time, but with redesigned, more difficult dungeons akin to a Second Quest. This game is an unofficial port from the original GameCube version.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/129915","developer":"Nintendo EAD","coverName":"Legend of Zelda, The - Ocarina of Time - Master Quest (USA) (Debug Edition).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.51,"count":170}},{"id":"the-new-tetris","title":"The New Tetris","year":1999,"genres":["Puzzle"],"description":"With special new moves, additional ways to score, and room for up to 4 players simultaneously, this already habit-forming classic will have you absolutely addicted! Perform a Spin Move to place that hard-to-fit piece. Can't use the shape you're given? Use the Hold Piece instead. Form Multi- and Mono-Squares, then clear them to make you score soar! You can even dump Garbage on your friends as you compete in multi-player mode.","descriptionSource":"http://www.gamefaqs.com/n64/198976-the-new-tetris","developer":"H2O Interactive","coverName":"New Tetris, The (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.83,"count":117}},{"id":"the-powerpuff-girls-chemical-x-traction","title":"The Powerpuff Girls: Chemical X-Traction","year":2001,"genres":["Fighting"],"description":"Your turn to fight: Powerpuff Girls style! Terror in Townsville, destruction and disaster! Mojo Jojo has stolen a pie full of Chemical X from the Powerpuff Girls and given a taste to every villain in town. It's up to you to take control and fight each of the Townsville villains and win back all the Chemical X before it's too late! Battle the villains in exciting arenas including Mojo Jojo's volcano lair, Townsville city dump and Fuzzy's country shack. Activate laser eyes and knock your opponent flat! Play as one of the Powerpuff Girls, OR your favorite villain!","descriptionSource":"http://www.gamefaqs.com/n64/532474-the-powerpuff-girls-chemical-x-traction","developer":"VIS Entertainment","coverName":"Powerpuff Girls, The - Chemical X-Traction (USA).n64","players":"2","publisher":"BAM! Entertainment","esrb":"E - Everyone","rating":{"score":3.2,"count":54}},{"id":"tigger-s-honey-hunt","title":"Tigger's Honey Hunt","year":2000,"genres":["Platformer"],"description":"Winnie the Pooh needs YOU! How can he throw a party without honey? Play as Tigger and run, jump, and bounce around the 100 Acre Wood in search of Pooh's 'most favorite' snack. Along the journey there'll be plenty of challenges - blustery blowing leaves to ride, icy terrain, falling boulders, menacing bees, pesky bats and more. Earn Tigger's very special 'Tiggertastic Bounce' as a bonus!","descriptionSource":"http://www.gamefaqs.com/n64/576969-tiggers-honey-hunt","developer":"Rivage Games","coverName":"Tigger's Honey Hunt (USA).n64","players":"2","publisher":"NewKidCo","esrb":"E - Everyone","rating":{"score":3.46,"count":59}},{"id":"tom-and-jerry-in-fists-of-furry","title":"Tom and Jerry in Fists of Furry","year":2000,"genres":["Fighting"],"description":"One-on-one fighting! Tag team tournaments! Just choose your character and then select the location. All the environments are modeled after scenes from your favorite Tom & Jerry episodes. An 'All-Star' line-up of characters such as Tom, Jerry, Butch, Spike, Tuffy, and Duckling help to make this the ultimate Tom & Jerry experience! Weapons include shovels, bombs, red-hot pokers, tennis rackets, furniture and an assortment of fruit, plus there are countless other tricks, traps and surprises to be found. It doesn't get any better than this. So go to your corner, wait for the bell and come out fighting. Just keep an eye out behind you, because no one fights fair in this game!","descriptionSource":"http://www.gamefaqs.com/n64/437520-tom-and-jerry-in-fists-of-furry","developer":"VIS Entertainment","coverName":"Tom and Jerry in Fists of Furry (USA).n64","players":"2","publisher":"NewKidCo","esrb":"E - Everyone","rating":{"score":3.47,"count":63}},{"id":"tom-clancy-s-rainbow-six","title":"Tom Clancy's Rainbow Six","year":1999,"genres":["Shooter","Strategy"],"description":"Rainbow Six is as close as it gets to the intensity of real-life tactical operations. You'll join an elite multi-national strike force hired by the world's governments to stop a group of deadly terrorists. Draw your team from a pool of specialists. Select authentic gear and weapons and infiltrate seized buildings to rescue hostages. Rainbow Six's explosive real-world action is coupled with spine-tingling tactics to create a gaming experience you won't soon forget.","descriptionSource":"http://www.gamefaqs.com/n64/198400-tom-clancys-rainbow-six","developer":"Saffire","coverName":"Tom Clancy's Rainbow Six (USA).n64","players":"2","publisher":"Red Storm Entertainment","esrb":"T - Teen","rating":{"score":3.47,"count":71}},{"id":"tonic-trouble","title":"Tonic Trouble","year":1999,"genres":["Platformer"],"description":"Trouble up to your bow tie! Ed's toxic goo turned the world crazy - tomatoes are rioting, carrots are biting back, and Grogh the Hellish wants Ed's head! Help Ed right the wrongs in 12 wildly animated worlds -insane puzzles, killer vegetables, dangerous dungeons, and more. All caused by Ed. It's the biggest trouble anyone has ever gotten into, or out of! A strange brew of action adventure and mind-bending puzzles!","descriptionSource":"http://www.gamefaqs.com/n64/199055-tonic-trouble","developer":"Ubisoft Montpellier","coverName":"Tonic Trouble (USA) (Rev A).n64","players":"1","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":3.26,"count":80}},{"id":"tony-hawk-s-pro-skater","title":"Tony Hawk's Pro Skater","year":2000,"genres":["Sports"],"description":"Go Big, Go Pro! Skate as legendary Tony Hawk, or as one of nine top pros. Work your way up the ranks by landing suicidal tricks in brutal competitions to become the highest ranked skate champ! Great features such as: Signature Pro Moves, fully skateable worlds, head-to-head competition, and Instant Replay Mode.","descriptionSource":"http://www.gamefaqs.com/n64/199059-tony-hawks-pro-skater","developer":"Edge of Reality","coverName":"Tony Hawk's Pro Skater (USA).n64","players":"2","publisher":"Activision","esrb":"E - Everyone","rating":{"score":3.87,"count":101}},{"id":"tony-hawk-s-pro-skater-2","title":"Tony Hawk's Pro Skater 2","year":2001,"genres":["Sports"],"description":"Tony Hawk's Pro Skater 2 redefined an already great game. Its addition of stellar new features (like Create-A-Park), and great game-play tweaks (the manual maneuver will be copied for years to come) made it the best installment in a killer series of games. Anyone who has ever skated the Philadelphia level will agree -- this game is a masterpiece of level design. Hell, it's a masterpiece all around. There isn't a bad park or dull moment, just pure gaming nirvana!","descriptionSource":"http://www.gamefaqs.com/n64/470189-tony-hawks-pro-skater-2","developer":"Edge of Reality","coverName":"Tony Hawk's Pro Skater 2 (USA).n64","players":"2","publisher":"Activision","esrb":"E - Everyone","rating":{"score":3.92,"count":96}},{"id":"tony-hawk-s-pro-skater-3","title":"Tony Hawk's Pro Skater 3","year":2002,"genres":["Sports"],"description":"You may not be able to live like the legend, but now you can skate like him.Skate as the legendary Tony Hawk or choose from a dream team of 12 top pro skaters, including old favorites like Lasek, Thomas, Muska, and Steamer, as well as new talent like Gilfberg, Caballero, Koston, and Mullen.Or enjoy full customization abilities with the enhanced Create-a-Skater (now including female skaters) and the Skatepark Editor.Travel from L.A. to Tokyo, Suburbia to Skater's Island performing challenges and meeting goals.New moves include the Revert, which allows you to link vert tricks, and flatland tricks such as Caspers, the Primo, and Handstand Manual.If you're good, you can even unlock hidden pro footage.","descriptionSource":"http://www.gamefaqs.com/n64/914527-tony-hawks-pro-skater-3","developer":"Edge of Reality","coverName":"Tony Hawk's Pro Skater 3 (USA).n64","players":"2","publisher":"Activision","esrb":"E - Everyone","rating":{"score":3.64,"count":87}},{"id":"tony-hawk-s-skateboarding","title":"Tony Hawk's Skateboarding","year":2000,"genres":["Sports"],"description":"Go Big, Go Pro! Skate as legendary Tony Hawk, or as one of nine top pros. Work your way up the ranks by landing suicidal tricks in brutal competitions to become the highest ranked skate champ! Great features such as: Signature Pro Moves, fully skateable worlds, head-to-head competition, and Instant Replay Mode.","descriptionSource":"http://www.gamefaqs.com/n64/199059-tony-hawks-pro-skater","developer":"Edge of Reality","coverName":"Tony Hawk's Skateboarding (Europe).n64","players":"2","publisher":"Activision","esrb":"E - Everyone","rating":{"score":3.87,"count":101}},{"id":"top-gear-hyper-bike","title":"Top Gear Hyper-Bike","year":2000,"genres":["Racing"],"description":"Big air. Fast tracks. Snarling competitors. Whether you're into high-flying motocross racing or knee-scraping street bike action, Top Gear Hyper Bike opens the throttle on gritty, two-wheeled fun. Strap on your brain bucket and test these features: Four incredible modes of play, Track Editor to create your own mind-blowing tracks, race on the street and in the dirt using 16 authentic race bikes from Kawasaki, Yamaha and Honda, unlock hidden bikes and bonus courses by winning race seasons in Championship Mode.","descriptionSource":"http://www.gamefaqs.com/n64/199066-top-gear-hyper-bike","developer":"Snowblind Studios","coverName":"Top Gear Hyper-Bike (USA).n64","players":"2","publisher":"Kemco","esrb":"E - Everyone","rating":{"score":3.4,"count":48}},{"id":"top-gear-overdrive","title":"Top Gear Overdrive","year":1998,"genres":["Racing"],"description":"Smile, you beast. It's the world's fastest multi-player N64 racing, geared for people who love to cheat! Oh yeah. This baby's got it all! Ten wild cars. Five white-knuckle tracks. A beautifully giddy selection of wicked hair-pin turns, roller coaster hills and secret, shifty shortcuts. Plus: 6 fullvocal BGM tunes. Challenging Mirror Racing Mode. The world's worst weather conditions. And: IT'S OKAY TO CHEAT! Once you get ahead you stay ahead by forcing the competition into interactive objects like traffic cones and road signs. Waaay cool. The one and only Top Gear Overdrive. Don't get mad. Get evil!","descriptionSource":"http://www.gamefaqs.com/n64/199067-top-gear-overdrive","developer":"Snowblind Studios","coverName":"Top Gear Overdrive (USA).n64","players":"4","publisher":"Vatical Entertainment","esrb":"E - Everyone","rating":{"score":3.86,"count":69}},{"id":"top-gear-rally","title":"Top Gear Rally","year":1997,"genres":["Racing"],"description":"Jump in, buckle up and drive yourself insane! Top Gear Rally will have your engines revving! No options on this baby - it comes fully equipped: 9 polygon cars, 5 intense tracks (Desert, Jungle, Mountain, coastline and Strip Mine), 4 high-performance game modes and multiple camera views!","descriptionSource":"http://www.gamefaqs.com/n64/199069-top-gear-rally","developer":"Boss Game Studios","coverName":"Top Gear Rally (USA).n64","players":"2","publisher":"Kotobuki System","esrb":"E - Everyone","rating":{"score":3.41,"count":74}},{"id":"top-gear-rally-2","title":"Top Gear Rally 2","year":1999,"genres":["Racing"],"description":"If you're ready to step up to a realistic racing game, Top Gear Rally 2 is the one to beat. This is the first and only game on the N64 to feature point-to-point rally courses and authentic rally racers from Toyota, Subaru and Mitsubishi. If you survive the rigors of ARSG Rally School, you'll earn racing certification for races around the world, on courses through every imaginable environmental condition. This isn't just simply the most realistic rally game on the planet - it's also the best!","descriptionSource":"http://www.gamefaqs.com/n64/199070-top-gear-rally-2","developer":"Saffire","coverName":"Top Gear Rally 2 (USA).n64","players":"4","publisher":"Kotobuki System","esrb":"E - Everyone","rating":{"score":3.67,"count":55}},{"id":"toy-story-2-buzz-lightyear-to-the-rescue","title":"Toy Story 2: Buzz Lightyear to the Rescue!","year":1999,"genres":["Platformer"],"description":"The Countdown to Adventure is On! As space hero Buzz Lightyear, you've got your hands full. Your best buddy, Woody, has been kidnapped by a greedy toy collector and it's going to be an all-out race against time to save him. It's all up to you... Buzz Lightyear to the rescue! Spin, spring, somersault and bounce through 15 colorful, action-packed levels. Unlock special toy accessories to complete your missions, like cool rocket jet boots! Enjoy fast and fun 3D gameplay with your favorite characters from the movie!","descriptionSource":"http://www.gamefaqs.com/n64/199097-disney-pixar-toy-story-2-buzz-lightyear-to-the","developer":"Traveller's Tales","coverName":"Toy Story 2 - Buzz Lightyear to the Rescue! (USA).n64","players":"1","publisher":"Activision","esrb":"E - Everyone","rating":{"score":3.69,"count":107}},{"id":"transformers-beast-wars-transmetals","title":"Transformers: Beast Wars Transmetals","year":2000,"genres":["Fighting"],"description":"Now, experience a Transformers battle you've never seen before! Take command of the Heroic Maximals and Evil Predicons as they struggle for supremacy! More powerful than ever, these cybertronian warriors can convert into 3 modes: beast, vehicle, and robot. Run, blast and transform your way to victory! Crush the competition with the awesome Ultra Blast attack!","descriptionSource":"http://www.gamefaqs.com/n64/576667-transformers-beast-wars-transmetals","developer":"Locomotive Corporation","coverName":"Transformers - Beast Wars Transmetals (USA).n64","players":"2","publisher":"BAM! Entertainment","esrb":"T - Teen","rating":{"score":2.51,"count":41}},{"id":"triple-play-2000","title":"Triple Play 2000","year":1999,"genres":["Sports"],"description":"This is POWER Baseball! Great game features such as: Full control hitting - more power, more contact! One-button baserunning! Fast-paced gameplay! Home Run Challenge! Multiple fielding cameras! Real-time lighting! Detailed facial animations!","descriptionSource":"http://www.gamefaqs.com/n64/199111-triple-play-2000","developer":"Treyarch","coverName":"Triple Play 2000 (USA).n64","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":2.49,"count":37}},{"id":"turok-2-seeds-of-evil","title":"Turok 2: Seeds of Evil","year":1998,"genres":["Shooter"],"description":"Only evil this dark could bring him back. Only a game this big can do him justice. Turok 2: Seeds of Evil! Pick off distant enemies with deadly sniper weapons, and enjoy ferocious multi-player deathmatches!","descriptionSource":"http://www.gamefaqs.com/n64/199127-turok-2-seeds-of-evil","developer":"Iguana Entertainment","coverName":"Turok 2 - Seeds of Evil (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.91,"count":165}},{"id":"turok-3-shadow-of-oblivion","title":"Turok 3: Shadow of Oblivion","year":2000,"genres":["Shooter"],"description":"Older than time itself, a savage cosmic entity called Oblivion exists only to devour everything in its path. Two new Turok warriors, Danielle and Joseph Fireseed must face this evil. The heritage of Turok and all humankind depends on them. Join the legacy. Over 24 upgradable weapons to battle 40 new and original enemies! Intense multiplayer action - over 8 modes and 48 maps!","descriptionSource":"http://www.gamefaqs.com/n64/199128-turok-3-shadow-of-oblivion","developer":"Acclaim Studios Austin","coverName":"Turok 3 - Shadow of Oblivion (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.62,"count":115}},{"id":"turok-dinosaur-hunter","title":"Turok: Dinosaur Hunter","year":1997,"genres":["Shooter"],"description":"The mantle has been passed. You've become Protector of the Earth. You are now Turok Dinosaur Hunter.","descriptionSource":"http://www.gamefaqs.com/n64/199130-turok-dinosaur-hunter","developer":"Iguana Entertainment","coverName":"Turok - Dinosaur Hunter (USA).n64","players":"1","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.9,"count":199}},{"id":"turok-rage-wars","title":"Turok: Rage Wars","year":1999,"genres":["Shooter"],"description":"Since time began, Turok has maintained the balance between good and evil with the Light Burden. A vessel that holds the power of creation. Now, fierce wars are fought for control. You must prove yourself worthy to wield the Light Burden. You must relive the challenge of your ancestors and survive the RAGE WARS! Featuring brutal heart-pounding deathmatches, lethal weapons with unimaginable power, and 8 savage game modes, including co-op mission-based gameplay, Team Bloodlust, Frag Tag and more!","descriptionSource":"http://www.gamefaqs.com/n64/199132-turok-rage-wars","developer":"Acclaim Studios Austin","coverName":"Turok - Rage Wars (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"M - Mature","rating":{"score":3.63,"count":86}},{"id":"twisted-edge-snowboarding","title":"Twisted Edge Snowboarding","year":1998,"genres":["Sports"],"description":"This is it! The fast-paced, intense snowboarding action you've been waiting for! TWISTED EDGE: EXTREME SNOWBOARDING! The sickest tricks, the biggest air and runs you've only dreamt about 'til now. No more searching for the best ride ever, grab your controller and prepare to get twisted! Loaded with riders, boards, and secrets - each with their own unique qualities. There's lots available, but only if you aren't slackin' off in your ridin' skills! Performance is everything and it pays off in TWISTED EDGE!","descriptionSource":"http://www.gamefaqs.com/n64/199134-twisted-edge-extreme-snowboarding","developer":"Boss Game Studios","coverName":"Twisted Edge - Extreme Snowboarding (Europe).n64","players":"2","publisher":"Kotobuki System","esrb":"E - Everyone","rating":{"score":2.84,"count":46}},{"id":"twisted-edge-extreme-snowboarding","title":"Twisted Edge: Extreme Snowboarding","year":1998,"genres":["Sports"],"description":"This is it! The fast-paced, intense snowboarding action you've been waiting for! TWISTED EDGE: EXTREME SNOWBOARDING! The sickest tricks, the biggest air and runs you've only dreamt about 'til now. No more searching for the best ride ever, grab your controller and prepare to get twisted! Loaded with riders, boards, and secrets - each with their own unique qualities. There's lots available, but only if you aren't slackin' off in your ridin' skills! Performance is everything and it pays off in TWISTED EDGE!","descriptionSource":"http://www.gamefaqs.com/n64/199134-twisted-edge-extreme-snowboarding","developer":"Boss Game Studios","coverName":"Twisted Edge - Extreme Snowboarding (USA).n64","players":"2","publisher":"Kotobuki System","esrb":"E - Everyone","rating":{"score":2.84,"count":46}},{"id":"v-rally-edition-99","title":"V-Rally Edition 99","year":1999,"genres":["Racing"],"description":"Racing insanity! Over 40 original tracks, 11 official World Rally Championship cars, tracks in 8 worldwide locations, realistic race physics and smooth car handling, diverse terrain such as jungles, canyons, deserts, mountains and more, unstable weather patterns like rain, fog, snow and cloudy. Adjust car performance characteristics to suit varied road conditions. Bonus and hidden cars and tracks to unlock!","descriptionSource":"http://www.gamefaqs.com/n64/199239-v-rally-edition-99","developer":"Eden Studios","coverName":"V-Rally Edition 99 (USA).n64","players":"2","publisher":"Infogrames","esrb":"E - Everyone","rating":{"score":3.14,"count":63}},{"id":"vigilante-8","title":"Vigilante 8","year":1998,"genres":["Racing","Shooter","Simulation"],"description":"Take the wheel as fully-loaded auto combat revs into high gear for the first time on the Nintendo 64. It's a down and dirty, gear-grinding, metal-piercing war on wheels. So get in. Sit down. Blow stuff up! Drive all 8 screamin' V-8's, plus 5 bonus cars! Fight in 8 fully destructible arenas! Go at it in 2 to 4 player battles with co-op and 'smear' options.","descriptionSource":"http://www.gamefaqs.com/n64/199192-vigilante-8","developer":"Luxoflux, Inc.","coverName":"Vigilante 8 (USA).n64","players":"4","publisher":"Activision","esrb":"T - Teen","rating":{"score":3.8,"count":101}},{"id":"vigilante-8-2nd-offense","title":"Vigilante 8: 2nd Offense","year":2000,"genres":["Racing","Shooter","Simulation"],"description":"The future of auto-combat is here! If it drives by, blow it up! Choose from 18 all-new 70's and futuristic vehicles, and 8 new destructible arenas with hidden power-ups. Earn points to upgrade your vehicle. Blast through insane 1 - 4 player action!","descriptionSource":"http://www.gamefaqs.com/n64/199195-vigilante-8-2nd-offense","developer":"Luxoflux, Inc.","coverName":"Vigilante 8 - 2nd Offense (USA).n64","players":"4","publisher":"Activision","esrb":"T - Teen","rating":{"score":4.07,"count":66}},{"id":"virtual-chess-64","title":"Virtual Chess 64","year":1998,"genres":["Board Game","Strategy"],"description":"Transform your N64 into a powerful chess adversary. The most awesome chess engine adapts to any skill level. Learning is endless fun yet even superb players face the maximum challenge. Brilliant graphics brings this classic game alive. Become the next chess legend!","descriptionSource":"http://www.gamefaqs.com/n64/199208-virtual-chess-64","developer":"Titus Software","coverName":"Virtual Chess 64 (USA) (En,Fr,Es).n64","players":"4","publisher":"Titus France","esrb":"E - Everyone","rating":{"score":2.92,"count":37}},{"id":"virtual-pool-64","title":"Virtual Pool 64","year":1998,"genres":["Sports"],"description":"The ultra-real physics make Virtual Pool 64 as close to real pool as it gets! Choose from 9 types of pool including favorites like 9-Ball, Straight Pool, 8-Ball and One Pocket. Three levels of difficulty: Amateur, Professional and Championship. Master trick shots, learn a new game or challenge hundreds of computer opponents in exciting tournament play.","descriptionSource":"http://www.gamefaqs.com/n64/199219-virtual-pool-64","developer":"Celeris","coverName":"Virtual Pool 64 (USA).n64","players":"2","publisher":"Crave Entertainment","esrb":"E - Everyone","rating":{"score":3.11,"count":52}},{"id":"waialae-country-club-true-golf-classics","title":"Waialae Country Club: True Golf Classics","year":1998,"genres":["Sports"],"description":"Get a grip on golf reality with Waialae Country Club True Golf Classics. This golf simulation is tucked into a beautiful Hawaiian setting, but don't let the scenery fool you. The course is designed with all of the challenging hazards of the real golf course. Enjoy the six game modes and save all your statistics to the Game Pak memory. Create up to ten golfers and fill each golf bag with customized clubs. Don't be stuck in the rough with an average golf game, when you can hit the fairway with the best!","descriptionSource":"http://www.gamefaqs.com/n64/199243-waialae-country-club","developer":"T&E Soft","coverName":"Waialae Country Club - True Golf Classics (USA).n64","players":"4","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":2.41,"count":51}},{"id":"war-gods","title":"War Gods","year":1997,"genres":["Fighting"],"description":"Billions of years ago, a Being from a distant galaxy was transporting a precious cargo of life giving Ore. The turbulent formation of our solar system caused his ship to crash, scattering Ore over the molten surface of Planet Earth. Through the millennia, Ten Humans came into contact with the Ore and were transformed into super-evolved warriors. These are the WarGods.","descriptionSource":"http://www.gamefaqs.com/n64/199248-war-gods","developer":"Eurocom Entertainment Software","coverName":"War Gods (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":2.69,"count":61}},{"id":"wave-race-64","title":"Wave Race 64","year":1996,"genres":["Racing"],"description":"Wave Race 64 is sure to provide some of the most exciting racing you've ever experienced. Feel the pounding and crashing of the waves as you accelerate into straight-aways, whip around the marker buoys and go airborne on the jump ramps. Don't race alone - challenge a friend! Take control in three different modes of play - Championship, Time Trials and Stunt Mode. Nine challenging courses set in exotic locales - race conditions change and the wave action responds to the way both you and your opponents race!","descriptionSource":"http://www.gamefaqs.com/n64/199278-wave-race-64","developer":"Nintendo","coverName":"Wave Race 64 (USA).n64","players":"2","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":4.3,"count":336}},{"id":"wayne-gretzky-s-3d-hockey","title":"Wayne Gretzky's 3D Hockey","year":1996,"genres":["Sports"],"description":"Tear up the ice with 'The Great One', and experience lightning-fast skating, blistering one-timers and hard-hitting body checks! Hammer the puck and rip the net... with the world's best! NHLPA and NHL license means real players, team names, logos, and uniforms. Includes all 26 teams, each with 17 available players in their actual NHL lines. Real-time rendered 3D environment with 7 user-selectable cameras allowing players to view the action from all possible angles. Wayne's hockey strategies, skating moves and logic are incorporated into the AI engine.","descriptionSource":"http://www.gamefaqs.com/n64/199279-wayne-gretzkys-3d-hockey","developer":"Atari Games (Midway)","coverName":"Wayne Gretzky's 3D Hockey (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.72,"count":69}},{"id":"wayne-gretzky-s-3d-hockey-98","title":"Wayne Gretzky's 3D Hockey '98","year":1997,"genres":["Sports"],"description":"Take on 'The Great One' again in this hot sequel to the smash hit voted 'Best Sports Game' of '96! With more great features, such as new hidden teams and improved, hard-hitting AI, Gretzky '98 packs a wallop! Includes all 26 teams, each with 17 available players on their actual NHL teams, and you can make player trades or line manipulations to create a powerhouse team of your own. Play 3-on-3, 4-on-4 or 5-on-5 games on either arcade or regulation size hockey rinks, plus exhibition games, full 82 game seasons or a best-of-seven playoff series with full statistic saving capability.","descriptionSource":"http://www.gamefaqs.com/n64/574500-wayne-gretzkys-3d-hockey-98","developer":"Software Creations","coverName":"Wayne Gretzky's 3D Hockey '98 (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":2.83,"count":44}},{"id":"wcw-backstage-assault","title":"WCW Backstage Assault","year":2000,"genres":["Fighting","Sports"],"description":"No-Holds-Barred Brawling! Over 50 WCW superstars, including the women of the WCW! 14 playable Backstage Areas, including the new Semi-Trailer Area. Destroy your enemy faster with power-ups! New - First Blood Mode and Torch matches! Use your environment as a weapon!","descriptionSource":"http://www.gamefaqs.com/n64/367004-wcw-backstage-assault","developer":"Kodiak Interactive","coverName":"WCW Backstage Assault (USA).n64","players":"2","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":2.43,"count":46}},{"id":"wcw-mayhem","title":"WCW Mayhem","year":1999,"genres":["Fighting","Sports"],"description":"Out Of Hand. Out Of The Ring.*Create a wrestler*Over 50 WCW Superstars*Six match types*All TV and PPV Venues*Real Ring Entrances*12 Backstage areas.","descriptionSource":"http://www.gamefaqs.com/n64/199281-wcw-mayhem","developer":"Kodiak Interactive","coverName":"WCW Mayhem (USA).n64","players":"4","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":3.53,"count":56}},{"id":"wcw-nitro","title":"WCW Nitro","year":1999,"genres":["Fighting","Sports"],"description":"Go for the gold, as you take on the Superstars of WCW and the NWO in Singles, Tag Team or Battle Royale competition! Set the stage - Fight in arenas from WCW's biggest events, including WCW Monday Nitro, Starrcade, and Halloween Havoc. Plus, TONS of hidden arenas, secret 'run-in' characters, Nitro theme music, and brawling in and out of the ring! Who's next? You are, when you step into the ring with WCW Nitro, the fastest wrestling game to hit your N64! Take control of over 60 WCW and NWO Superstars! Dozens of devastating moves per wrestler, including trademark maneuvers, taunts, and finishers!","descriptionSource":"http://www.gamefaqs.com/n64/199284-wcw-nitro","developer":"Inland Productions","coverName":"WCW Nitro (USA).n64","players":"4","publisher":"THQ","esrb":"E - Everyone","rating":{"score":2.56,"count":45}},{"id":"wcw-vs-nwo-world-tour","title":"WCW vs. nWo: World Tour","year":1997,"genres":["Fighting","Sports"],"description":"Over 40 wrestlers in all, including over 20 WCW and NWO superstars like Hollywood Hogan, Sting, The Giant, Lex Luger, Ric Flair, The Outsiders, and many more! Each wrestler is capable of performing 30 to 40 moves, including his own signature moves! Featuring five different gameplay modes, and Tag Team and simultaneous four-player action!","descriptionSource":"http://www.gamefaqs.com/n64/199286-wcw-vs-nwo-world-tour","developer":"Aki Corp.","coverName":"WCW vs. nWo - World Tour (USA).n64","players":"4","publisher":"THQ","esrb":"E - Everyone","rating":{"score":3.89,"count":96}},{"id":"wcw-nwo-revenge","title":"WCW-nWo Revenge","year":1998,"genres":["Fighting","Sports"],"description":"More than 60 wrestlers, including ALL of the top WCW and NWO superstars! Awesome new features including wrestler entrances, all the real WCW belts, hidden weapons, instant replay, completely updated roster and complete user stats and arcade style scores! Enjoy real pay-per-view arenas, 40-man Battle Royale mode, and a costume editing feature!","descriptionSource":"http://www.gamefaqs.com/n64/199288-wcw-nwo-revenge","developer":"Aki Corp.","coverName":"WCW-nWo Revenge (USA).n64","players":"4","publisher":"THQ","esrb":"E - Everyone","rating":{"score":4.17,"count":161}},{"id":"wetrix","title":"Wetrix","year":1998,"genres":["Puzzle"],"description":"A rainstorm so fierce, it will keep you from leaving your home for the next six months. Wetrix just might be the most addictive puzzle game of all time. Using randomly shaped 3D blocks as they fall from the sky, you must create a series of lakes and dams before the heavy rains appear. Because if the water drains, you lose! Sound simple? Well, mix in a few natural disasters and bomb attacks, and suddenly you need to muster all your strategy and skill to combat nature's fury!","descriptionSource":"http://www.gamefaqs.com/n64/199293-wetrix","developer":"Zed Two Limited","coverName":"Wetrix (USA) (En,Fr,De,Es,It,Nl).n64","players":"2","publisher":"Infogrames Entertainment","esrb":"E - Everyone","rating":{"score":3.62,"count":68}},{"id":"wheel-of-fortune","title":"Wheel of Fortune","year":1997,"genres":["Puzzle"],"description":"The hit TV game show comes to your Nintendo 64! Hosted by Vanna White, America's most popular game show hostess. Over 4,000 puzzles and 31 different categories. Speed Up, Jackpot, Tiebreaker and Bonus rounds. Stunning 3D environment. Exciting gameplay for up to three players.","descriptionSource":"http://www.gamefaqs.com/n64/915332-wheel-of-fortune","developer":"GameTek","coverName":"Wheel of Fortune (USA).n64","players":"3","publisher":"Take-Two Interactive Software","esrb":"E - Everyone","rating":{"score":2.75,"count":58}},{"id":"winback-covert-operations","title":"WinBack: Covert Operations","year":1999,"genres":["Shooter"],"description":"The first blast wiped out your Space Center. In just 3 hours, the hi-tech weapons satellite will strike again... It's your job to make sure that doesn't happen. Featuring intense third-person shooting action, precision laser-sighting aiming mechanism, immense 3D environments, battle heavily-armed boss characters and 'smart' enemies, 4-player Deathmatch, along with Lethal Tag, Cube Hunt, and Quick Draw.","descriptionSource":"http://www.gamefaqs.com/n64/199307-winback-covert-operations","developer":"Omega Force","coverName":"WinBack - Covert Operations (USA).n64","players":"4","publisher":"Koei","esrb":"T - Teen","rating":{"score":3.53,"count":88}},{"id":"wipeout-64","title":"Wipeout 64","year":1998,"genres":["Racing"],"description":"The fastest races. The deadliest weapons. The biggest name in anti-gravity racing descends on N64 with incredible new visual power and fully enhanced gameplay glory. With blistering races, challenges, time trials and a multiplay league, Wipeout 64 delivers pure racing devastation. Faster than you can imagine.","descriptionSource":"http://www.gamefaqs.com/n64/199316-wipeout-64","developer":"Psygnosis","coverName":"Wipeout 64 (USA).n64","players":"4","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.87,"count":115}},{"id":"world-cup-98","title":"World Cup 98","year":1998,"genres":["Sports"],"description":"Win the World - For Your Country! All 32 World Cup France 98 qualifying teams: Take your team, with all your favorite players, to the World Cup Final and win it all. NEW! World Cup Classics: Play 8 of the all-time most thrilling World Cup Final matches. NEW! On-the-fly in-game management: Alter attacking strategy and formation at the press of a button. NEW! On-the-fly in-game tactics: Run preset plays at critical points in the game.","descriptionSource":"http://www.gamefaqs.com/n64/199325-world-cup-98","developer":"EA Canada","coverName":"World Cup 98 (USA) (En,Fr,De,Es,It,Nl,Sv,Da).n64","players":"4","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.43,"count":53}},{"id":"world-driver-championship","title":"World Driver Championship","year":1999,"genres":["Racing"],"description":"Your passport to racing! Develop a racing career as you compete for job offers with each of the 15 World Driver Teams. Ten tracks located throughout the world. 20 challenging events spread across two different levels of competition. Over 30 highly detailed, exotic cars with realistic physics and handling! Race head-to-head in two-player split-screen mode. Save replay on the Contoller Pak to analyze your driving skills from multiple camera angles.","descriptionSource":"http://www.gamefaqs.com/n64/189710-world-driver-championship","developer":"Boss Game Studios","coverName":"World Driver Championship (USA).n64","players":"2","publisher":"Midway Home Entertainment","esrb":"E - Everyone","rating":{"score":3.44,"count":66}},{"id":"worms-armageddon","title":"Worms Armageddon","year":2000,"genres":["Strategy"],"description":"'Dis ain't no fishing game. The ultimate test of strategy pits worm vs. worm throughout 44 missions for 1 - 4 players. Ignite 41 special weapons, like highly flammable old ladies, bouncy banana bombs, and flying sheep, as you inch your way to victory. Devise wickedly ingenious strategies so that your army of worms can wipe THEIR army of worms right off the planet! Over-the-top action and an endless supply of multi-player modes make Worms Armageddon the perfect strategy game!","descriptionSource":"http://www.gamefaqs.com/n64/199339-worms-armageddon","developer":"Infogrames","coverName":"Worms Armageddon (USA) (En,Fr,Es).n64","players":"4","publisher":"Infogrames Europe","esrb":"E - Everyone","rating":{"score":3.61,"count":75}},{"id":"wwf-attitude","title":"WWF Attitude","year":1999,"genres":["Fighting","Sports"],"description":"Now featuring over 40 of your favorite WWF superstars! Customize your own wrestler's move sets and costumes. Over 20 game modes including all-new specialty matches. Real-life WWF entrances and theme songs. Wrestle your way to the title in an all-new career mode. First ever Create-Your-Own Pay-Per-View Mode! Two-man commentary featuring Shane McMahon and Jerry 'The King' Lawler.","descriptionSource":"http://www.gamefaqs.com/n64/199344-wwf-attitude","developer":"Iguana Entertainment","coverName":"WWF Attitude (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"T - Teen","rating":{"score":3.16,"count":68}},{"id":"wwf-no-mercy","title":"WWF No Mercy","year":2000,"genres":["Fighting","Sports"],"description":"Jump into the ring with the biggest, baddest jambronis around and experience brutal WWF action never before seen in a console game! Over 65 WWF superstars, all-new Ladder matches, and all-new Double-Team moves, like the Dudley 3D Deathdrop! Take on the entire Federation in Survival Mode. Take the action out of the ring in 10 different backstage areas!","descriptionSource":"http://www.gamefaqs.com/n64/914112-wwf-no-mercy","developer":"Aki Corp.","coverName":"WWF No Mercy (USA).n64","players":"4","publisher":"THQ","esrb":"T - Teen","rating":{"score":4.36,"count":203}},{"id":"wwf-war-zone","title":"WWF War Zone","year":1998,"genres":["Fighting","Sports"],"description":"WWF WARZONE is here for your N64, featuring the top superstars in the World Wrestling Federation! Signature and finishing moves unique to each wrestler. Specialized matches including Steel Cage Match. Four-player action with Tag Team, Tornado, War, and Training Modes! Over 300 motion captured maneuvers. Create and save up to 30 customized wrestlers!","descriptionSource":"http://www.gamefaqs.com/n64/199350-wwf-war-zone","developer":"Iguana Entertainment","coverName":"WWF War Zone (USA).n64","players":"4","publisher":"Acclaim Entertainment","esrb":"T - Teen","rating":{"score":3.19,"count":57}},{"id":"wwf-wrestlemania-2000","title":"WWF WrestleMania 2000","year":1999,"genres":["Fighting","Sports"],"description":"The greatest wrestling game ever created! Tons of game modes, including Cage Match, Road to Wrestlemania, Create a PPV, and more! Create and bet WWF Championship belts with your friends. Over 50 of the top WWF superstars, more than any other WWF game! Thousands of signature moves, taunts, and mannerisms. New Create a Wrestler, with custom moves, costumes, and fighting styles!","descriptionSource":"http://www.gamefaqs.com/n64/199352-wwf-wrestlemania-2000","developer":"Aki Corp.","coverName":"WWF WrestleMania 2000 (USA).n64","players":"4","publisher":"THQ","esrb":"T - Teen","rating":{"score":4.04,"count":128}},{"id":"xena-warrior-princess","title":"Xena: Warrior Princess","year":1999,"genres":["Fighting"],"description":"Xena shall choose the defenders of the world. We have seen them in the memories of her exploits. So come together, Earth's greatest heroes and villains. Choose your weapons wisely and let the battles begin! Just remember, each victory only brings you closer to challenging the embodiment of darkness... Despair himself! Each of Xena's 10 characters possess their own unique weapons, attitudes and fighting techniques. Exclusive multi-player feature includes a roster mode, plus team and single battles.","descriptionSource":"http://www.gamefaqs.com/n64/199364-xena-warrior-princess-the-talisman-of-fate","developer":"Saffire","coverName":"Xena - Warrior Princess - The Talisman of Fate (Europe).n64","players":"4","publisher":"Titus Software","esrb":"T - Teen","rating":{"score":3.38,"count":77}},{"id":"xena-warrior-princess-the-talisman-of-fate","title":"Xena: Warrior Princess: The Talisman of Fate","year":1999,"genres":["Fighting"],"description":"Xena shall choose the defenders of the world. We have seen them in the memories of her exploits. So come together, Earth's greatest heroes and villains. Choose your weapons wisely and let the battles begin! Just remember, each victory only brings you closer to challenging the embodiment of darkness... Despair himself! Each of Xena's 10 characters possess their own unique weapons, attitudes and fighting techniques. Exclusive multi-player feature includes a roster mode, plus team and single battles.","descriptionSource":"http://www.gamefaqs.com/n64/199364-xena-warrior-princess-the-talisman-of-fate","developer":"Saffire","coverName":"Xena - Warrior Princess - The Talisman of Fate (USA).n64","players":"4","publisher":"Titus Software","esrb":"T - Teen","rating":{"score":3.38,"count":77}},{"id":"yoshi-s-story","title":"Yoshi's Story","year":1998,"genres":["Platformer"],"description":"Baby Bowser has taken the Super Happy Tree and cast a spell on Yoshi's world, turning it into the pages of a picture book. The only Yoshis not affected by the spell were six hatchlings that were still protected by their shells. It's up to them to reclaim the Super Happy Tree and restore happiness to the world. That is the only thing that can break Baby Bowser's spell!","descriptionSource":"http://www.gamefaqs.com/n64/199386-yoshis-story","developer":"Nintendo","coverName":"Yoshi's Story (USA) (En,Ja).n64","players":"1","publisher":"Nintendo","esrb":"E - Everyone","rating":{"score":3.9,"count":303}}];
